INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C1','soc',4,1,'u2',1,'국가유산의 뜻과 종류 — 국가유산 = 조상 대대로 전해 내려온, 보존할 가치가 있는 것(예전 이름 문화재) · 과거와 현재를 이어 줌 · 형태가 있으면 문화유산(석탑·도자기·기와집), 형태가 없으면 무형유산(판소리·탈춤·김장) · 옛 그림(서당·씨름)처럼 옛사람들의 생활과 생각이 담김 · 소중히 여기고 보존',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C2','soc',4,1,'u2',2,'국가유산의 가치 — 가치 = 국가유산에 담긴 소중함과 뜻 · 역사적(오래 전해 옴)·과학적(슬기로운 원리)·심미적(아름다움)·생태환경적(자연과 어울림) · 한옥 온돌·마루 = 과학적, 처마 곡선 = 심미적, 나무·흙·돌 재료 = 생태환경적 · 김장 함께 담가 나누며 세대 전승 = 역사적, 땅속 김칫독 = 과학적 · 하나에 여러 가치 · 유네스코 인류무형문화유산 = 세계가 가치를 인정 · 가치를 알면 보존하려는 마음',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C3','soc',4,1,'u2',3,'우리 지역 국가유산 조사 방법 — 조사 = 사실을 찾아 확인하는 일, 특징과 가치를 알게 됨 · 책·백과사전 · 누리집 검색 · 문화유산 해설사께 여쭤보기 · 답사(직접 찾아가기 — 계획을 세우고 촬영 가능한 곳인지 확인) · 여러 방법을 함께 쓰면 더 정확하고 자세 · 조사 뒤 정리해 특징과 가치 알기',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C4','soc',4,1,'u2',4,'조사한 국가유산 정리하기 — 기본 정보(분류·있는 곳·시대) + 특징 + 가치 · 특징 = 있는 그대로의 사실 · 가치 = 특징을 바탕으로 추론 · 그대로 베끼지 말고 담긴 뜻을 생각해 정리 · 모둠과 나누기(말하는 사람은 또렷하게, 듣는 사람은 집중해 듣고 새로 안 것 적기, 질문은 이야기가 끝난 뒤) · 정리하는 까닭 = 특징과 가치를 알고 소중함 느끼기',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C5','soc',4,1,'u2',5,'조상들의 생활 모습 표현하기 — 공연하기(노래·춤 — 강강술래) · 가상 일기 쓰기(옛사람이 되어) · 역할놀이(대본·옛 장면 연기) · 그림·만화 · 조사한 역사적 사실을 토대로 상상을 더함 · 표현하면 국가유산을 알리고 가치를 이해하며 지역에 자긍심 · 해녀의 물질·노래도 세대를 이어 전해진 무형유산',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C6','soc',4,1,'u2',6,'주제① 생각 펼치기 — 미래의 국가유산 = 미래에도 소중한 가치가 있을지 생각해 정함(새것·비싼 것·좋아하는 것이 기준이 아님) · 국가유산 안내판 = 소개할 국가유산을 정해 특징과 가치를 조사해 담음 · 주제① = 의미·종류·가치를 알고 조사·정리·표현',ARRAY['[4사06-01] 국가유산의 의미·종류·가치를 알고 우리 지역의 국가유산을 조사·정리·표현한다(차시 머리 표기 · 문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C7','soc',4,1,'u2',7,'우리 지역의 역사를 알 수 있는 장소 — 박물관 = 유물·자료를 모아 보관·전시 · 기념관 = 인물이나 사건을 오래 기억하려고 만든 곳 · 유적지 = 옛사람들의 흔적(유적)이 남은 곳 · 셋 다 지역의 역사를 알려 줌 · 기념관이 그 지역에 있는 까닭 = 인물과 지역의 인연 · 유물 = 옛사람이 쓰다가 남긴 물건 · 신문 기사·검색·답사로 찾음 · 박물관은 모형·영상 등 여러 방법으로 역사를 알림',ARRAY['[4사06-02] 우리 지역의 역사를 알 수 있는 장소를 찾아 역사를 조사·소개하고 보존하려는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C8','soc',4,1,'u2',8,'우리 지역의 역사 조사하기 — 조사 계획 세우기 → 조사하기 → 조사 보고서 쓰기 · 인터넷 조사(누리집 검색)·문헌 조사(책·기록물)·답사(직접 찾아가기)·면담 조사(여쭤보기), 여러 방법을 함께 · 계획서 = 주제·장소·내용·방법·역할 나누기·준비물·주의할 점 · 인터넷 정보는 믿을 만한지 확인 · 가상 현실 전시 · 답사는 보호자와 함께·안전 · 보고서 = 주제·장소·방법·내용 + 알게 된 점·느낀 점, 그대로 베끼지 않고 내 말로',ARRAY['[4사06-02] 우리 지역의 역사를 알 수 있는 장소를 찾아 역사를 조사·소개하고 보존하려는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C9','soc',4,1,'u2',9,'우리 지역의 역사 소개하기 — 동영상(촬영 → 편집 도구 고르기 → 역사적 특징이 드러나게 편집 → 소개, 움직임과 소리로 생생) · 안내 책자(내용 정하기 → 그림·사진 → 역사적 특징, 자세) · 역사 인물 신문(신문 제목 → 기사 제목 → 그림·사진·글, 퀴즈·인터뷰) · 사진전(설명을 붙여 전시, 모은 사진은 출처 표시) · 조사 보고서 · 우리 반 역사 박물관 · 듣는 사람이 이해하기 쉽게, 다른 모둠 자료도 관심 있게 관람 · 큐레이터(학예사) · 자긍심',ARRAY['[4사06-02] 우리 지역의 역사를 알 수 있는 장소를 찾아 역사를 조사·소개하고 보존하려는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C10','soc',4,1,'u2',10,'우리 지역의 역사 보존하기 — 보존 = 잘 보살피고 지켜서 계속 남아 있게 하는 것 · 문제: 무형유산을 이을 사람이 없어 사라질 위기, 국가유산 훼손 · 보존하지 않으면 전통이 끊기고 다음 세대에 전해지지 못함 · 지역의 노력: 관리·보존, 유네스코 지정 노력(재정·기술 지원), 무형유산 알리는 행사 · 우리의 실천: 관심 갖고 공부하기, 지킴이·봉사 활동, 널리 알리기 · 역사는 다음 세대를 위한 것',ARRAY['[4사06-02] 우리 지역의 역사를 알 수 있는 장소를 찾아 역사를 조사·소개하고 보존하려는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u2-C11','soc',4,1,'u2',11,'주제② 생각 펼치기 — 역사 체험 프로그램 = 역사적으로 의미 있는 장소 정하기 → 역사적 특징 조사 → 체험 프로그램 만들기 · 역사가 담긴 캐릭터 = 사건·장소 정하기 → 특징 조사 → 어울리는 캐릭터와 이름 · 주제② = 장소 → 조사 → 소개 → 보존 · 보존은 어린이도 함께',ARRAY['[4사06-02] 우리 지역의 역사를 알 수 있는 장소를 찾아 역사를 조사·소개하고 보존하려는 태도를 기른다(차시 머리 표기 · 문구 초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X01','soc',4,'u2',ARRAY['SO4-1-u2-C1']::text[],'국가유산을 아무 옛 물건이나 새로 만든 물건쯤으로 여겨, 조상 대대로 전해 온 보존할 가치가 있는 것이라는 뜻을 놓친다','전해 내려온 · 소중한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X02','soc',4,'u2',ARRAY['SO4-1-u2-C1']::text[],'형태가 있는 것만 국가유산이라고 여겨 소리·춤·솜씨로 전해 오는 무형유산을 놓친다','형태가 없어도 국가유산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X03','soc',4,'u2',ARRAY['SO4-1-u2-C1']::text[],'문화유산과 무형유산을 바꾸어 나눈다(솜씨로 만든 먹을거리를 보고 문화유산이라고 하는 등)','형태 있음 = 문화유산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X04','soc',4,'u2',ARRAY['SO4-1-u2-C1']::text[],'국가유산이나 옛 그림에서 옛사람들의 생활과 생각을 알 수 있다는 것을 놓친다','옛사람의 삶이 담겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X05','soc',4,'u2',ARRAY['SO4-1-u2-C2','SO4-1-u2-C6']::text[],'국가유산의 가치를 가격·크기·새로움 같은 것으로 여긴다','가치 = 소중함과 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X06','soc',4,'u2',ARRAY['SO4-1-u2-C2']::text[],'역사적·과학적·심미적·생태환경적 가치를 서로 바꾸어 짝짓는다','오래 전해 옴 · 슬기 · 아름다움 · 자연') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X07','soc',4,'u2',ARRAY['SO4-1-u2-C2']::text[],'하나의 국가유산에는 한 가지 가치만 담긴다고 여긴다','여러 가치가 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X08','soc',4,'u2',ARRAY['SO4-1-u2-C2','SO4-1-u2-C10']::text[],'유네스코 등재·지정의 뜻을 잘못 안다(곧 사라진다, 값이 오른다, 아무도 못 본다고 여기는 등)','세계가 가치를 인정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X09','soc',4,'u2',ARRAY['SO4-1-u2-C3','SO4-1-u2-C8']::text[],'조사 방법의 이름과 하는 일을 바꾸어 안다(직접 찾아가는 것을 누리집 조사라고 하는 등)','직접 찾아가기 = 답사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X10','soc',4,'u2',ARRAY['SO4-1-u2-C3','SO4-1-u2-C8']::text[],'조사를 사실을 찾아 확인하는 일로 보지 않고, 지어내거나 들은 대로 적어도 된다고 여긴다','조사 = 사실 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X11','soc',4,'u2',ARRAY['SO4-1-u2-C3','SO4-1-u2-C8']::text[],'조사 방법은 한 가지만 쓰면 충분하다고 여긴다','여러 방법이 서로 보태져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X12','soc',4,'u2',ARRAY['SO4-1-u2-C3','SO4-1-u2-C8']::text[],'답사를 준비 없이 가거나 촬영 가능 여부·보호자·안전을 살피지 않는다','계획 · 촬영 확인 · 안전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X13','soc',4,'u2',ARRAY['SO4-1-u2-C4']::text[],'특징과 가치를 헷갈린다(헤아린 가치를 특징으로, 사실을 가치로 여기는 등)','특징 = 사실 · 가치 = 추론') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X14','soc',4,'u2',ARRAY['SO4-1-u2-C4','SO4-1-u2-C8']::text[],'찾은 내용을 그대로 베끼거나 친구 것을 옮겨 적어도 정리라고 여긴다','뜻을 생각해 내 말로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X15','soc',4,'u2',ARRAY['SO4-1-u2-C4']::text[],'국가유산의 기본 정보(분류·있는 곳·시대)가 아닌 것을 기본 정보로 여긴다','분류 · 있는 곳 · 시대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X16','soc',4,'u2',ARRAY['SO4-1-u2-C4','SO4-1-u2-C9']::text[],'발표나 소개를 듣고 말할 때 끼어들거나 딴짓하는 등 바르지 않은 태도를 고른다','집중해서 듣고 또렷하게 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X17','soc',4,'u2',ARRAY['SO4-1-u2-C5']::text[],'표현할 때 역사적 사실 없이 상상만으로 지어내도 된다고 여긴다','사실 위에 상상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X18','soc',4,'u2',ARRAY['SO4-1-u2-C5','SO4-1-u2-C9']::text[],'표현·소개 방법의 이름과 하는 일을 바꾸어 알거나, 표현이 아닌 활동을 표현 방법으로 여긴다','공연 · 가상 일기 · 역할놀이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X19','soc',4,'u2',ARRAY['SO4-1-u2-C5','SO4-1-u2-C9']::text[],'표현하고 소개하는 활동이 재미일 뿐 국가유산을 알리고 가치를 이해하는 일과 관계없다고 여긴다','알리고 · 이해하고 · 자긍심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X20','soc',4,'u2',ARRAY['SO4-1-u2-C6']::text[],'미래의 국가유산을 가장 새것·비싼 것·내가 좋아하는 것으로 정한다','미래에도 소중한 가치가 있을지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X21','soc',4,'u2',ARRAY['SO4-1-u2-C7']::text[],'박물관·기념관·유적지가 어떤 곳인지 서로 바꾸어 안다','전시 · 기억 · 흔적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X22','soc',4,'u2',ARRAY['SO4-1-u2-C7','SO4-1-u2-C11']::text[],'지역의 역사와 관계없는 곳(놀이공원·백화점 등)을 역사를 알 수 있는 장소로 여긴다','역사가 담긴 곳인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X23','soc',4,'u2',ARRAY['SO4-1-u2-C7']::text[],'기념관이 그 지역에 있는 까닭을 건물·교통·땅값에서 찾고, 인물·사건과 지역의 인연을 놓친다','그 지역과의 인연') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X24','soc',4,'u2',ARRAY['SO4-1-u2-C8','SO4-1-u2-C11']::text[],'조사나 만들기의 차례를 바꾼다(계획 없이 조사하거나 보고서를 먼저 쓰는 등)','계획 → 조사 → 보고서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X25','soc',4,'u2',ARRAY['SO4-1-u2-C8','SO4-1-u2-C11']::text[],'조사 계획서와 조사 보고서에 쓸 내용을 바꾸어 안다(알게 된 점·느낀 점을 계획서에 쓰는 등)','알게 된 점·느낀 점 = 보고서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X26','soc',4,'u2',ARRAY['SO4-1-u2-C8']::text[],'인터넷에서 찾은 정보는 모두 믿을 수 있다고 여긴다','믿을 만한지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X27','soc',4,'u2',ARRAY['SO4-1-u2-C9']::text[],'다른 곳에서 모은 사진·그림을 출처 없이 쓰거나 내 것처럼 쓴다','출처 표시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X28','soc',4,'u2',ARRAY['SO4-1-u2-C9']::text[],'소개 자료를 만드는 차례나 자료마다의 좋은 점을 바꾸어 안다','동영상 = 촬영부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X29','soc',4,'u2',ARRAY['SO4-1-u2-C3','SO4-1-u2-C9']::text[],'문화유산 해설사·큐레이터 같은 사람이 하는 일을 바꾸어 안다','안내 · 전시 기획') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X30','soc',4,'u2',ARRAY['SO4-1-u2-C10']::text[],'보존을 새것으로 바꾸기·숨겨 두기·가져가기처럼 잘못 여긴다','보살피고 지켜 남게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X31','soc',4,'u2',ARRAY['SO4-1-u2-C10','SO4-1-u2-C11']::text[],'보존은 어른이나 지역(군·나라)만 하는 일이라고 여긴다','어린이도 할 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X32','soc',4,'u2',ARRAY['SO4-1-u2-C10']::text[],'훼손·이을 사람 부족을 문제로 보지 않거나, 그대로 두어도 역사가 저절로 이어진다고 여긴다','두면 사라지고 끊겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u2-X33','soc',4,'u2',ARRAY['SO4-1-u2-C11','SO4-1-u2-C6']::text[],'체험 프로그램·캐릭터·안내판을 장소나 국가유산의 특징을 조사하지 않고 마음대로 만든다','특징을 조사해 담아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#1','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',1,'mc','auto','조상 대대로 전해 내려온, 보존할 가치가 있는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"mc","stem":"조상 대대로 전해 내려온, 보존할 가치가 있는 것을 무엇이라고 하나요?","options":[{"t":"국가유산","correct":true},{"t":"새로 산 물건","mis":"SO4-1-u2-X01"},{"t":"기념품","mis":"SO4-1-u2-X01"},{"t":"장난감","mis":"SO4-1-u2-X01"}],"explanation":["조상에게서 왔어요.","보존할 가치가 있어요.","국가유산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#2','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',1,'sa','auto','국가유산은 예전에 무엇이라고 불렀나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"sa","stem":"국가유산은 예전에 무엇이라고 불렀나요? 세 글자로 쓰세요.","answer":["문화재"],"explanation":["지금 이름은 국가유산이에요.","예전 이름은 문화◯예요.","문화재예요."],"mis":"SO4-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#3','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',1,'ox','auto','판소리처럼 형태가 없는 것도 국가유산이 될 수 있어요.',ARRAY['SO4-1-u2-X02']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"ox","stem":"판소리처럼 형태가 없는 것도 국가유산이 될 수 있어요.","answer":"O","reason_options":[{"t":"소리·춤·솜씨처럼 형태 없이 전해 오는 무형유산도 있기 때문에","correct":true},{"t":"눈으로 보고 만질 수 있는 것만 국가유산이기 때문에","mis":"SO4-1-u2-X02"}],"mis":"SO4-1-u2-X02","explanation":["판소리는 소리예요.","형태가 없어도 전해 와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#4','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',1,'mc','auto','석탑·도자기·기와집처럼 형태가 있는 국가유산을 무엇이라고 하나요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X01']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"mc","stem":"석탑·도자기·기와집처럼 형태가 있는 국가유산을 무엇이라고 하나요?","options":[{"t":"문화유산","correct":true},{"t":"무형유산","mis":"SO4-1-u2-X03"},{"t":"미래유산","mis":"SO4-1-u2-X01"},{"t":"기념품","mis":"SO4-1-u2-X01"}],"explanation":["형태가 있어요.","눈으로 보고 만져요.","문화유산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#5','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',2,'mc','auto','카드 가운데 형태가 없는 국가유산끼리 바르게 묶은 것은 무엇인가요?',ARRAY['SO4-1-u2-X03']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"mc","stem":"카드 가운데 형태가 없는 국가유산끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"판소리 · 탈춤 · 김장","correct":true},{"t":"석탑 · 도자기 · 기와집","mis":"SO4-1-u2-X03"},{"t":"판소리 · 석탑 · 김장","mis":"SO4-1-u2-X03"},{"t":"도자기 · 탈춤 · 기와집","mis":"SO4-1-u2-X03"}],"explanation":["소리·춤·솜씨를 찾아요.","만질 수 없어요.","판소리·탈춤·김장이에요."],"asset":{"type":"passage","lines":["석탑 — 돌을 층층이 쌓아 만든 탑","도자기 — 흙을 빚어 구운 그릇","판소리 — 이야기를 노래로 부르는 소리","탈춤 — 탈을 쓰고 추는 춤","기와집 — 기와를 얹은 옛날식 집","김장 — 겨울 김치를 함께 담그는 솜씨"],"title":"솔빛반이 모은 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#6','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',2,'mc','auto','그림 ㉮를 보고 알 수 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X04','SO4-1-u2-X05']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"mc","stem":"그림 ㉮를 보고 알 수 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날에도 선생님 앞에서 아이들이 공부했어요","correct":true},{"t":"옛날에는 아이들이 공부하지 않았어요","mis":"SO4-1-u2-X04"},{"t":"그림을 그린 날의 날씨","mis":"SO4-1-u2-X04"},{"t":"그림의 가격","mis":"SO4-1-u2-X05"}],"explanation":["서당 그림이에요.","아이들이 책을 읽어요.","옛날에도 공부했어요."],"asset":{"type":"passage","lines":["㉮ 서당 그림 — 훈장님 앞에 아이들이 둘러앉아 책을 읽는다.","㉯ 씨름 그림 — 두 사람이 샅바를 잡고 겨루고, 둘레에서 사람들이 구경한다."],"title":"옛사람들이 그린 두 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#7','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',2,'ox','auto','국가유산은 옛날 것이라 오늘날의 우리와는 관계가 없어요.',ARRAY['SO4-1-u2-X01']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"ox","stem":"국가유산은 옛날 것이라 오늘날의 우리와는 관계가 없어요.","answer":"X","reason_options":[{"t":"국가유산은 과거와 현재를 이어 주며 옛사람들의 삶을 알려 주기 때문에","correct":true},{"t":"옛날 것은 지금 쓸모가 없기 때문에","mis":"SO4-1-u2-X01"}],"mis":"SO4-1-u2-X01","explanation":["옛날부터 전해 왔어요.","오늘날까지 이어져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#8','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',2,'match','auto','카드의 국가유산을 알맞은 칸에 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"match","stem":"카드의 국가유산을 알맞은 칸에 이으세요.","pairs":[{"l":"도자기","r":"형태가 있는 문화유산"},{"l":"탈춤","r":"형태가 없는 무형유산"}],"mis":"SO4-1-u2-X03","explanation":["도자기는 그릇이에요.","탈춤은 춤이에요.","형태로 나눠요."],"asset":{"type":"passage","lines":["석탑 — 돌을 층층이 쌓아 만든 탑","도자기 — 흙을 빚어 구운 그릇","판소리 — 이야기를 노래로 부르는 소리","탈춤 — 탈을 쓰고 추는 춤","기와집 — 기와를 얹은 옛날식 집","김장 — 겨울 김치를 함께 담그는 솜씨"],"title":"솔빛반이 모은 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#9','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',2,'blank','auto','국가유산은 눈으로 보고 만질 수 있는지, 곧 (    )이/가 있는지에 따라 둘로 나눌 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"blank","stem":"국가유산은 눈으로 보고 만질 수 있는지, 곧 (    )이/가 있는지에 따라 둘로 나눌 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"형태","correct":true},{"t":"가격","mis":"SO4-1-u2-X05"},{"t":"나이","mis":"SO4-1-u2-X01"},{"t":"주인","mis":"SO4-1-u2-X01"}],"explanation":["보고 만질 수 있나요?","모양이 있나요?","형태예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_basic#10','soc',4,1,'u2','L01','g4_1_soc_u2_L01_basic','lesson_basic','SO4-1-u2-C1',3,'mc','auto','김장이 무형유산인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X02','SO4-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"mc","stem":"김장이 무형유산인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"김치를 담그는 솜씨가 사람에게서 사람으로 전해 오기 때문이에요","correct":true},{"t":"김치는 눈으로 볼 수 있기 때문이에요","mis":"SO4-1-u2-X03"},{"t":"겨울에만 하는 일이기 때문이에요","mis":"SO4-1-u2-X02"},{"t":"새로 생긴 음식이기 때문이에요","mis":"SO4-1-u2-X01"}],"explanation":["김장은 솜씨예요.","솜씨는 형태가 없어요.","그래서 무형유산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
