INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#4','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',3,'mc','auto','석탑과 판소리를 같은 칸에 넣지 않는 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X02','SO4-1-u2-X03']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"mc","stem":"석탑과 판소리를 같은 칸에 넣지 않는 까닭은 무엇인가요?","options":[{"t":"석탑은 형태가 있고 판소리는 형태가 없기 때문이에요","correct":true},{"t":"석탑이 판소리보다 더 오래되었기 때문이에요","mis":"SO4-1-u2-X05"},{"t":"판소리는 국가유산이 아니기 때문이에요","mis":"SO4-1-u2-X02"},{"t":"석탑은 무형유산이기 때문이에요","mis":"SO4-1-u2-X03"}],"explanation":["석탑은 돌탑이에요.","판소리는 소리예요.","형태가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#5','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',3,'mc','auto','옛 그림이나 국가유산을 보고 알 수 있는 것을 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u2-X04','SO4-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"mc","stem":"옛 그림이나 국가유산을 보고 알 수 있는 것을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"옛사람들이 어떻게 살고 무엇을 생각했는지","correct":true},{"t":"미래에 일어날 일","mis":"SO4-1-u2-X04"},{"t":"오늘 물건의 가격","mis":"SO4-1-u2-X05"},{"t":"다른 나라의 지도","mis":"SO4-1-u2-X04"}],"explanation":["옛것이에요.","옛사람의 생활이 담겼어요.","삶과 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#6','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',3,'ox','auto','손을 맞잡고 원을 그리며 노래하는 강강술래는 형태가 없는 국가유산이에요.',ARRAY['SO4-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"ox","stem":"손을 맞잡고 원을 그리며 노래하는 강강술래는 형태가 없는 국가유산이에요.","answer":"O","reason_options":[{"t":"노래와 춤으로 사람에게서 사람으로 전해 오기 때문에","correct":true},{"t":"손으로 만질 수 없으면 국가유산이 아니기 때문에","mis":"SO4-1-u2-X02"}],"mis":"SO4-1-u2-X02","explanation":["강강술래는 노래와 춤이에요.","형태가 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#7','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',3,'mc','auto','국가유산이 과거와 현재를 이어 준다는 말의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X01','SO4-1-u2-X05']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"mc","stem":"국가유산이 과거와 현재를 이어 준다는 말의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날부터 오늘날까지 전해 와 옛사람들의 삶을 알려 준다는 뜻이에요","correct":true},{"t":"옛날 물건을 오늘날 새것으로 바꾼다는 뜻이에요","mis":"SO4-1-u2-X01"},{"t":"과거에만 쓰고 지금은 쓰지 않는다는 뜻이에요","mis":"SO4-1-u2-X01"},{"t":"옛날과 오늘날의 가격을 견준다는 뜻이에요","mis":"SO4-1-u2-X05"}],"explanation":["옛날부터 전해 왔어요.","오늘날 우리가 만나요.","삶을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#8','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',4,'essay','teacher','국가유산이 무엇인지 쓰고, 문화유산과 무형유산의 예를 하나씩 들어 둘이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C1","difficulty":4,"kind":"essay","stem":"국가유산이 무엇인지 쓰고, 문화유산과 무형유산의 예를 하나씩 들어 둘이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 국가유산은 조상 대대로 전해 내려온, 보존할 가치가 있는 것이에요. 석탑은 눈으로 보고 만질 수 있는 문화유산이고, 판소리는 형태 없이 소리로 전해 오는 무형유산이에요.","scoring_points":["국가유산의 뜻을 썼는가","문화유산과 무형유산의 예를 하나씩 바르게 들었는가","형태가 있는지 없는지로 차이를 썼는가"]},"explanation":["뜻을 먼저 써요.","예를 들어요.","형태로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#9','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',4,'mc','auto','카드에 「짚신을 삼는 솜씨」를 더하려고 해요. 어느 칸에 넣어야 하고 그 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X02','SO4-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":4,"kind":"mc","stem":"카드에 「짚신을 삼는 솜씨」를 더하려고 해요. 어느 칸에 넣어야 하고 그 까닭은 무엇인가요?","options":[{"t":"무형유산 칸 — 짚신이 아니라 짚신을 삼는 솜씨가 전해 오는 것이라서","correct":true},{"t":"문화유산 칸 — 짚신은 손으로 만질 수 있어서","mis":"SO4-1-u2-X03"},{"t":"어느 칸에도 넣을 수 없어요 — 형태가 없어서","mis":"SO4-1-u2-X02"},{"t":"문화유산 칸 — 오래된 것은 모두 문화유산이라서","mis":"SO4-1-u2-X01"}],"explanation":["무엇이 전해 오나요?","솜씨예요.","솜씨는 형태가 없어요."],"asset":{"type":"passage","lines":["석탑 — 돌을 층층이 쌓아 만든 탑","도자기 — 흙을 빚어 구운 그릇","판소리 — 이야기를 노래로 부르는 소리","탈춤 — 탈을 쓰고 추는 춤","기와집 — 기와를 얹은 옛날식 집","김장 — 겨울 김치를 함께 담그는 솜씨"],"title":"솔빛반이 모은 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L01_challenge#10','soc',4,1,'u2','L01','g4_1_soc_u2_L01_challenge','lesson_challenge','SO4-1-u2-C1',4,'essay','teacher','그림 ㉮와 ㉯ 가운데 하나를 골라 그 그림으로 알 수 있는 옛사람들의 생활을 쓰고, 국가유산을 소중히 여겨야 하는 까닭과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C1","difficulty":4,"kind":"essay","stem":"그림 ㉮와 ㉯ 가운데 하나를 골라 그 그림으로 알 수 있는 옛사람들의 생활을 쓰고, 국가유산을 소중히 여겨야 하는 까닭과 이어 쓰세요.","answer_guide":{"answer":"예: 그림 ㉯를 보면 옛사람들도 씨름을 하며 함께 놀고 구경했다는 것을 알 수 있어요. 이렇게 국가유산에는 옛사람들의 생활과 생각이 담겨 있어 옛날을 이해할 수 있으니, 소중히 여기고 보존해 다음 세대에 물려줘야 해요.","scoring_points":["그림 하나를 골랐는가","그림으로 알 수 있는 생활 모습을 썼는가","소중히 여겨야 하는 까닭과 이어 썼는가"]},"explanation":["그림을 골라요.","생활 모습을 찾아요.","까닭과 이어요."],"asset":{"type":"passage","lines":["㉮ 서당 그림 — 훈장님 앞에 아이들이 둘러앉아 책을 읽는다.","㉯ 씨름 그림 — 두 사람이 샅바를 잡고 겨루고, 둘레에서 사람들이 구경한다."],"title":"옛사람들이 그린 두 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#1','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',1,'mc','auto','국가유산에 담긴 소중함과 뜻을 무엇이라고 하나요?',ARRAY['SO4-1-u2-X05']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"mc","stem":"국가유산에 담긴 소중함과 뜻을 무엇이라고 하나요?","options":[{"t":"가치","correct":true},{"t":"가격","mis":"SO4-1-u2-X05"},{"t":"무게","mis":"SO4-1-u2-X05"},{"t":"크기","mis":"SO4-1-u2-X05"}],"explanation":["값이 아니에요.","소중함과 뜻이에요.","가치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#2','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',1,'sa','auto','아름다움에 관한 가치를 ○○○ 가치라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"sa","stem":"아름다움에 관한 가치를 ○○○ 가치라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["심미적"],"explanation":["아름다움이에요.","심◯◯이에요.","심미적 가치예요."],"mis":"SO4-1-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#3','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',1,'ox','auto','하나의 국가유산에 여러 가지 가치가 함께 담기기도 해요.',ARRAY['SO4-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"ox","stem":"하나의 국가유산에 여러 가지 가치가 함께 담기기도 해요.","answer":"O","reason_options":[{"t":"한옥처럼 슬기·아름다움·자연과의 어울림이 함께 담긴 국가유산이 있기 때문에","correct":true},{"t":"국가유산마다 가치는 꼭 한 가지뿐이기 때문에","mis":"SO4-1-u2-X07"}],"mis":"SO4-1-u2-X07","explanation":["한옥을 떠올려요.","가치가 여럿이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#4','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',1,'mc','auto','한옥의 온돌과 마루에서 알 수 있는 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"mc","stem":"한옥의 온돌과 마루에서 알 수 있는 가치는 무엇인가요?","options":[{"t":"과학적 가치","correct":true},{"t":"심미적 가치","mis":"SO4-1-u2-X06"},{"t":"생태환경적 가치","mis":"SO4-1-u2-X06"},{"t":"가격의 가치","mis":"SO4-1-u2-X05"}],"explanation":["겨울엔 따뜻해요.","여름엔 시원해요.","슬기로운 과학적 가치예요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#5','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',2,'mc','auto','한옥의 처마에서 알 수 있는 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"mc","stem":"한옥의 처마에서 알 수 있는 가치는 무엇인가요?","options":[{"t":"심미적 가치","correct":true},{"t":"과학적 가치","mis":"SO4-1-u2-X06"},{"t":"역사적 가치","mis":"SO4-1-u2-X06"},{"t":"크기의 가치","mis":"SO4-1-u2-X05"}],"explanation":["곡선이 있어요.","아름다워요.","심미적 가치예요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#6','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',2,'mc','auto','한옥을 마을 둘레의 나무·흙·돌로 지은 것에서 알 수 있는 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"mc","stem":"한옥을 마을 둘레의 나무·흙·돌로 지은 것에서 알 수 있는 가치는 무엇인가요?","options":[{"t":"생태환경적 가치","correct":true},{"t":"심미적 가치","mis":"SO4-1-u2-X06"},{"t":"역사적 가치","mis":"SO4-1-u2-X06"},{"t":"가격의 가치","mis":"SO4-1-u2-X05"}],"explanation":["자연 재료예요.","자연을 해치지 않아요.","생태환경적 가치예요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#7','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',2,'match','auto','김장 문화의 모습과 담긴 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"match","stem":"김장 문화의 모습과 담긴 가치를 알맞게 이으세요.","pairs":[{"l":"함께 담가 나누며 세대를 이어 전해 옴","r":"역사적 가치"},{"l":"김칫독을 땅에 묻어 겨울에도 영양을 얻음","r":"과학적 가치"}],"mis":"SO4-1-u2-X06","explanation":["오래 전해 왔어요.","슬기로운 방법이에요.","가치를 이어요."],"asset":{"type":"passage","lines":["마을 사람들이 서로 도와 함께 김치를 담그고 나눈다.","김칫독을 땅에 묻어 겨울에도 김치를 먹으며 영양을 얻었다.","이 솜씨는 할머니에게서 어머니로, 다시 아이들에게 이어지고 있다.","세계도 이 문화의 가치를 인정해 유네스코 인류무형문화유산이 되었다."],"title":"김장 문화 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#8','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',2,'ox','auto','김장 문화가 유네스코 인류무형문화유산이 된 것은 세계가 그 가치를 인정했다는 뜻이에요.',ARRAY['SO4-1-u2-X08']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"ox","stem":"김장 문화가 유네스코 인류무형문화유산이 된 것은 세계가 그 가치를 인정했다는 뜻이에요.","answer":"O","reason_options":[{"t":"세계가 함께 그 가치를 인정하고 지키겠다는 뜻이기 때문에","correct":true},{"t":"유네스코에 오르면 곧 사라진다는 뜻이기 때문에","mis":"SO4-1-u2-X08"}],"mis":"SO4-1-u2-X08","explanation":["세계가 알아보았어요.","가치를 인정했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["마을 사람들이 서로 도와 함께 김치를 담그고 나눈다.","김칫독을 땅에 묻어 겨울에도 김치를 먹으며 영양을 얻었다.","이 솜씨는 할머니에게서 어머니로, 다시 아이들에게 이어지고 있다.","세계도 이 문화의 가치를 인정해 유네스코 인류무형문화유산이 되었다."],"title":"김장 문화 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#9','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',2,'blank','auto','오래전부터 여러 세대에 걸쳐 전해 내려온 것에서 알 수 있는 가치는 (    ) 가치예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"blank","stem":"오래전부터 여러 세대에 걸쳐 전해 내려온 것에서 알 수 있는 가치는 (    ) 가치예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"역사적","correct":true},{"t":"심미적","mis":"SO4-1-u2-X06"},{"t":"생태환경적","mis":"SO4-1-u2-X06"},{"t":"값비싼","mis":"SO4-1-u2-X05"}],"explanation":["오래 전해 왔어요.","세대를 이었어요.","역사적 가치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_basic#10','soc',4,1,'u2','L02','g4_1_soc_u2_L02_basic','lesson_basic','SO4-1-u2-C2',3,'mc','auto','국가유산의 가치를 알게 되면 어떤 마음이 생기나요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"국가유산의 가치를 알게 되면 어떤 마음이 생기나요?","options":[{"t":"아끼고 보존해 다음 세대에 물려주고 싶어져요","correct":true},{"t":"값을 매겨 팔고 싶어져요","mis":"SO4-1-u2-X05"},{"t":"관심 없이 두고 싶어져요","mis":"SO4-1-u2-X01"},{"t":"낡았으니 새것으로 바꾸고 싶어져요","mis":"SO4-1-u2-X01"}],"explanation":["가치를 알았어요.","소중함을 느껴요.","지키고 싶어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
