INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#2','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',2,'ox','auto','한옥의 온돌은 아름다움만을 위해 만든 시설이에요.',ARRAY['SO4-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"ox","stem":"한옥의 온돌은 아름다움만을 위해 만든 시설이에요.","answer":"X","reason_options":[{"t":"겨울에 방을 따뜻하게 하는 슬기가 담긴 시설이기 때문에","correct":true},{"t":"보기 좋은 것은 모두 심미적 가치이기 때문에","mis":"SO4-1-u2-X06"}],"mis":"SO4-1-u2-X06","explanation":["온돌은 방을 데워요.","슬기로운 원리예요.","그래서 X예요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#3','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',3,'error','auto','한옥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X06']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"error","stem":"한옥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「처마의 곡선에는 생태환경적 가치가 담겼어.」","correct":true,"mis_target":"SO4-1-u2-X06"},{"t":"친구 가 — 「마루에는 과학적 가치가 담겼어.」","mis":"SO4-1-u2-X06"},{"t":"친구 나 — 「자연 재료에는 생태환경적 가치가 담겼어.」","mis":"SO4-1-u2-X06"}],"explanation":["처마는 곡선이에요.","아름다움이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#4','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',3,'mc','auto','김장 문화 한 가지에 담긴 가치를 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u2-X07','SO4-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"김장 문화 한 가지에 담긴 가치를 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"역사적 가치와 과학적 가치가 함께 담겨 있어요","correct":true},{"t":"역사적 가치 하나만 담겨 있어요","mis":"SO4-1-u2-X07"},{"t":"아무 가치도 담겨 있지 않아요","mis":"SO4-1-u2-X05"},{"t":"가격의 가치만 담겨 있어요","mis":"SO4-1-u2-X05"}],"explanation":["세대를 이어 왔어요.","땅속 김칫독도 있어요.","가치가 둘이에요."],"asset":{"type":"passage","lines":["마을 사람들이 서로 도와 함께 김치를 담그고 나눈다.","김칫독을 땅에 묻어 겨울에도 김치를 먹으며 영양을 얻었다.","이 솜씨는 할머니에게서 어머니로, 다시 아이들에게 이어지고 있다.","세계도 이 문화의 가치를 인정해 유네스코 인류무형문화유산이 되었다."],"title":"김장 문화 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#5','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',3,'mc','auto','가치를 가격으로 여긴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X07']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"가치를 가격으로 여긴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"가치는 값이 아니라 국가유산에 담긴 소중함과 뜻이야","correct":true},{"t":"맞아, 비쌀수록 가치가 커","mis":"SO4-1-u2-X05"},{"t":"맞아, 클수록 가치가 커","mis":"SO4-1-u2-X05"},{"t":"가치는 오래된 정도로만 정해져","mis":"SO4-1-u2-X07"}],"explanation":["가치는 값이 아니에요.","소중함과 뜻이에요.","알맞게 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#6','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',3,'ox','auto','유네스코에 이름이 오른 국가유산은 우리나라 사람만 아는 문화라는 뜻이에요.',ARRAY['SO4-1-u2-X08']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"ox","stem":"유네스코에 이름이 오른 국가유산은 우리나라 사람만 아는 문화라는 뜻이에요.","answer":"X","reason_options":[{"t":"세계가 함께 그 가치를 인정했다는 뜻이기 때문에","correct":true},{"t":"유네스코는 그 나라 안에서만 알리는 곳이기 때문에","mis":"SO4-1-u2-X08"}],"mis":"SO4-1-u2-X08","explanation":["세계가 알아보았어요.","함께 인정해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#7','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',3,'mc','auto','자료에 나온 한옥의 네 가지 모습에서 찾을 수 있는 가치를 바르게 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X07','SO4-1-u2-X05']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"자료에 나온 한옥의 네 가지 모습에서 찾을 수 있는 가치를 바르게 고른 것은 무엇인가요?","options":[{"t":"과학적·심미적·생태환경적 가치","correct":true},{"t":"과학적 가치뿐","mis":"SO4-1-u2-X07"},{"t":"심미적 가치뿐","mis":"SO4-1-u2-X07"},{"t":"가격의 가치와 크기의 가치","mis":"SO4-1-u2-X05"}],"explanation":["온돌·마루는 과학적이에요.","처마는 심미적이에요.","재료는 생태환경적이에요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#8','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',4,'essay','teacher','한옥의 모습 두 가지를 골라 각각 어떤 가치가 담겼는지 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C2","difficulty":4,"kind":"essay","stem":"한옥의 모습 두 가지를 골라 각각 어떤 가치가 담겼는지 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 온돌에는 과학적 가치가 담겼어요. 아궁이 불로 방바닥을 데워 겨울을 따뜻하게 지내는 슬기로운 원리이기 때문이에요. 처마에는 심미적 가치가 담겼어요. 지붕 끝이 위로 올라간 곡선이 아름답기 때문이에요.","scoring_points":["한옥의 모습 두 가지를 골랐는가","각각 알맞은 가치를 썼는가","모습에서 가치를 찾은 까닭을 썼는가"]},"explanation":["모습을 골라요.","가치를 짝지어요.","까닭을 써요."],"asset":{"type":"passage","lines":["온돌 — 아궁이 불로 방바닥을 데워 겨울에 따뜻하다.","마루 — 바람이 잘 통해 여름에 시원하다.","처마 — 지붕 끝이 위로 살짝 올라간 곡선이 아름답다.","재료 — 마을 둘레의 나무·흙·돌로 지어 자연을 해치지 않는다."],"title":"솔빛군 옛 한옥 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#9','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',4,'mc','auto','김장을 하는 마을 사람들의 모습에서 역사적 가치를 찾은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C2","difficulty":4,"kind":"mc","stem":"김장을 하는 마을 사람들의 모습에서 역사적 가치를 찾은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 도우며 담그는 문화가 여러 세대에 걸쳐 이어져 왔기 때문이에요","correct":true},{"t":"김치가 맛있기 때문이에요","mis":"SO4-1-u2-X05"},{"t":"김칫독을 땅에 묻어 영양을 얻었기 때문이에요","mis":"SO4-1-u2-X06"},{"t":"김치 값이 비싸기 때문이에요","mis":"SO4-1-u2-X05"}],"explanation":["역사적 가치는 오래 전해 옴이에요.","세대를 이었어요.","그래서 역사적 가치예요."],"asset":{"type":"passage","lines":["마을 사람들이 서로 도와 함께 김치를 담그고 나눈다.","김칫독을 땅에 묻어 겨울에도 김치를 먹으며 영양을 얻었다.","이 솜씨는 할머니에게서 어머니로, 다시 아이들에게 이어지고 있다.","세계도 이 문화의 가치를 인정해 유네스코 인류무형문화유산이 되었다."],"title":"김장 문화 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L02_challenge#10','soc',4,1,'u2','L02','g4_1_soc_u2_L02_challenge','lesson_challenge','SO4-1-u2-C2',4,'essay','teacher','우리 고장에 마을 사람들이 오랫동안 함께 물을 길어 쓴 옛 우물이 있어요. 이 우물에 담겼을 가치를 하나 골라 까닭과 함께 쓰고, 그 가치를 알면 우물을 어떻게 대할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":4,"kind":"essay","stem":"우리 고장에 마을 사람들이 오랫동안 함께 물을 길어 쓴 옛 우물이 있어요. 이 우물에 담겼을 가치를 하나 골라 까닭과 함께 쓰고, 그 가치를 알면 우물을 어떻게 대할지 쓰세요.","answer_guide":{"answer":"예: 옛 우물에는 역사적 가치가 담겼을 거예요. 마을 사람들이 오랫동안 함께 물을 길어 쓰며 생활해 온 곳이기 때문이에요. 이 가치를 알면 우물에 쓰레기를 버리지 않고 소중히 여기며 지킬 거예요.","scoring_points":["가치를 하나 골랐는가","우물의 모습과 이어 까닭을 썼는가","소중히 대하는 태도를 썼는가"]},"explanation":["우물의 모습을 읽어요.","가치를 골라요.","태도를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#1','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',1,'mc','auto','국가유산이 있는 곳에 직접 찾아가 살펴보는 조사 방법은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"mc","stem":"국가유산이 있는 곳에 직접 찾아가 살펴보는 조사 방법은 무엇인가요?","options":[{"t":"답사","correct":true},{"t":"검색","mis":"SO4-1-u2-X09"},{"t":"독서","mis":"SO4-1-u2-X09"},{"t":"전화","mis":"SO4-1-u2-X09"}],"explanation":["직접 가요.","현장을 살펴요.","답사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#2','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',1,'sa','auto','국가유산을 안내하며 궁금한 점에 답해 주는 사람을 문화유산 ○○○라고 해요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"sa","stem":"국가유산을 안내하며 궁금한 점에 답해 주는 사람을 문화유산 ○○○라고 해요. 세 글자로 쓰세요.","answer":["해설사"],"explanation":["안내해 주어요.","해설◯예요.","해설사예요."],"mis":"SO4-1-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#3','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',1,'ox','auto','국가유산을 조사하면 그 국가유산의 특징과 가치를 알 수 있어요.',ARRAY['SO4-1-u2-X10']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"ox","stem":"국가유산을 조사하면 그 국가유산의 특징과 가치를 알 수 있어요.","answer":"O","reason_options":[{"t":"조사는 사실을 찾아 확인하는 일이기 때문에","correct":true},{"t":"조사는 생각나는 대로 적는 일이기 때문에","mis":"SO4-1-u2-X10"}],"mis":"SO4-1-u2-X10","explanation":["사실을 찾아요.","특징과 가치를 알아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#4','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',1,'mc','auto','도서관의 책과 백과사전에서 국가유산을 찾아보는 방법은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"mc","stem":"도서관의 책과 백과사전에서 국가유산을 찾아보는 방법은 무엇인가요?","options":[{"t":"책으로 조사하기","correct":true},{"t":"답사로 조사하기","mis":"SO4-1-u2-X09"},{"t":"해설사께 여쭤보기","mis":"SO4-1-u2-X09"},{"t":"누리집으로 조사하기","mis":"SO4-1-u2-X09"}],"explanation":["도서관이에요.","책을 찾아요.","책으로 조사하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#5','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',2,'mc','auto','대화에서 하린이와 도윤이가 말한 조사 방법이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"mc","stem":"대화에서 하린이와 도윤이가 말한 조사 방법이 아닌 것은 무엇인가요?","options":[{"t":"친구에게 내용을 지어내 달라고 하기","correct":true},{"t":"백과사전 찾기","mis":"SO4-1-u2-X09"},{"t":"누리집 검색하기","mis":"SO4-1-u2-X09"},{"t":"직접 가서 살펴보기","mis":"SO4-1-u2-X09"}],"explanation":["네 가지 방법이 나와요.","지어내기는 없어요.","조사는 사실 확인이에요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 고장 옛 석탑은 언제 만들었을까?"},{"who":"도윤","text":"도서관에서 백과사전을 찾아보자."},{"who":"하린","text":"누리집에서도 검색해 보고, 해설사님께도 여쭤보자."},{"who":"도윤","text":"그리고 직접 가서 살펴보면 더 잘 알겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#6','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',2,'ox','auto','답사를 갈 때 사진을 찍어도 되는 곳인지 미리 알아보는 것이 좋아요.',ARRAY['SO4-1-u2-X12']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"ox","stem":"답사를 갈 때 사진을 찍어도 되는 곳인지 미리 알아보는 것이 좋아요.","answer":"O","reason_options":[{"t":"촬영이 안 되는 곳도 있어 미리 확인해야 하기 때문에","correct":true},{"t":"국가유산이 있는 곳은 어디든 마음대로 찍어도 되기 때문에","mis":"SO4-1-u2-X12"}],"mis":"SO4-1-u2-X12","explanation":["촬영이 안 되는 곳도 있어요.","미리 알아봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 갈 날짜와 길을 정한다.","② 보호자와 함께 갈지 정한다.","③ 사진을 찍어도 되는 곳인지 미리 알아본다.","④ 궁금한 점을 적어 간다."],"title":"솔빛반 답사 준비 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#7','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',2,'mc','auto','국가유산 정보를 모아 둔 누리집이나 군청 누리집을 이용하는 조사 방법은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"mc","stem":"국가유산 정보를 모아 둔 누리집이나 군청 누리집을 이용하는 조사 방법은 무엇인가요?","options":[{"t":"인터넷(누리집)으로 조사하기","correct":true},{"t":"답사로 조사하기","mis":"SO4-1-u2-X09"},{"t":"책으로 조사하기","mis":"SO4-1-u2-X09"},{"t":"해설사께 여쭤보기","mis":"SO4-1-u2-X09"}],"explanation":["누리집이에요.","인터넷으로 찾아요.","누리집 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#8','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',2,'blank','auto','여러 방법으로 조사하면 서로 보태져 더 (    ) 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X11']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"blank","stem":"여러 방법으로 조사하면 서로 보태져 더 (    ) 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"정확하고 자세히","correct":true},{"t":"대충","mis":"SO4-1-u2-X11"},{"t":"늦게","mis":"SO4-1-u2-X11"},{"t":"조금만","mis":"SO4-1-u2-X11"}],"explanation":["방법이 여럿이에요.","서로 보태져요.","정확하고 자세히 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#9','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',2,'match','auto','조사 방법과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"match","stem":"조사 방법과 하는 일을 알맞게 이으세요.","pairs":[{"l":"답사","r":"직접 찾아가 살펴보기"},{"l":"해설사께 여쭤보기","r":"궁금한 점을 직접 묻기"},{"l":"책으로 조사하기","r":"백과사전에서 찾기"}],"mis":"SO4-1-u2-X09","explanation":["방법을 읽어요.","하는 일을 떠올려요.","이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_basic#10','soc',4,1,'u2','L03','g4_1_soc_u2_L03_basic','lesson_basic','SO4-1-u2-C3',3,'mc','auto','국가유산을 조사하는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"mc","stem":"국가유산을 조사하는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"확인하지 않고 내용을 지어내기","correct":true},{"t":"누리집에서 검색하기","mis":"SO4-1-u2-X10"},{"t":"책에서 찾아보기","mis":"SO4-1-u2-X10"},{"t":"직접 찾아가 살펴보기","mis":"SO4-1-u2-X10"}],"explanation":["조사는 사실을 찾아요.","지어내면 사실이 아니에요.","지어내기는 조사가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#1','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',2,'mc','auto','답사 준비 목록에 더하면 좋은 것은 무엇인가요?',ARRAY['SO4-1-u2-X12']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"mc","stem":"답사 준비 목록에 더하면 좋은 것은 무엇인가요?","options":[{"t":"안전하게 다닐 길과 주의할 점 알아보기","correct":true},{"t":"아무 준비 없이 가기로 하기","mis":"SO4-1-u2-X12"},{"t":"국가유산을 만져 보기로 하기","mis":"SO4-1-u2-X12"},{"t":"친구에게 다 맡기기","mis":"SO4-1-u2-X12"}],"explanation":["답사는 준비가 필요해요.","안전도 살펴요.","주의할 점을 알아봐요."],"asset":{"type":"passage","lines":["① 갈 날짜와 길을 정한다.","② 보호자와 함께 갈지 정한다.","③ 사진을 찍어도 되는 곳인지 미리 알아본다.","④ 궁금한 점을 적어 간다."],"title":"솔빛반 답사 준비 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#2','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',2,'ox','auto','조사는 한 가지 방법만 쓰는 것이 가장 좋아요.',ARRAY['SO4-1-u2-X11']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"ox","stem":"조사는 한 가지 방법만 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"방법마다 알 수 있는 것이 달라 여러 방법을 함께 쓰면 서로 보태지기 때문에","correct":true},{"t":"한 가지 방법으로 모든 것을 알 수 있기 때문에","mis":"SO4-1-u2-X11"}],"mis":"SO4-1-u2-X11","explanation":["방법마다 달라요.","함께 쓰면 보태져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#3','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',3,'error','auto','대화를 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X09','SO4-1-u2-X29']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"error","stem":"대화를 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「직접 가서 살펴보는 건 누리집 조사야.」","correct":true,"mis_target":"SO4-1-u2-X09"},{"t":"친구 나 — 「백과사전은 책으로 조사하는 방법이야.」","mis":"SO4-1-u2-X09"},{"t":"친구 다 — 「해설사님께 여쭤보면 궁금한 점을 직접 물을 수 있어.」","mis":"SO4-1-u2-X29"}],"explanation":["직접 가는 건 답사예요.","누리집 조사가 아니에요.","친구 가가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 고장 옛 석탑은 언제 만들었을까?"},{"who":"도윤","text":"도서관에서 백과사전을 찾아보자."},{"who":"하린","text":"누리집에서도 검색해 보고, 해설사님께도 여쭤보자."},{"who":"도윤","text":"그리고 직접 가서 살펴보면 더 잘 알겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#4','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',3,'mc','auto','석탑을 만든 때를 알고 싶은데 누리집 두 곳의 내용이 서로 달라요. 어떻게 하면 좋을까요?',ARRAY['SO4-1-u2-X10','SO4-1-u2-X11']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"mc","stem":"석탑을 만든 때를 알고 싶은데 누리집 두 곳의 내용이 서로 달라요. 어떻게 하면 좋을까요?","options":[{"t":"책을 찾거나 해설사께 여쭤 사실을 더 확인해요","correct":true},{"t":"마음에 드는 내용을 골라 적어요","mis":"SO4-1-u2-X10"},{"t":"두 내용을 섞어 새로 지어 적어요","mis":"SO4-1-u2-X10"},{"t":"조사를 그만두어요","mis":"SO4-1-u2-X11"}],"explanation":["내용이 달라요.","다른 방법으로 확인해요.","사실을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#5','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',3,'mc','auto','하린이와 도윤이가 네 가지 방법을 함께 쓰려는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X11']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"mc","stem":"하린이와 도윤이가 네 가지 방법을 함께 쓰려는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 보태져 더 정확하고 자세히 알 수 있기 때문이에요","correct":true},{"t":"시간이 오래 걸릴수록 좋기 때문이에요","mis":"SO4-1-u2-X11"},{"t":"한 가지만 하면 혼나기 때문이에요","mis":"SO4-1-u2-X11"},{"t":"방법마다 알 수 있는 것이 똑같기 때문이에요","mis":"SO4-1-u2-X11"}],"explanation":["방법마다 달라요.","서로 보태요.","정확하고 자세해요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 고장 옛 석탑은 언제 만들었을까?"},{"who":"도윤","text":"도서관에서 백과사전을 찾아보자."},{"who":"하린","text":"누리집에서도 검색해 보고, 해설사님께도 여쭤보자."},{"who":"도윤","text":"그리고 직접 가서 살펴보면 더 잘 알겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#6','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',3,'ox','auto','국가유산을 조사한 뒤에는 조사한 내용을 정리해 특징과 가치를 알아봐요.',ARRAY['SO4-1-u2-X10']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"ox","stem":"국가유산을 조사한 뒤에는 조사한 내용을 정리해 특징과 가치를 알아봐요.","answer":"O","reason_options":[{"t":"조사한 것을 정리해야 국가유산을 제대로 알 수 있기 때문에","correct":true},{"t":"조사가 끝나면 내용은 버려도 되기 때문에","mis":"SO4-1-u2-X10"}],"mis":"SO4-1-u2-X10","explanation":["조사를 마쳤어요.","정리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#7','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',3,'mc','auto','문화유산 해설사께 여쭤보는 방법의 좋은 점은 무엇인가요?',ARRAY['SO4-1-u2-X12','SO4-1-u2-X11','SO4-1-u2-X29']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"mc","stem":"문화유산 해설사께 여쭤보는 방법의 좋은 점은 무엇인가요?","options":[{"t":"궁금한 점을 그 자리에서 직접 물어볼 수 있어요","correct":true},{"t":"사진을 마음대로 찍을 수 있어요","mis":"SO4-1-u2-X12"},{"t":"조사하지 않아도 돼요","mis":"SO4-1-u2-X11"},{"t":"국가유산을 가져갈 수 있어요","mis":"SO4-1-u2-X29"}],"explanation":["해설사는 안내해요.","직접 물어요.","바로 답을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#8','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',4,'essay','teacher','솔빛반이 옛 석탑으로 답사를 가요. 답사 전에 할 일 두 가지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C3","difficulty":4,"kind":"essay","stem":"솔빛반이 옛 석탑으로 답사를 가요. 답사 전에 할 일 두 가지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 사진을 찍어도 되는 곳인지 미리 알아봐야 해요. 촬영이 안 되는 곳도 있기 때문이에요. 궁금한 점을 적어 가야 해요. 무엇을 살펴볼지 알아야 답사에서 더 많은 것을 알 수 있기 때문이에요.","scoring_points":["답사 전에 할 일 두 가지를 썼는가","각각의 까닭을 썼는가","목록이나 차시 내용과 맞게 썼는가"]},"explanation":["목록을 읽어요.","두 가지를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 갈 날짜와 길을 정한다.","② 보호자와 함께 갈지 정한다.","③ 사진을 찍어도 되는 곳인지 미리 알아본다.","④ 궁금한 점을 적어 간다."],"title":"솔빛반 답사 준비 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#9','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',4,'mc','auto','석탑에 담긴 옛이야기를 조사하려고 해요. 가장 알맞은 조사 계획은 무엇인가요?',ARRAY['SO4-1-u2-X11','SO4-1-u2-X10','SO4-1-u2-X12']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C3","difficulty":4,"kind":"mc","stem":"석탑에 담긴 옛이야기를 조사하려고 해요. 가장 알맞은 조사 계획은 무엇인가요?","options":[{"t":"책·누리집으로 먼저 알아보고, 답사 때 해설사께 궁금한 점을 여쭤봐요","correct":true},{"t":"누리집 한 곳만 보고 끝내요","mis":"SO4-1-u2-X11"},{"t":"기억나는 이야기를 지어 써요","mis":"SO4-1-u2-X10"},{"t":"준비 없이 석탑에 가 봐요","mis":"SO4-1-u2-X12"}],"explanation":["먼저 찾아봐요.","직접 가서 여쭤봐요.","여러 방법을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L03_challenge#10','soc',4,1,'u2','L03','g4_1_soc_u2_L03_challenge','lesson_challenge','SO4-1-u2-C3',4,'essay','teacher','책·누리집·해설사·답사 가운데 두 가지를 골라 각 방법으로 무엇을 알 수 있을지 쓰고, 두 방법을 함께 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C3","difficulty":4,"kind":"essay","stem":"책·누리집·해설사·답사 가운데 두 가지를 골라 각 방법으로 무엇을 알 수 있을지 쓰고, 두 방법을 함께 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 책으로는 석탑을 언제, 어떻게 만들었는지 알 수 있어요. 답사로는 석탑의 크기와 생김새를 직접 볼 수 있어요. 두 방법을 함께 쓰면 책에서 읽은 내용을 눈으로 확인할 수 있어 더 정확하고 자세히 알 수 있어요.","scoring_points":["조사 방법 두 가지를 골랐는가","각 방법으로 알 수 있는 것을 썼는가","함께 쓰면 좋은 점을 썼는가"]},"explanation":["방법을 골라요.","알 수 있는 것을 써요.","함께 쓰면 좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#1','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',1,'mc','auto','조사한 국가유산의 특징은 어떻게 정리해야 하나요?',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"mc","stem":"조사한 국가유산의 특징은 어떻게 정리해야 하나요?","options":[{"t":"있는 그대로 사실에 따라","correct":true},{"t":"마음대로 지어서","mis":"SO4-1-u2-X13"},{"t":"재미있게 꾸며서","mis":"SO4-1-u2-X13"},{"t":"가치와 섞어서","mis":"SO4-1-u2-X13"}],"explanation":["특징은 사실이에요.","있는 그대로예요.","사실에 따라 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#2','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',1,'sa','auto','특징을 바탕으로 국가유산이 왜 소중한지 헤아려 정리한 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"sa","stem":"특징을 바탕으로 국가유산이 왜 소중한지 헤아려 정리한 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["가치"],"explanation":["헤아린 것이에요.","소중함과 뜻이에요.","가치예요."],"mis":"SO4-1-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#3','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',1,'ox','auto','조사한 내용은 글자를 그대로 베끼지 말고 담긴 뜻을 생각한 뒤 정리해요.',ARRAY['SO4-1-u2-X14']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"ox","stem":"조사한 내용은 글자를 그대로 베끼지 말고 담긴 뜻을 생각한 뒤 정리해요.","answer":"O","reason_options":[{"t":"뜻을 생각해야 국가유산을 제대로 이해할 수 있기 때문에","correct":true},{"t":"그대로 베끼는 것이 가장 좋은 정리이기 때문에","mis":"SO4-1-u2-X14"}],"mis":"SO4-1-u2-X14","explanation":["그대로 베끼지 않아요.","뜻을 생각해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#4','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',1,'mc','auto','국가유산의 기본 정보가 아닌 것은 무엇인가요?',ARRAY['SO4-1-u2-X15']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"mc","stem":"국가유산의 기본 정보가 아닌 것은 무엇인가요?","options":[{"t":"내일의 날씨","correct":true},{"t":"분류(종류)","mis":"SO4-1-u2-X15"},{"t":"있는 곳","mis":"SO4-1-u2-X15"},{"t":"만든 시대","mis":"SO4-1-u2-X15"}],"explanation":["분류·있는 곳·시대예요.","날씨는 아니에요.","내일의 날씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#5','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',2,'mc','auto','하린이의 조사 수첩에서 특징에 해당하는 것을 모두 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"mc","stem":"하린이의 조사 수첩에서 특징에 해당하는 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉢, ㉣","mis":"SO4-1-u2-X13"},{"t":"㉠, ㉢","mis":"SO4-1-u2-X13"},{"t":"㉡, ㉣","mis":"SO4-1-u2-X13"}],"explanation":["눈으로 확인한 것이에요.","다섯 층·지붕돌 끝이에요.","㉠, ㉡이에요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 석탑","분류 — 형태가 있는 문화유산","있는 곳 — 솔빛군 절터 언덕","만든 때 — (조사해서 적을 칸)","㉠ 돌을 다섯 층으로 쌓아 만들었다.","㉡ 층마다 지붕돌 끝이 살짝 들려 있다.","㉢ 무거운 돌을 높이 쌓은 조상들의 뛰어난 솜씨가 담겼다.","㉣ 살짝 들린 지붕돌 끝에서 아름다움을 느낄 수 있다."],"title":"하린이의 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#6','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',2,'mc','auto','조사 수첩의 ㉢은 특징과 가치 가운데 무엇인가요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"mc","stem":"조사 수첩의 ㉢은 특징과 가치 가운데 무엇인가요?","options":[{"t":"가치 — 특징을 바탕으로 헤아린 것","correct":true},{"t":"특징 — 눈으로 확인한 사실","mis":"SO4-1-u2-X13"},{"t":"기본 정보 — 있는 곳","mis":"SO4-1-u2-X15"},{"t":"기본 정보 — 만든 때","mis":"SO4-1-u2-X15"}],"explanation":["솜씨가 담겼대요.","헤아린 것이에요.","가치예요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 석탑","분류 — 형태가 있는 문화유산","있는 곳 — 솔빛군 절터 언덕","만든 때 — (조사해서 적을 칸)","㉠ 돌을 다섯 층으로 쌓아 만들었다.","㉡ 층마다 지붕돌 끝이 살짝 들려 있다.","㉢ 무거운 돌을 높이 쌓은 조상들의 뛰어난 솜씨가 담겼다.","㉣ 살짝 들린 지붕돌 끝에서 아름다움을 느낄 수 있다."],"title":"하린이의 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#7','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',2,'ox','auto','서아는 친구의 발표를 바르게 듣고 있어요.',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"ox","stem":"서아는 친구의 발표를 바르게 듣고 있어요.","answer":"X","reason_options":[{"t":"도윤이의 말이 끝나기 전에 끼어들었기 때문에","correct":true},{"t":"먼저 말하는 사람이 잘 듣는 사람이기 때문에","mis":"SO4-1-u2-X16"}],"mis":"SO4-1-u2-X16","explanation":["도윤이가 말하는 중이에요.","서아가 끼어들었어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"우리 모둠은 옛 석탑을 조사했어. 돌을 다섯 층으로 쌓았대."},{"who":"서아","text":"(도윤이가 말하는 중에) 나도 알아! 그다음은 내가 말할게!"},{"who":"하린","text":"나는 들으며 새로 알게 된 것을 적고 있어."},{"who":"예준","text":"궁금한 점은 도윤이 이야기가 끝난 뒤에 물어볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#8','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',2,'match','auto','정리표의 칸과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"match","stem":"정리표의 칸과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"특징","r":"돌을 다섯 층으로 쌓았다"},{"l":"가치","r":"조상의 뛰어난 솜씨가 담겼다"},{"l":"기본 정보","r":"솔빛군 절터 언덕에 있다"}],"mis":"SO4-1-u2-X13","explanation":["사실은 특징이에요.","헤아린 것은 가치예요.","있는 곳은 기본 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
