INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_basic#10','soc',4,1,'u2','L04','g4_1_soc_u2_L04_basic','lesson_basic','SO4-1-u2-C4',3,'mc','auto','특징과 가치를 나누어 정리하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X14']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"mc","stem":"특징과 가치를 나누어 정리하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사실대로 알고 그 소중함까지 느낄 수 있기 때문이에요","correct":true},{"t":"칸이 많을수록 보기 좋기 때문이에요","mis":"SO4-1-u2-X13"},{"t":"특징과 가치는 늘 같은 내용이기 때문이에요","mis":"SO4-1-u2-X13"},{"t":"베껴 쓰기 쉽기 때문이에요","mis":"SO4-1-u2-X14"}],"explanation":["특징은 사실이에요.","가치는 소중함이에요.","둘 다 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#1','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',2,'mc','auto','모둠 나누기에서 바르게 듣는 친구를 모두 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"mc","stem":"모둠 나누기에서 바르게 듣는 친구를 모두 고른 것은 무엇인가요?","options":[{"t":"하린, 예준","correct":true},{"t":"서아, 하린","mis":"SO4-1-u2-X16"},{"t":"서아, 예준","mis":"SO4-1-u2-X16"},{"t":"서아","mis":"SO4-1-u2-X16"}],"explanation":["하린이는 적으며 들어요.","예준이는 끝난 뒤 물어요.","하린, 예준이에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"우리 모둠은 옛 석탑을 조사했어. 돌을 다섯 층으로 쌓았대."},{"who":"서아","text":"(도윤이가 말하는 중에) 나도 알아! 그다음은 내가 말할게!"},{"who":"하린","text":"나는 들으며 새로 알게 된 것을 적고 있어."},{"who":"예준","text":"궁금한 점은 도윤이 이야기가 끝난 뒤에 물어볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#2','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',2,'ox','auto','조사 수첩의 ㉣은 눈으로 확인한 사실이므로 특징이에요.',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"ox","stem":"조사 수첩의 ㉣은 눈으로 확인한 사실이므로 특징이에요.","answer":"X","reason_options":[{"t":"아름다움을 느낀다는 것은 특징을 보고 헤아린 가치이기 때문에","correct":true},{"t":"느낌을 적은 것도 모두 사실이기 때문에","mis":"SO4-1-u2-X13"}],"mis":"SO4-1-u2-X13","explanation":["아름다움을 느꼈어요.","헤아린 것이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 석탑","분류 — 형태가 있는 문화유산","있는 곳 — 솔빛군 절터 언덕","만든 때 — (조사해서 적을 칸)","㉠ 돌을 다섯 층으로 쌓아 만들었다.","㉡ 층마다 지붕돌 끝이 살짝 들려 있다.","㉢ 무거운 돌을 높이 쌓은 조상들의 뛰어난 솜씨가 담겼다.","㉣ 살짝 들린 지붕돌 끝에서 아름다움을 느낄 수 있다."],"title":"하린이의 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#3','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',3,'error','auto','조사 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X15']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"error","stem":"조사 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉡은 조상의 솜씨를 헤아린 가치야.」","correct":true,"mis_target":"SO4-1-u2-X13"},{"t":"친구 가 — 「㉠은 있는 그대로의 사실이라 특징이야.」","mis":"SO4-1-u2-X13"},{"t":"친구 나 — 「있는 곳과 분류는 기본 정보야.」","mis":"SO4-1-u2-X15"}],"explanation":["㉡은 지붕돌 모습이에요.","눈으로 본 사실이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 석탑","분류 — 형태가 있는 문화유산","있는 곳 — 솔빛군 절터 언덕","만든 때 — (조사해서 적을 칸)","㉠ 돌을 다섯 층으로 쌓아 만들었다.","㉡ 층마다 지붕돌 끝이 살짝 들려 있다.","㉢ 무거운 돌을 높이 쌓은 조상들의 뛰어난 솜씨가 담겼다.","㉣ 살짝 들린 지붕돌 끝에서 아름다움을 느낄 수 있다."],"title":"하린이의 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#4','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',3,'mc','auto','석탑의 특징인 돌을 다섯 층으로 쌓았다는 사실에서 헤아릴 수 있는 가치로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X05','SO4-1-u2-X01']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"mc","stem":"석탑의 특징인 돌을 다섯 층으로 쌓았다는 사실에서 헤아릴 수 있는 가치로 알맞은 것은 무엇인가요?","options":[{"t":"무거운 돌을 높이 쌓아 올린 조상들의 솜씨","correct":true},{"t":"돌이 다섯 개라는 사실","mis":"SO4-1-u2-X13"},{"t":"석탑의 값이 비싸다는 것","mis":"SO4-1-u2-X05"},{"t":"석탑이 새로 지은 탑이라는 것","mis":"SO4-1-u2-X01"}],"explanation":["특징을 읽어요.","무엇이 담겼을지 헤아려요.","조상들의 솜씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#5','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',3,'mc','auto','누리집 설명을 그대로 옮겨 적은 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X14']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"mc","stem":"누리집 설명을 그대로 옮겨 적은 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"무엇이 담겼는지 생각해 보고 네 말로 정리해 봐","correct":true},{"t":"잘했어, 그대로 옮기는 게 정리야","mis":"SO4-1-u2-X14"},{"t":"친구 것을 옮겨 적으면 더 좋아","mis":"SO4-1-u2-X14"},{"t":"정리는 하지 않아도 돼","mis":"SO4-1-u2-X14"}],"explanation":["그대로 베꼈어요.","뜻을 생각해야 해요.","내 말로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#6','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',3,'ox','auto','정리한 내용을 모둠과 나누면 더 많은 국가유산을 알 수 있어요.',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"ox","stem":"정리한 내용을 모둠과 나누면 더 많은 국가유산을 알 수 있어요.","answer":"O","reason_options":[{"t":"친구들이 조사한 국가유산까지 함께 알게 되기 때문에","correct":true},{"t":"모둠과 나누면 내 정리가 없어지기 때문에","mis":"SO4-1-u2-X16"}],"mis":"SO4-1-u2-X16","explanation":["모둠마다 조사했어요.","서로 나눠요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#7','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',3,'mc','auto','국가유산을 조사하고 정리하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X14']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"mc","stem":"국가유산을 조사하고 정리하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"특징과 가치를 알고 소중함을 느끼려고","correct":true},{"t":"정보만 외우려고","mis":"SO4-1-u2-X14"},{"t":"점수만 받으려고","mis":"SO4-1-u2-X14"},{"t":"친구보다 많이 적으려고","mis":"SO4-1-u2-X14"}],"explanation":["정보만이 아니에요.","특징과 가치를 알아요.","소중함을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#8','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',4,'essay','teacher','조사 수첩의 ㉠~㉣을 특징과 가치로 나누고, 특징 하나와 그 특징에서 헤아린 가치를 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C4","difficulty":4,"kind":"essay","stem":"조사 수첩의 ㉠~㉣을 특징과 가치로 나누고, 특징 하나와 그 특징에서 헤아린 가치를 이어 쓰세요.","answer_guide":{"answer":"예: 특징은 ㉠, ㉡이고 가치는 ㉢, ㉣이에요. ㉡ 층마다 지붕돌 끝이 살짝 들려 있다는 특징에서 ㉣ 그 모습에서 아름다움을 느낄 수 있다는 가치를 헤아릴 수 있어요.","scoring_points":["특징 ㉠·㉡과 가치 ㉢·㉣으로 나누었는가","특징 하나를 골랐는가","그 특징과 이어지는 가치를 썼는가"]},"explanation":["사실을 찾아요.","헤아린 것을 찾아요.","이어 써요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 석탑","분류 — 형태가 있는 문화유산","있는 곳 — 솔빛군 절터 언덕","만든 때 — (조사해서 적을 칸)","㉠ 돌을 다섯 층으로 쌓아 만들었다.","㉡ 층마다 지붕돌 끝이 살짝 들려 있다.","㉢ 무거운 돌을 높이 쌓은 조상들의 뛰어난 솜씨가 담겼다.","㉣ 살짝 들린 지붕돌 끝에서 아름다움을 느낄 수 있다."],"title":"하린이의 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#9','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',4,'mc','auto','도자기 정리표의 가치 칸에 쓸 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C4","difficulty":4,"kind":"mc","stem":"도자기 정리표의 가치 칸에 쓸 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"흙을 빚고 구워 단단한 그릇을 만든 조상들의 슬기가 담겼다","correct":true},{"t":"흙을 빚어 구운 그릇이다","mis":"SO4-1-u2-X13"},{"t":"높이가 한 뼘쯤이다","mis":"SO4-1-u2-X13"},{"t":"지금 가게에서 파는 그릇보다 비싸다","mis":"SO4-1-u2-X05"}],"explanation":["가치 칸이에요.","헤아린 것을 써요.","조상들의 슬기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L04_challenge#10','soc',4,1,'u2','L04','g4_1_soc_u2_L04_challenge','lesson_challenge','SO4-1-u2-C4',4,'essay','teacher','모둠 나누기에서 말하는 사람과 듣는 사람이 지킬 점을 하나씩 쓰고, 서아에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C4","difficulty":4,"kind":"essay","stem":"모둠 나누기에서 말하는 사람과 듣는 사람이 지킬 점을 하나씩 쓰고, 서아에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 말하는 사람은 또렷하게 말해요. 듣는 사람은 집중해서 듣고 새로 알게 된 것을 적어요. 서아야, 도윤이 이야기가 끝날 때까지 들은 뒤에 네 생각을 말해 줘.","scoring_points":["말하는 사람이 지킬 점을 썼는가","듣는 사람이 지킬 점을 썼는가","서아에게 알맞은 말을 썼는가"]},"explanation":["말하는 사람을 떠올려요.","듣는 사람을 떠올려요.","서아에게 말해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"우리 모둠은 옛 석탑을 조사했어. 돌을 다섯 층으로 쌓았대."},{"who":"서아","text":"(도윤이가 말하는 중에) 나도 알아! 그다음은 내가 말할게!"},{"who":"하린","text":"나는 들으며 새로 알게 된 것을 적고 있어."},{"who":"예준","text":"궁금한 점은 도윤이 이야기가 끝난 뒤에 물어볼게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#1','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',1,'mc','auto','노래나 춤으로 국가유산을 표현하는 방법은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"mc","stem":"노래나 춤으로 국가유산을 표현하는 방법은 무엇인가요?","options":[{"t":"공연하기","correct":true},{"t":"가상 일기 쓰기","mis":"SO4-1-u2-X18"},{"t":"역할놀이 하기","mis":"SO4-1-u2-X18"},{"t":"계산하기","mis":"SO4-1-u2-X18"}],"explanation":["노래와 춤이에요.","무대에서 보여 줘요.","공연하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#2','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',1,'sa','auto','옛사람이 되어 그날 있었던 일을 상상해 쓰는 표현 방법을 ○○ 일기 쓰기라고 해요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"sa","stem":"옛사람이 되어 그날 있었던 일을 상상해 쓰는 표현 방법을 ○○ 일기 쓰기라고 해요. 두 글자로 쓰세요.","answer":["가상"],"explanation":["옛사람이 되어요.","◯◯ 일기예요.","가상 일기예요."],"mis":"SO4-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#3','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',1,'ox','auto','역할놀이는 대본을 만들어 옛 장면을 연기하는 표현 방법이에요.',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"ox","stem":"역할놀이는 대본을 만들어 옛 장면을 연기하는 표현 방법이에요.","answer":"O","reason_options":[{"t":"옛사람이 되어 그 장면을 몸과 말로 나타내기 때문에","correct":true},{"t":"역할놀이는 노래만 부르는 방법이기 때문에","mis":"SO4-1-u2-X18"}],"mis":"SO4-1-u2-X18","explanation":["대본이 있어요.","연기해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#4','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',1,'mc','auto','조상들의 생활 모습을 표현하는 방법이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"mc","stem":"조상들의 생활 모습을 표현하는 방법이 아닌 것은 무엇인가요?","options":[{"t":"수학 문제 풀기","correct":true},{"t":"공연하기","mis":"SO4-1-u2-X18"},{"t":"가상 일기 쓰기","mis":"SO4-1-u2-X18"},{"t":"역할놀이 하기","mis":"SO4-1-u2-X18"}],"explanation":["표현 방법을 떠올려요.","공연·일기·역할놀이예요.","수학 문제는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#5','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',2,'mc','auto','표현 계획 ㉰는 어떤 표현 방법인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"mc","stem":"표현 계획 ㉰는 어떤 표현 방법인가요?","options":[{"t":"역할놀이 하기","correct":true},{"t":"공연하기","mis":"SO4-1-u2-X18"},{"t":"가상 일기 쓰기","mis":"SO4-1-u2-X18"},{"t":"사진 찍기","mis":"SO4-1-u2-X18"}],"explanation":["대본을 만들어요.","장면을 연기해요.","역할놀이예요."],"asset":{"type":"passage","lines":["㉮ 손을 맞잡고 원을 그리며 강강술래를 노래하고 춤춘다.","㉯ 옛 해녀가 되어 하루를 일기로 쓴다.","㉰ 대본을 만들어 옛사람들이 배를 타고 고기 잡는 장면을 연기한다.","㉱ 옛 서당의 모습을 네 칸 만화로 그린다."],"title":"솔빛반의 표현 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#6','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',2,'ox','auto','가상 일기는 역사적 사실과 관계없이 마음대로 상상해 써도 돼요.',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"ox","stem":"가상 일기는 역사적 사실과 관계없이 마음대로 상상해 써도 돼요.","answer":"X","reason_options":[{"t":"조사한 역사적 사실을 토대로 상상해야 참모습을 바르게 전할 수 있기 때문에","correct":true},{"t":"가상이라는 말은 사실이 필요 없다는 뜻이기 때문에","mis":"SO4-1-u2-X17"}],"mis":"SO4-1-u2-X17","explanation":["사실이 바탕이에요.","그 위에 상상해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#7','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',2,'match','auto','표현 계획과 표현 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"match","stem":"표현 계획과 표현 방법을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"공연하기"},{"l":"㉯","r":"가상 일기 쓰기"},{"l":"㉱","r":"그림·만화 그리기"}],"mis":"SO4-1-u2-X18","explanation":["노래와 춤이에요.","일기예요.","만화예요."],"asset":{"type":"passage","lines":["㉮ 손을 맞잡고 원을 그리며 강강술래를 노래하고 춤춘다.","㉯ 옛 해녀가 되어 하루를 일기로 쓴다.","㉰ 대본을 만들어 옛사람들이 배를 타고 고기 잡는 장면을 연기한다.","㉱ 옛 서당의 모습을 네 칸 만화로 그린다."],"title":"솔빛반의 표현 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#8','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',2,'blank','auto','해녀의 물질과 노래는 형태 없이 세대를 이어 전해져 (    )에 속해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X17','SO4-1-u2-X01']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"blank","stem":"해녀의 물질과 노래는 형태 없이 세대를 이어 전해져 (    )에 속해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"무형유산","correct":true},{"t":"문화유산","mis":"SO4-1-u2-X03"},{"t":"새 놀이","mis":"SO4-1-u2-X17"},{"t":"기념품","mis":"SO4-1-u2-X01"}],"explanation":["물질과 노래예요.","형태가 없어요.","무형유산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#9','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',2,'mc','auto','조상들의 생활 모습을 표현하면 좋은 점이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u2-X19']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"mc","stem":"조상들의 생활 모습을 표현하면 좋은 점이 아닌 것은 무엇인가요?","options":[{"t":"국가유산이 저절로 사라져요","correct":true},{"t":"국가유산을 널리 알릴 수 있어요","mis":"SO4-1-u2-X19"},{"t":"국가유산의 가치를 이해할 수 있어요","mis":"SO4-1-u2-X19"},{"t":"우리 지역에 자긍심을 가질 수 있어요","mis":"SO4-1-u2-X19"}],"explanation":["알려요.","이해해요.","사라지는 건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_basic#10','soc',4,1,'u2','L05','g4_1_soc_u2_L05_basic','lesson_basic','SO4-1-u2-C5',3,'mc','auto','표현 계획 ㉮를 하기 전에 가장 먼저 할 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X18']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"mc","stem":"표현 계획 ㉮를 하기 전에 가장 먼저 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"강강술래가 어떤 놀이인지 조사해요","correct":true},{"t":"조사 없이 바로 마음대로 춤춰요","mis":"SO4-1-u2-X17"},{"t":"일기장을 준비해요","mis":"SO4-1-u2-X18"},{"t":"계산 문제를 풀어요","mis":"SO4-1-u2-X18"}],"explanation":["표현할 것을 정했어요.","먼저 알아봐요.","조사가 먼저예요."],"asset":{"type":"passage","lines":["㉮ 손을 맞잡고 원을 그리며 강강술래를 노래하고 춤춘다.","㉯ 옛 해녀가 되어 하루를 일기로 쓴다.","㉰ 대본을 만들어 옛사람들이 배를 타고 고기 잡는 장면을 연기한다.","㉱ 옛 서당의 모습을 네 칸 만화로 그린다."],"title":"솔빛반의 표현 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#1','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',2,'mc','auto','역할놀이로 표현할 때 가장 먼저 정할 것은 무엇인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X19']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"mc","stem":"역할놀이로 표현할 때 가장 먼저 정할 것은 무엇인가요?","options":[{"t":"표현할 국가유산과 장면","correct":true},{"t":"입을 옷 색깔","mis":"SO4-1-u2-X17"},{"t":"보러 올 사람 수","mis":"SO4-1-u2-X19"},{"t":"끝나고 먹을 간식","mis":"SO4-1-u2-X19"}],"explanation":["무엇을 나타낼까요?","장면을 정해요.","국가유산과 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#2','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',2,'ox','auto','예린이의 가상 일기는 모두 역사적 사실을 토대로 썼어요.',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"ox","stem":"예린이의 가상 일기는 모두 역사적 사실을 토대로 썼어요.","answer":"X","reason_options":[{"t":"옛 해녀가 휴대 전화를 쓴 것은 역사적 사실과 맞지 않기 때문에","correct":true},{"t":"가상 일기라서 무엇을 써도 사실이 되기 때문에","mis":"SO4-1-u2-X17"}],"mis":"SO4-1-u2-X17","explanation":["옛날 해녀예요.","휴대 전화가 없었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["나는 옛날 바닷가 마을의 해녀다.","물에 들어가기 전에 휴대 전화로 바다 날씨를 찾아보았다.","숨을 참고 바닷속에 들어가 전복과 소라를 땄다.","물 위로 올라와 숨을 내쉬며 동료들과 노래를 불렀다.","저녁에는 딴 것을 나누며 내일 바다가 잔잔하기를 빌었다."],"title":"예린이가 쓴 가상 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#3','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',3,'error','auto','가상 일기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"error","stem":"가상 일기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「일기니까 휴대 전화 부분도 괜찮아.」","correct":true,"mis_target":"SO4-1-u2-X17"},{"t":"친구 가 — 「숨을 참고 해산물을 딴 건 해녀의 물질이야.」","mis":"SO4-1-u2-X17"},{"t":"친구 다 — 「노래를 부른 부분은 해녀 노래를 떠올리게 해.」","mis":"SO4-1-u2-X18"}],"explanation":["사실을 토대로 써요.","휴대 전화는 맞지 않아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["나는 옛날 바닷가 마을의 해녀다.","물에 들어가기 전에 휴대 전화로 바다 날씨를 찾아보았다.","숨을 참고 바닷속에 들어가 전복과 소라를 땄다.","물 위로 올라와 숨을 내쉬며 동료들과 노래를 불렀다.","저녁에는 딴 것을 나누며 내일 바다가 잔잔하기를 빌었다."],"title":"예린이가 쓴 가상 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#4','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',3,'mc','auto','예린이의 일기에서 고쳐야 할 부분은 무엇인가요?',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"mc","stem":"예린이의 일기에서 고쳐야 할 부분은 무엇인가요?","options":[{"t":"물에 들어가기 전에 휴대 전화로 바다 날씨를 찾아본 부분","correct":true},{"t":"숨을 참고 전복과 소라를 딴 부분","mis":"SO4-1-u2-X17"},{"t":"동료들과 노래를 부른 부분","mis":"SO4-1-u2-X17"},{"t":"딴 것을 나눈 부분","mis":"SO4-1-u2-X17"}],"explanation":["옛날이에요.","휴대 전화를 찾아요.","그 부분을 고쳐요."],"asset":{"type":"passage","lines":["나는 옛날 바닷가 마을의 해녀다.","물에 들어가기 전에 휴대 전화로 바다 날씨를 찾아보았다.","숨을 참고 바닷속에 들어가 전복과 소라를 땄다.","물 위로 올라와 숨을 내쉬며 동료들과 노래를 불렀다.","저녁에는 딴 것을 나누며 내일 바다가 잔잔하기를 빌었다."],"title":"예린이가 쓴 가상 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#5','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',3,'mc','auto','상상만으로 지어낸 표현이 국가유산을 알리는 데 알맞지 않은 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"mc","stem":"상상만으로 지어낸 표현이 국가유산을 알리는 데 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"국가유산의 참모습과 가치를 잘못 전할 수 있기 때문이에요","correct":true},{"t":"상상하면 재미가 없기 때문이에요","mis":"SO4-1-u2-X17"},{"t":"표현은 원래 재미로만 하기 때문이에요","mis":"SO4-1-u2-X19"},{"t":"사실은 표현할 수 없기 때문이에요","mis":"SO4-1-u2-X17"}],"explanation":["지어내면 사실이 아니에요.","참모습이 바뀌어요.","잘못 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#6','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',3,'ox','auto','해녀의 물질처럼 형태가 없는 무형유산도 공연·일기·역할놀이로 표현할 수 있어요.',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"ox","stem":"해녀의 물질처럼 형태가 없는 무형유산도 공연·일기·역할놀이로 표현할 수 있어요.","answer":"O","reason_options":[{"t":"노래·춤·몸짓·글로 그 모습을 생생하게 나타낼 수 있기 때문에","correct":true},{"t":"형태가 없는 것은 나타낼 방법이 없기 때문에","mis":"SO4-1-u2-X18"}],"mis":"SO4-1-u2-X18","explanation":["물질은 형태가 없어요.","몸짓과 글로 나타내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#7','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',3,'mc','auto','표현 계획 ㉯와 ㉰의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X18','SO4-1-u2-X17']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"mc","stem":"표현 계획 ㉯와 ㉰의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"옛사람이 되어 그 생활 모습을 나타내요","correct":true},{"t":"둘 다 노래와 춤으로만 나타내요","mis":"SO4-1-u2-X18"},{"t":"둘 다 사실 없이 지어내요","mis":"SO4-1-u2-X17"},{"t":"둘 다 사진을 찍어 붙여요","mis":"SO4-1-u2-X18"}],"explanation":["㉯는 일기예요.","㉰는 역할놀이예요.","옛사람이 되어요."],"asset":{"type":"passage","lines":["㉮ 손을 맞잡고 원을 그리며 강강술래를 노래하고 춤춘다.","㉯ 옛 해녀가 되어 하루를 일기로 쓴다.","㉰ 대본을 만들어 옛사람들이 배를 타고 고기 잡는 장면을 연기한다.","㉱ 옛 서당의 모습을 네 칸 만화로 그린다."],"title":"솔빛반의 표현 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#8','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',4,'essay','teacher','예린이의 가상 일기에서 사실과 맞지 않는 부분을 찾아 고쳐 쓰고, 가상 일기를 쓸 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C5","difficulty":4,"kind":"essay","stem":"예린이의 가상 일기에서 사실과 맞지 않는 부분을 찾아 고쳐 쓰고, 가상 일기를 쓸 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 휴대 전화로 바다 날씨를 찾아본 부분이 맞지 않아요. 「물에 들어가기 전에 하늘과 물결을 살펴 바다 날씨를 짐작했다.」로 고쳐요. 가상 일기는 조사한 역사적 사실을 토대로 상상을 더해 써야 해요.","scoring_points":["맞지 않는 부분을 찾았는가","옛날에 맞게 고쳐 썼는가","역사적 사실을 토대로 쓴다는 점을 썼는가"]},"explanation":["맞지 않는 곳을 찾아요.","옛날에 맞게 고쳐요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["나는 옛날 바닷가 마을의 해녀다.","물에 들어가기 전에 휴대 전화로 바다 날씨를 찾아보았다.","숨을 참고 바닷속에 들어가 전복과 소라를 땄다.","물 위로 올라와 숨을 내쉬며 동료들과 노래를 불렀다.","저녁에는 딴 것을 나누며 내일 바다가 잔잔하기를 빌었다."],"title":"예린이가 쓴 가상 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#9','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',4,'mc','auto','탈춤을 표현하려는 모둠에게 가장 알맞은 계획은 무엇인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X18','SO4-1-u2-X19']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C5","difficulty":4,"kind":"mc","stem":"탈춤을 표현하려는 모둠에게 가장 알맞은 계획은 무엇인가요?","options":[{"t":"탈춤의 뜻과 동작을 조사한 뒤 탈을 쓰고 공연해요","correct":true},{"t":"조사 없이 요즘 춤을 섞어 공연해요","mis":"SO4-1-u2-X17"},{"t":"탈춤으로 계산 문제를 만들어 풀어요","mis":"SO4-1-u2-X18"},{"t":"탈을 사서 교실에 걸어 두기만 해요","mis":"SO4-1-u2-X19"}],"explanation":["먼저 조사해요.","사실 위에 나타내요.","공연해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L05_challenge#10','soc',4,1,'u2','L05','g4_1_soc_u2_L05_challenge','lesson_challenge','SO4-1-u2-C5',4,'essay','teacher','조상들의 생활 모습을 표현하면 좋은 점 두 가지를 쓰고, 내가 해 보고 싶은 표현 방법을 하나 골라 무엇을 표현할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C5","difficulty":4,"kind":"essay","stem":"조상들의 생활 모습을 표현하면 좋은 점 두 가지를 쓰고, 내가 해 보고 싶은 표현 방법을 하나 골라 무엇을 표현할지 쓰세요.","answer_guide":{"answer":"예: 표현하면 우리 지역 국가유산을 널리 알릴 수 있고, 국가유산의 가치를 더 잘 이해할 수 있어요. 나는 옛 서당 아이가 되어 가상 일기를 쓰고 싶어요. 훈장님 앞에서 소리 내어 글을 읽은 하루를 쓸 거예요.","scoring_points":["좋은 점 두 가지를 썼는가","표현 방법 하나를 골랐는가","무엇을 표현할지 썼는가"]},"explanation":["좋은 점을 떠올려요.","방법을 골라요.","표현할 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#1','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',1,'mc','auto','미래의 국가유산이 될 만한 것을 정할 때 가장 먼저 생각할 점은 무엇인가요?',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C6","difficulty":1,"kind":"mc","stem":"미래의 국가유산이 될 만한 것을 정할 때 가장 먼저 생각할 점은 무엇인가요?","options":[{"t":"미래에도 소중한 가치가 있을지","correct":true},{"t":"가장 새것인지","mis":"SO4-1-u2-X20"},{"t":"가장 비싼지","mis":"SO4-1-u2-X20"},{"t":"내가 좋아하는지","mis":"SO4-1-u2-X20"}],"explanation":["미래의 국가유산이에요.","가치가 기준이에요.","미래에도 소중할지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#2','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C1',1,'sa','auto','형태 없이 소리·춤·솜씨로 전해 오는 국가유산을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"sa","stem":"형태 없이 소리·춤·솜씨로 전해 오는 국가유산을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["무형유산"],"explanation":["형태가 없어요.","무형◯◯이에요.","무형유산이에요."],"mis":"SO4-1-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#3','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C3',1,'ox','auto','국가유산이 있는 곳에 직접 찾아가 살펴보는 것을 답사라고 해요.',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"ox","stem":"국가유산이 있는 곳에 직접 찾아가 살펴보는 것을 답사라고 해요.","answer":"O","reason_options":[{"t":"현장에서 직접 보고 확인하는 조사 방법이기 때문에","correct":true},{"t":"답사는 누리집에서 검색하는 방법이기 때문에","mis":"SO4-1-u2-X09"}],"mis":"SO4-1-u2-X09","explanation":["직접 가요.","현장을 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#4','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',1,'mc','auto','국가유산 안내판에 꼭 담아야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C6","difficulty":1,"kind":"mc","stem":"국가유산 안내판에 꼭 담아야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"국가유산의 특징과 가치","correct":true},{"t":"만든 사람의 기분","mis":"SO4-1-u2-X33"},{"t":"안내판을 만든 날의 날씨","mis":"SO4-1-u2-X33"},{"t":"국가유산의 가격","mis":"SO4-1-u2-X05"}],"explanation":["안내판은 소개해요.","무엇이 중요할까요?","특징과 가치예요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 한옥","종류 — 형태가 있는 문화유산","특징 — 온돌방과 마루가 있고 처마 끝이 올라가 있다.","가치 — 계절에 맞게 지내는 슬기와 아름다움이 담겼다.","부탁 — 기둥과 벽을 만지거나 낙서하지 말아 주세요."],"title":"솔빛반 국가유산 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#5','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C2',2,'mc','auto','처마 끝이 올라간 곡선처럼 아름다움에 관한 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"mc","stem":"처마 끝이 올라간 곡선처럼 아름다움에 관한 가치는 무엇인가요?","options":[{"t":"심미적 가치","correct":true},{"t":"과학적 가치","mis":"SO4-1-u2-X06"},{"t":"역사적 가치","mis":"SO4-1-u2-X06"},{"t":"생태환경적 가치","mis":"SO4-1-u2-X06"}],"explanation":["곡선이에요.","아름다움이에요.","심미적 가치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#6','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',2,'mc','auto','미래의 국가유산을 알맞게 고른 친구는 누구인가요?',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"mc","stem":"미래의 국가유산을 알맞게 고른 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"도윤","mis":"SO4-1-u2-X20"},{"t":"예준","mis":"SO4-1-u2-X20"},{"t":"세 친구 모두","mis":"SO4-1-u2-X20"}],"explanation":["새것·비싼 것이 아니에요.","함께 이어 온 것이에요.","하린이에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"미래의 국가유산으로 어제 산 새 게임기를 그릴래."},{"who":"하린","text":"나는 우리 마을이 해마다 함께 여는 줄다리기 놀이를 그릴래."},{"who":"예준","text":"나는 가장 비싼 물건을 그릴래."},{"who":"서아","text":"왜 그것을 골랐는지 까닭도 같이 써 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#7','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C4',2,'ox','auto','안내판의 특징 줄에는 있는 그대로의 사실을 적었어요.',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"ox","stem":"안내판의 특징 줄에는 있는 그대로의 사실을 적었어요.","answer":"O","reason_options":[{"t":"온돌방·마루·처마는 눈으로 확인할 수 있는 사실이기 때문에","correct":true},{"t":"특징 줄에는 느낌만 적어야 하기 때문에","mis":"SO4-1-u2-X13"}],"mis":"SO4-1-u2-X13","explanation":["특징 줄을 읽어요.","눈으로 확인돼요.","그래서 O예요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 한옥","종류 — 형태가 있는 문화유산","특징 — 온돌방과 마루가 있고 처마 끝이 올라가 있다.","가치 — 계절에 맞게 지내는 슬기와 아름다움이 담겼다.","부탁 — 기둥과 벽을 만지거나 낙서하지 말아 주세요."],"title":"솔빛반 국가유산 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#8','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',2,'match','auto','주제①에서 배운 활동과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"match","stem":"주제①에서 배운 활동과 하는 일을 알맞게 이으세요.","pairs":[{"l":"조사","r":"책·누리집·해설사·답사로 알아보기"},{"l":"정리","r":"특징은 사실, 가치는 헤아려 적기"},{"l":"표현","r":"공연·가상 일기·역할놀이로 나타내기"}],"mis":"SO4-1-u2-X18","explanation":["알아보기예요.","적기예요.","나타내기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#9','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',2,'blank','auto','서아의 말처럼 미래의 국가유산을 그릴 때는 고른 것과 함께 (    )도 써요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"blank","stem":"서아의 말처럼 미래의 국가유산을 그릴 때는 고른 것과 함께 (    )도 써요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"그것을 고른 까닭","correct":true},{"t":"그것의 가격","mis":"SO4-1-u2-X20"},{"t":"산 가게 이름","mis":"SO4-1-u2-X20"},{"t":"좋아하는 색","mis":"SO4-1-u2-X20"}],"explanation":["서아의 말을 읽어요.","왜 골랐는지예요.","고른 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"미래의 국가유산으로 어제 산 새 게임기를 그릴래."},{"who":"하린","text":"나는 우리 마을이 해마다 함께 여는 줄다리기 놀이를 그릴래."},{"who":"예준","text":"나는 가장 비싼 물건을 그릴래."},{"who":"서아","text":"왜 그것을 골랐는지 까닭도 같이 써 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_basic#10','soc',4,1,'u2','L06','g4_1_soc_u2_L06_basic','lesson_basic','SO4-1-u2-C6',3,'mc','auto','국가유산 안내판을 만들 때 가장 알맞은 차례는 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X05']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"mc","stem":"국가유산 안내판을 만들 때 가장 알맞은 차례는 무엇인가요?","options":[{"t":"소개할 국가유산 정하기 → 특징과 가치 조사·정리하기 → 안내판에 담기","correct":true},{"t":"안내판 꾸미기 → 아무 국가유산이나 고르기","mis":"SO4-1-u2-X33"},{"t":"안내판에 생각나는 대로 쓰기 → 조사는 하지 않기","mis":"SO4-1-u2-X33"},{"t":"가격 알아보기 → 비싼 것만 쓰기","mis":"SO4-1-u2-X05"}],"explanation":["먼저 정해요.","조사·정리해요.","안내판에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#1','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C1',2,'mc','auto','석탑·판소리·한옥·강강술래를 두 칸으로 바르게 나눈 것은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"mc","stem":"석탑·판소리·한옥·강강술래를 두 칸으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"석탑·한옥 / 판소리·강강술래","correct":true},{"t":"석탑·판소리 / 한옥·강강술래","mis":"SO4-1-u2-X03"},{"t":"석탑·강강술래 / 판소리·한옥","mis":"SO4-1-u2-X03"},{"t":"네 가지 모두 한 칸","mis":"SO4-1-u2-X02"}],"explanation":["형태가 있나요?","석탑·한옥은 있어요.","판소리·강강술래는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#2','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',2,'ox','auto','도윤이가 고른 새 게임기는 새것이라서 미래의 국가유산으로 가장 알맞아요.',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"ox","stem":"도윤이가 고른 새 게임기는 새것이라서 미래의 국가유산으로 가장 알맞아요.","answer":"X","reason_options":[{"t":"새것인지보다 미래에도 소중한 가치가 있을지가 중요하기 때문에","correct":true},{"t":"가장 새것일수록 오래 전해지기 때문에","mis":"SO4-1-u2-X20"}],"mis":"SO4-1-u2-X20","explanation":["새것이 기준이 아니에요.","가치가 기준이에요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"미래의 국가유산으로 어제 산 새 게임기를 그릴래."},{"who":"하린","text":"나는 우리 마을이 해마다 함께 여는 줄다리기 놀이를 그릴래."},{"who":"예준","text":"나는 가장 비싼 물건을 그릴래."},{"who":"서아","text":"왜 그것을 골랐는지 까닭도 같이 써 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#3','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',3,'error','auto','안내판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X13']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"error","stem":"안내판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「가치 줄은 아무 말이나 써도 돼.」","correct":true,"mis_target":"SO4-1-u2-X33"},{"t":"친구 가 — 「특징 줄은 사실이라 정확해야 해.」","mis":"SO4-1-u2-X13"},{"t":"친구 나 — 「부탁 줄은 국가유산을 지키는 데 도움이 돼.」","mis":"SO4-1-u2-X33"}],"explanation":["가치는 특징에서 헤아려요.","아무 말이나가 아니에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 한옥","종류 — 형태가 있는 문화유산","특징 — 온돌방과 마루가 있고 처마 끝이 올라가 있다.","가치 — 계절에 맞게 지내는 슬기와 아름다움이 담겼다.","부탁 — 기둥과 벽을 만지거나 낙서하지 말아 주세요."],"title":"솔빛반 국가유산 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#4','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C2',3,'mc','auto','안내판의 가치 줄에 담긴 가치를 바르게 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X07','SO4-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"안내판의 가치 줄에 담긴 가치를 바르게 고른 것은 무엇인가요?","options":[{"t":"과학적 가치와 심미적 가치","correct":true},{"t":"역사적 가치 하나","mis":"SO4-1-u2-X07"},{"t":"생태환경적 가치와 가격의 가치","mis":"SO4-1-u2-X05"},{"t":"아무 가치도 없어요","mis":"SO4-1-u2-X05"}],"explanation":["계절에 맞게 지내는 슬기예요.","아름다움이에요.","과학적·심미적 가치예요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 한옥","종류 — 형태가 있는 문화유산","특징 — 온돌방과 마루가 있고 처마 끝이 올라가 있다.","가치 — 계절에 맞게 지내는 슬기와 아름다움이 담겼다.","부탁 — 기둥과 벽을 만지거나 낙서하지 말아 주세요."],"title":"솔빛반 국가유산 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#5','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C5',3,'mc','auto','주제①에서 국가유산을 조사·정리·표현하며 얻은 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"mc","stem":"주제①에서 국가유산을 조사·정리·표현하며 얻은 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"국가유산을 소중히 여기고 지키려는 마음","correct":true},{"t":"국가유산은 재미없다는 마음","mis":"SO4-1-u2-X19"},{"t":"표현만 잘하면 된다는 마음","mis":"SO4-1-u2-X19"},{"t":"조사는 귀찮다는 마음","mis":"SO4-1-u2-X19"}],"explanation":["알고 조사했어요.","표현했어요.","소중히 여겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#6','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',3,'ox','auto','하린이가 고른 마을 줄다리기 놀이는 형태가 없지만 미래의 국가유산이 될 수 있어요.',ARRAY['SO4-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"ox","stem":"하린이가 고른 마을 줄다리기 놀이는 형태가 없지만 미래의 국가유산이 될 수 있어요.","answer":"O","reason_options":[{"t":"마을 사람들이 함께 이어 온 놀이로 미래에도 소중한 가치가 있을 수 있기 때문에","correct":true},{"t":"형태가 없는 것은 국가유산이 될 수 없기 때문에","mis":"SO4-1-u2-X02"}],"mis":"SO4-1-u2-X02","explanation":["줄다리기는 놀이예요.","형태가 없어도 돼요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"미래의 국가유산으로 어제 산 새 게임기를 그릴래."},{"who":"하린","text":"나는 우리 마을이 해마다 함께 여는 줄다리기 놀이를 그릴래."},{"who":"예준","text":"나는 가장 비싼 물건을 그릴래."},{"who":"서아","text":"왜 그것을 골랐는지 까닭도 같이 써 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#7','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',3,'mc','auto','예준이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X20','SO4-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"mc","stem":"예준이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"값보다 미래에도 소중한 가치가 있을지 생각해 봐","correct":true},{"t":"맞아, 비쌀수록 국가유산이야","mis":"SO4-1-u2-X20"},{"t":"맞아, 새것일수록 좋아","mis":"SO4-1-u2-X20"},{"t":"까닭은 쓰지 않아도 돼","mis":"SO4-1-u2-X33"}],"explanation":["예준이는 값으로 골랐어요.","가치가 기준이에요.","알맞게 말해 줘요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"미래의 국가유산으로 어제 산 새 게임기를 그릴래."},{"who":"하린","text":"나는 우리 마을이 해마다 함께 여는 줄다리기 놀이를 그릴래."},{"who":"예준","text":"나는 가장 비싼 물건을 그릴래."},{"who":"서아","text":"왜 그것을 골랐는지 까닭도 같이 써 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#8','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',4,'essay','teacher','미래의 국가유산으로 남기고 싶은 것을 하나 정하고, 미래에도 소중할 까닭을 가치와 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C6","difficulty":4,"kind":"essay","stem":"미래의 국가유산으로 남기고 싶은 것을 하나 정하고, 미래에도 소중할 까닭을 가치와 이어 쓰세요.","answer_guide":{"answer":"예: 우리 학교 학생들이 해마다 함께 심고 가꾸는 꽃밭 가꾸기 활동을 남기고 싶어요. 여러 세대 학생들이 이어 온 일이라 역사적 가치가 있고, 자연과 어울리는 생태환경적 가치도 있어 미래에도 소중할 거예요.","scoring_points":["남기고 싶은 것을 하나 정했는가","가치와 이어 까닭을 썼는가","새것·비싼 것이 아닌 가치로 판단했는가"]},"explanation":["하나 정해요.","가치를 떠올려요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#9','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',4,'mc','auto','안내판을 더 좋게 고치는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X13','SO4-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C6","difficulty":4,"kind":"mc","stem":"안내판을 더 좋게 고치는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"조사한 사실을 더 확인해 만든 때도 채워 넣어요","correct":true},{"t":"사실이 아니어도 재미있는 이야기를 지어 넣어요","mis":"SO4-1-u2-X17"},{"t":"가치 줄을 지워요","mis":"SO4-1-u2-X13"},{"t":"부탁 줄에 가격을 적어요","mis":"SO4-1-u2-X05"}],"explanation":["정보를 더해요.","사실을 확인해요.","만든 때를 채워요."],"asset":{"type":"passage","lines":["이름 — 솔빛군 옛 한옥","종류 — 형태가 있는 문화유산","특징 — 온돌방과 마루가 있고 처마 끝이 올라가 있다.","가치 — 계절에 맞게 지내는 슬기와 아름다움이 담겼다.","부탁 — 기둥과 벽을 만지거나 낙서하지 말아 주세요."],"title":"솔빛반 국가유산 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L06_challenge#10','soc',4,1,'u2','L06','g4_1_soc_u2_L06_challenge','lesson_challenge','SO4-1-u2-C6',4,'essay','teacher','주제①에서 배운 것을 국가유산의 뜻·가치·조사·표현 가운데 세 가지를 넣어 세 문장으로 정리하세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C6","difficulty":4,"kind":"essay","stem":"주제①에서 배운 것을 국가유산의 뜻·가치·조사·표현 가운데 세 가지를 넣어 세 문장으로 정리하세요.","answer_guide":{"answer":"예: 국가유산은 조상 대대로 전해 내려온, 보존할 가치가 있는 것이에요. 국가유산에는 역사적·과학적·심미적·생태환경적 가치가 담겨 있어요. 책·누리집·해설사·답사로 조사하고 공연·가상 일기·역할놀이로 표현할 수 있어요.","scoring_points":["세 가지를 골라 넣었는가","각 내용을 바르게 썼는가","세 문장으로 정리했는가"]},"explanation":["세 가지를 골라요.","바르게 써요.","세 문장으로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#1','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',1,'mc','auto','지역의 역사가 담긴 유물이나 자료를 모아 전시하는 곳은 어디인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"mc","stem":"지역의 역사가 담긴 유물이나 자료를 모아 전시하는 곳은 어디인가요?","options":[{"t":"박물관","correct":true},{"t":"기념관","mis":"SO4-1-u2-X21"},{"t":"유적지","mis":"SO4-1-u2-X21"},{"t":"놀이터","mis":"SO4-1-u2-X22"}],"explanation":["유물과 자료예요.","모아 전시해요.","박물관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#2','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',1,'sa','auto','옛사람들이 쓰다가 남긴 물건을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"sa","stem":"옛사람들이 쓰다가 남긴 물건을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["유물"],"explanation":["옛사람이 남겼어요.","◯물이에요.","유물이에요."],"mis":"SO4-1-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#3','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',1,'ox','auto','기념관은 역사적 인물이나 사건을 오래 기억하려고 만든 곳이에요.',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"ox","stem":"기념관은 역사적 인물이나 사건을 오래 기억하려고 만든 곳이에요.","answer":"O","reason_options":[{"t":"인물과 사건을 잊지 않고 기억하도록 세운 곳이기 때문에","correct":true},{"t":"기념관은 물건을 사고파는 곳이기 때문에","mis":"SO4-1-u2-X21"}],"mis":"SO4-1-u2-X21","explanation":["기념관이에요.","오래 기억해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#4','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',1,'mc','auto','옛사람들의 흔적이나 유적이 남아 있는 곳은 어디인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"mc","stem":"옛사람들의 흔적이나 유적이 남아 있는 곳은 어디인가요?","options":[{"t":"유적지","correct":true},{"t":"박물관","mis":"SO4-1-u2-X21"},{"t":"기념관","mis":"SO4-1-u2-X21"},{"t":"도서관","mis":"SO4-1-u2-X22"}],"explanation":["흔적이 남아 있어요.","유적이 있어요.","유적지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#5','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',2,'mc','auto','㉯가 솔빛군에 세워진 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X23','SO4-1-u2-X22']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"mc","stem":"㉯가 솔빛군에 세워진 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"그 독립운동가가 이 고장에서 태어나고 자랐기 때문이에요","correct":true},{"t":"건물을 크게 지을 수 있어서예요","mis":"SO4-1-u2-X23"},{"t":"교통이 편해서예요","mis":"SO4-1-u2-X23"},{"t":"놀이 기구를 놓으려고요","mis":"SO4-1-u2-X22"}],"explanation":["기념관이에요.","이 고장 사람이에요.","인연이 깊어요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#6','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',2,'ox','auto','박물관·기념관·유적지는 모두 지역의 역사를 알 수 있는 장소예요.',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"ox","stem":"박물관·기념관·유적지는 모두 지역의 역사를 알 수 있는 장소예요.","answer":"O","reason_options":[{"t":"셋 다 조상들의 생활 모습과 지역의 역사를 알려 주기 때문에","correct":true},{"t":"셋 가운데 박물관만 역사와 관계있기 때문에","mis":"SO4-1-u2-X21"}],"mis":"SO4-1-u2-X21","explanation":["세 장소를 떠올려요.","모두 역사를 알려 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#7','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',2,'match','auto','장소와 그곳의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"match","stem":"장소와 그곳의 종류를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"박물관"},{"l":"㉯","r":"기념관"},{"l":"㉰","r":"유적지"}],"mis":"SO4-1-u2-X21","explanation":["전시해요.","기억해요.","흔적이 있어요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#8','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',2,'mc','auto','신문 기사로 알 수 있는 솔빛군의 역사는 무엇인가요?',ARRAY['SO4-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"mc","stem":"신문 기사로 알 수 있는 솔빛군의 역사는 무엇인가요?","options":[{"t":"옛날 솔빛성을 쌓은 일","correct":true},{"t":"다른 나라의 축제","mis":"SO4-1-u2-X22"},{"t":"내년의 도시 계획","mis":"SO4-1-u2-X22"},{"t":"새로 생긴 놀이공원","mis":"SO4-1-u2-X22"}],"explanation":["기사를 읽어요.","성을 쌓을 때 쓴 도구예요.","솔빛성을 쌓은 일이에요."],"asset":{"type":"passage","lines":["솔빛군 역사 박물관이 새 전시를 열었다.","옛날 솔빛성을 쌓을 때 쓴 도구를 모형으로 만들어 보여 준다.","성을 쌓는 차례를 그림과 영상으로도 볼 수 있다.","관람객들은 성이 어떻게 만들어졌는지 알게 되었다고 말했다."],"title":"솔빛 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#9','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',2,'blank','auto','우리 지역의 역사 장소는 신문 기사를 읽거나 스마트 기기로 (    )해서 찾을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X22']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"blank","stem":"우리 지역의 역사 장소는 신문 기사를 읽거나 스마트 기기로 (    )해서 찾을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"검색","correct":true},{"t":"계산","mis":"SO4-1-u2-X22"},{"t":"운동","mis":"SO4-1-u2-X22"},{"t":"요리","mis":"SO4-1-u2-X22"}],"explanation":["스마트 기기예요.","찾아봐요.","검색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_basic#10','soc',4,1,'u2','L07','g4_1_soc_u2_L07_basic','lesson_basic','SO4-1-u2-C7',3,'mc','auto','역사를 알 수 있는 장소로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u2-X22']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"mc","stem":"역사를 알 수 있는 장소로 알맞지 않은 것은 무엇인가요?","options":[{"t":"새로 지은 백화점","correct":true},{"t":"옛 성터","mis":"SO4-1-u2-X22"},{"t":"독립운동가 기념관","mis":"SO4-1-u2-X22"},{"t":"지역 역사 박물관","mis":"SO4-1-u2-X22"}],"explanation":["역사가 담겼나요?","백화점은 아니에요.","새로 지은 백화점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#1','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',2,'mc','auto','박물관이 성을 쌓는 차례를 그림과 영상으로도 보여 주는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"mc","stem":"박물관이 성을 쌓는 차례를 그림과 영상으로도 보여 주는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"관람객이 지역의 역사를 더 쉽게 알도록 하려고","correct":true},{"t":"관람객이 빨리 나가도록 하려고","mis":"SO4-1-u2-X21"},{"t":"유물을 팔려고","mis":"SO4-1-u2-X21"},{"t":"성을 새로 지으려고","mis":"SO4-1-u2-X22"}],"explanation":["그림과 영상이에요.","쉽게 알 수 있어요.","역사를 알려 줘요."],"asset":{"type":"passage","lines":["솔빛군 역사 박물관이 새 전시를 열었다.","옛날 솔빛성을 쌓을 때 쓴 도구를 모형으로 만들어 보여 준다.","성을 쌓는 차례를 그림과 영상으로도 볼 수 있다.","관람객들은 성이 어떻게 만들어졌는지 알게 되었다고 말했다."],"title":"솔빛 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#2','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',2,'ox','auto','㉰에 가면 아주 오래전 사람들이 남긴 흔적을 직접 볼 수 있어요.',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"ox","stem":"㉰에 가면 아주 오래전 사람들이 남긴 흔적을 직접 볼 수 있어요.","answer":"O","reason_options":[{"t":"유적지는 옛사람들의 흔적이 그 자리에 남아 있는 곳이기 때문에","correct":true},{"t":"유적지는 인물을 기억하려고 새로 지은 건물이기 때문에","mis":"SO4-1-u2-X21"}],"mis":"SO4-1-u2-X21","explanation":["㉰는 유적지예요.","흔적이 남아 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#3','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',3,'error','auto','안내를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"error","stem":"안내를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉯는 옛 흔적이 남아 있어서 유적지야.」","correct":true,"mis_target":"SO4-1-u2-X21"},{"t":"친구 나 — 「㉮에서는 옛 그릇과 농기구를 볼 수 있어.」","mis":"SO4-1-u2-X21"},{"t":"친구 다 — 「㉰는 오래전 사람들이 남긴 무덤이 있는 유적지야.」","mis":"SO4-1-u2-X21"}],"explanation":["㉯는 기념관이에요.","인물을 기억해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#4','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',3,'mc','auto','우리 고장 출신 화가를 오래 기억하려고 세운 곳은 어떤 장소에 가장 가까운가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"mc","stem":"우리 고장 출신 화가를 오래 기억하려고 세운 곳은 어떤 장소에 가장 가까운가요?","options":[{"t":"기념관","correct":true},{"t":"유적지","mis":"SO4-1-u2-X21"},{"t":"박물관","mis":"SO4-1-u2-X21"},{"t":"놀이공원","mis":"SO4-1-u2-X22"}],"explanation":["인물을 기억해요.","오래 기억하려고 세웠어요.","기념관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#5','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',3,'mc','auto','어떤 지역에 그 지역 인물의 기념관이 있는 까닭을 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u2-X23']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 지역에 그 지역 인물의 기념관이 있는 까닭을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"그 인물이 그 지역과 인연이 깊어 오래 기억하려고","correct":true},{"t":"땅값이 싸서","mis":"SO4-1-u2-X23"},{"t":"사람이 많이 살아서","mis":"SO4-1-u2-X23"},{"t":"아무 지역에나 세우기 때문에","mis":"SO4-1-u2-X23"}],"explanation":["인물과 지역이에요.","인연이 깊어요.","오래 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#6','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',3,'ox','auto','역사를 알 수 있는 장소는 신문 기사만 보고 찾을 수 있어요.',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"ox","stem":"역사를 알 수 있는 장소는 신문 기사만 보고 찾을 수 있어요.","answer":"X","reason_options":[{"t":"검색하거나 직접 답사해서도 찾을 수 있기 때문에","correct":true},{"t":"역사 장소는 신문에만 나오기 때문에","mis":"SO4-1-u2-X09"}],"mis":"SO4-1-u2-X09","explanation":["방법은 여러 가지예요.","검색·답사도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#7','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',3,'mc','auto','옛사람들이 농사지을 때 쓴 도구를 보고 싶다면 어디로 가면 좋을까요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"mc","stem":"옛사람들이 농사지을 때 쓴 도구를 보고 싶다면 어디로 가면 좋을까요?","options":[{"t":"㉮ 솔빛군 역사 박물관","correct":true},{"t":"㉯ 솔빛군 독립운동가 기념관","mis":"SO4-1-u2-X21"},{"t":"㉰ 솔빛군 고인돌 유적지","mis":"SO4-1-u2-X21"},{"t":"새로 문을 연 장난감 가게","mis":"SO4-1-u2-X22"}],"explanation":["농기구는 유물이에요.","유물은 박물관에 모아요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#8','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',4,'essay','teacher','㉮·㉯·㉰ 가운데 두 곳을 골라 각각 어떤 곳인지 쓰고, 그곳에서 알 수 있는 것을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C7","difficulty":4,"kind":"essay","stem":"㉮·㉯·㉰ 가운데 두 곳을 골라 각각 어떤 곳인지 쓰고, 그곳에서 알 수 있는 것을 쓰세요.","answer_guide":{"answer":"예: ㉮ 솔빛군 역사 박물관은 유물과 자료를 모아 전시하는 곳이라 옛사람들이 쓴 그릇과 농기구를 볼 수 있어요. ㉰ 솔빛군 고인돌 유적지는 옛사람들의 흔적이 남은 곳이라 아주 오래전 사람들이 남긴 큰 돌 무덤을 볼 수 있어요.","scoring_points":["두 곳을 골랐는가","각 장소가 어떤 곳인지 바르게 썼는가","그곳에서 알 수 있는 것을 썼는가"]},"explanation":["두 곳을 골라요.","어떤 곳인지 써요.","알 수 있는 것을 써요."],"asset":{"type":"passage","lines":["㉮ 솔빛군 역사 박물관 — 옛 그릇·농기구 같은 유물과 자료를 모아 전시한다.","㉯ 솔빛군 독립운동가 기념관 — 이 고장에서 태어나고 자란 독립운동가를 기억하려고 세웠다.","㉰ 솔빛군 고인돌 유적지 — 아주 오래전 사람들이 남긴 큰 돌 무덤이 남아 있다."],"title":"솔빛군 역사 장소 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#9','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',4,'mc','auto','가족과 갈 역사 장소를 고르는데 친구가 옛사람들이 살던 자리를 그대로 보고 싶다고 했어요. 어디가 가장 알맞을까요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C7","difficulty":4,"kind":"mc","stem":"가족과 갈 역사 장소를 고르는데 친구가 옛사람들이 살던 자리를 그대로 보고 싶다고 했어요. 어디가 가장 알맞을까요?","options":[{"t":"유적지","correct":true},{"t":"박물관","mis":"SO4-1-u2-X21"},{"t":"기념관","mis":"SO4-1-u2-X21"},{"t":"백화점","mis":"SO4-1-u2-X22"}],"explanation":["살던 자리예요.","그대로 남아 있어요.","유적지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L07_challenge#10','soc',4,1,'u2','L07','g4_1_soc_u2_L07_challenge','lesson_challenge','SO4-1-u2-C7',4,'essay','teacher','신문 기사를 읽고 솔빛군 역사 박물관에서 알 수 있는 지역의 역사를 쓰고, 박물관이 역사를 알려 주는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C7","difficulty":4,"kind":"essay","stem":"신문 기사를 읽고 솔빛군 역사 박물관에서 알 수 있는 지역의 역사를 쓰고, 박물관이 역사를 알려 주는 방법을 쓰세요.","answer_guide":{"answer":"예: 옛날 솔빛성을 어떻게 쌓았는지 알 수 있어요. 박물관은 성을 쌓을 때 쓴 도구를 모형으로 만들어 보여 주고, 성을 쌓는 차례를 그림과 영상으로도 보여 주어 역사를 알려 줘요.","scoring_points":["기사 속 지역의 역사를 썼는가","박물관이 알려 주는 방법을 썼는가","기사 내용과 맞게 썼는가"]},"explanation":["기사를 읽어요.","역사를 찾아요.","방법을 써요."],"asset":{"type":"passage","lines":["솔빛군 역사 박물관이 새 전시를 열었다.","옛날 솔빛성을 쌓을 때 쓴 도구를 모형으로 만들어 보여 준다.","성을 쌓는 차례를 그림과 영상으로도 볼 수 있다.","관람객들은 성이 어떻게 만들어졌는지 알게 되었다고 말했다."],"title":"솔빛 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#1','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',1,'mc','auto','우리 지역의 역사를 조사할 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO4-1-u2-X24']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"mc","stem":"우리 지역의 역사를 조사할 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"조사 계획 세우기","correct":true},{"t":"조사 보고서 쓰기","mis":"SO4-1-u2-X24"},{"t":"느낀 점 발표하기","mis":"SO4-1-u2-X24"},{"t":"친구와 놀기","mis":"SO4-1-u2-X24"}],"explanation":["차례가 있어요.","계획이 먼저예요.","계획 세우기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#2','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',1,'sa','auto','조사를 마친 뒤 알게 된 점과 느낀 점을 넣어 쓰는 글을 조사 ○○○라고 해요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"sa","stem":"조사를 마친 뒤 알게 된 점과 느낀 점을 넣어 쓰는 글을 조사 ○○○라고 해요. 세 글자로 쓰세요.","answer":["보고서"],"explanation":["조사를 마쳤어요.","보고◯예요.","보고서예요."],"mis":"SO4-1-u2-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#3','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',1,'ox','auto','박물관 누리집에 들어가 자료를 찾는 것은 인터넷 조사예요.',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"ox","stem":"박물관 누리집에 들어가 자료를 찾는 것은 인터넷 조사예요.","answer":"O","reason_options":[{"t":"누리집을 검색해 자료를 찾는 방법이기 때문에","correct":true},{"t":"누리집에서 찾는 것은 답사이기 때문에","mis":"SO4-1-u2-X09"}],"mis":"SO4-1-u2-X09","explanation":["누리집이에요.","인터넷으로 찾아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#4','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',1,'mc','auto','책이나 기록물을 찾아보는 조사 방법은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"mc","stem":"책이나 기록물을 찾아보는 조사 방법은 무엇인가요?","options":[{"t":"문헌 조사","correct":true},{"t":"면담 조사","mis":"SO4-1-u2-X09"},{"t":"답사","mis":"SO4-1-u2-X09"},{"t":"인터넷 조사","mis":"SO4-1-u2-X09"}],"explanation":["책과 기록물이에요.","문헌이에요.","문헌 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#5','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',2,'mc','auto','조사 계획서에 들어가지 않아야 할 줄은 무엇인가요?',ARRAY['SO4-1-u2-X25']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"mc","stem":"조사 계획서에 들어가지 않아야 할 줄은 무엇인가요?","options":[{"t":"㉠ 알게 된 점","correct":true},{"t":"조사 방법","mis":"SO4-1-u2-X25"},{"t":"역할 나누기","mis":"SO4-1-u2-X25"},{"t":"조사 장소","mis":"SO4-1-u2-X25"}],"explanation":["계획은 조사 전이에요.","알게 된 점은 조사 뒤예요.","㉠이에요."],"asset":{"type":"passage","lines":["조사 주제 — 고인돌 유적지에 살던 옛사람들","조사 장소 — 솔빛군 고인돌 유적지","조사 내용 — 옛사람들은 이곳에서 어떻게 살았을까?","조사 방법 — 인터넷 조사, 답사","역할 나누기 — 검색·기록·준비물·정리","㉠ 알게 된 점 — 큰 돌을 여럿이 힘을 모아 옮겼다."],"title":"도윤이 모둠 조사 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_basic#6','soc',4,1,'u2','L08','g4_1_soc_u2_L08_basic','lesson_basic','SO4-1-u2-C8',2,'ox','auto','하린이처럼 누리집에서 찾은 내용을 책에서도 확인하는 것은 좋은 태도예요.',ARRAY['SO4-1-u2-X26']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"ox","stem":"하린이처럼 누리집에서 찾은 내용을 책에서도 확인하는 것은 좋은 태도예요.","answer":"O","reason_options":[{"t":"인터넷 정보가 모두 믿을 만한 것은 아니어서 확인이 필요하기 때문에","correct":true},{"t":"인터넷 정보는 모두 맞으니 확인할 필요가 없기 때문에","mis":"SO4-1-u2-X26"}],"mis":"SO4-1-u2-X26","explanation":["누리집 내용이에요.","책에서도 확인해요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"유적지 누리집을 찾았어. 가상 현실로 안을 둘러볼 수도 있대."},{"who":"하린","text":"누리집 내용이 맞는지 책에서도 확인해 보자."},{"who":"예준","text":"유적지에 갈 때는 보호자와 함께 가고, 안전하게 다니자."},{"who":"서아","text":"유적지를 오래 돌봐 오신 할아버지께 여쭤볼 것도 적어 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
