INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#2','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',2,'ox','auto','여러 조사 방법을 함께 쓰면 더 자세하고 정확하게 알 수 있어요.',ARRAY['SO4-1-u2-X11']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"ox","stem":"여러 조사 방법을 함께 쓰면 더 자세하고 정확하게 알 수 있어요.","answer":"O","reason_options":[{"t":"한 가지만 쓰면 놓치는 것을 다른 방법이 채워 주기 때문에","correct":true},{"t":"방법이 많으면 오히려 아무것도 알 수 없기 때문에","mis":"SO4-1-u2-X11"}],"mis":"SO4-1-u2-X11","explanation":["방법이 여럿이에요.","서로 채워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#3','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',3,'error','auto','조사 계획서를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X25']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"error","stem":"조사 계획서를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「알게 된 점은 계획서에 미리 써 두는 거야.」","correct":true,"mis_target":"SO4-1-u2-X25"},{"t":"친구 가 — 「조사 방법에 답사를 쓴 건 알맞아.」","mis":"SO4-1-u2-X25"},{"t":"친구 다 — 「역할을 나누면 무엇을 맡을지 분명해져.」","mis":"SO4-1-u2-X25"}],"explanation":["알게 된 점은 조사 뒤예요.","보고서에 써요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["조사 주제 — 고인돌 유적지에 살던 옛사람들","조사 장소 — 솔빛군 고인돌 유적지","조사 내용 — 옛사람들은 이곳에서 어떻게 살았을까?","조사 방법 — 인터넷 조사, 답사","역할 나누기 — 검색·기록·준비물·정리","㉠ 알게 된 점 — 큰 돌을 여럿이 힘을 모아 옮겼다."],"title":"도윤이 모둠 조사 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#4','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',3,'mc','auto','계획서의 ㉠은 어디로 옮겨 써야 하나요?',ARRAY['SO4-1-u2-X25']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"mc","stem":"계획서의 ㉠은 어디로 옮겨 써야 하나요?","options":[{"t":"조사 보고서","correct":true},{"t":"조사 주제 줄","mis":"SO4-1-u2-X25"},{"t":"역할 나누기 줄","mis":"SO4-1-u2-X25"},{"t":"조사 방법 줄","mis":"SO4-1-u2-X25"}],"explanation":["㉠은 알게 된 점이에요.","조사 뒤에 써요.","보고서예요."],"asset":{"type":"passage","lines":["조사 주제 — 고인돌 유적지에 살던 옛사람들","조사 장소 — 솔빛군 고인돌 유적지","조사 내용 — 옛사람들은 이곳에서 어떻게 살았을까?","조사 방법 — 인터넷 조사, 답사","역할 나누기 — 검색·기록·준비물·정리","㉠ 알게 된 점 — 큰 돌을 여럿이 힘을 모아 옮겼다."],"title":"도윤이 모둠 조사 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#5','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',3,'mc','auto','인터넷에서 찾은 내용이 믿을 만한지 확인하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X26']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"mc","stem":"인터넷에서 찾은 내용이 믿을 만한지 확인하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"공공 기관 누리집이나 책에서 같은 내용을 찾아 견줘요","correct":true},{"t":"글이 길면 믿어요","mis":"SO4-1-u2-X26"},{"t":"맨 처음 나온 글을 믿어요","mis":"SO4-1-u2-X26"},{"t":"그림이 예쁘면 믿어요","mis":"SO4-1-u2-X26"}],"explanation":["그대로 믿지 않아요.","다른 자료와 견줘요.","확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#6','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',3,'ox','auto','계획 없이 답사부터 가면 무엇을 볼지 몰라 헤맬 수 있어요.',ARRAY['SO4-1-u2-X24']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"ox","stem":"계획 없이 답사부터 가면 무엇을 볼지 몰라 헤맬 수 있어요.","answer":"O","reason_options":[{"t":"계획을 세워야 무엇을 어떻게 알아볼지 분명해지기 때문에","correct":true},{"t":"조사는 계획 없이 하는 것이 더 빠르기 때문에","mis":"SO4-1-u2-X24"}],"mis":"SO4-1-u2-X24","explanation":["계획이 먼저예요.","무엇을 볼지 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#7','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',3,'mc','auto','도윤이가 말한 가상 현실 전시의 좋은 점은 무엇인가요?',ARRAY['SO4-1-u2-X11','SO4-1-u2-X12','SO4-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"mc","stem":"도윤이가 말한 가상 현실 전시의 좋은 점은 무엇인가요?","options":[{"t":"직접 가지 않고도 전시 안을 둘러볼 수 있어요","correct":true},{"t":"답사를 가지 않아도 모든 것을 알 수 있어요","mis":"SO4-1-u2-X11"},{"t":"보호자 없이 유적지에 갈 수 있어요","mis":"SO4-1-u2-X12"},{"t":"찾은 내용을 확인할 필요가 없어요","mis":"SO4-1-u2-X26"}],"explanation":["가상 현실이에요.","화면으로 둘러봐요.","가지 않고도 봐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"유적지 누리집을 찾았어. 가상 현실로 안을 둘러볼 수도 있대."},{"who":"하린","text":"누리집 내용이 맞는지 책에서도 확인해 보자."},{"who":"예준","text":"유적지에 갈 때는 보호자와 함께 가고, 안전하게 다니자."},{"who":"서아","text":"유적지를 오래 돌봐 오신 할아버지께 여쭤볼 것도 적어 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#8','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',4,'essay','teacher','계획서의 잘못된 곳을 찾아 바르게 고치고, 조사 보고서에 들어갈 내용 두 가지를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C8","difficulty":4,"kind":"essay","stem":"계획서의 잘못된 곳을 찾아 바르게 고치고, 조사 보고서에 들어갈 내용 두 가지를 쓰세요.","answer_guide":{"answer":"예: ㉠ 알게 된 점은 계획서가 아니라 조사를 마친 뒤 보고서에 써야 해요. 그 자리에는 준비물이나 주의할 점을 써요. 조사 보고서에는 조사해서 새롭게 알게 된 점과 느낀 점을 넣어요.","scoring_points":["㉠이 잘못되었음을 찾았는가","계획서에 알맞은 내용으로 고쳤는가","보고서 내용 두 가지를 썼는가"]},"explanation":["잘못된 줄을 찾아요.","고쳐요.","보고서 내용을 써요."],"asset":{"type":"passage","lines":["조사 주제 — 고인돌 유적지에 살던 옛사람들","조사 장소 — 솔빛군 고인돌 유적지","조사 내용 — 옛사람들은 이곳에서 어떻게 살았을까?","조사 방법 — 인터넷 조사, 답사","역할 나누기 — 검색·기록·준비물·정리","㉠ 알게 된 점 — 큰 돌을 여럿이 힘을 모아 옮겼다."],"title":"도윤이 모둠 조사 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#9','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',4,'mc','auto','고인돌 유적지 조사를 바른 차례로 늘어놓은 것은 무엇인가요?',ARRAY['SO4-1-u2-X24','SO4-1-u2-X25']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C8","difficulty":4,"kind":"mc","stem":"고인돌 유적지 조사를 바른 차례로 늘어놓은 것은 무엇인가요?","options":[{"t":"계획서 쓰기 → 누리집 조사와 답사 → 알게 된 점·느낀 점을 넣어 보고서 쓰기","correct":true},{"t":"보고서 쓰기 → 계획서 쓰기 → 답사","mis":"SO4-1-u2-X24"},{"t":"답사 → 보고서 쓰기 → 계획서 쓰기","mis":"SO4-1-u2-X24"},{"t":"계획서에 느낀 점 쓰기 → 답사 → 끝","mis":"SO4-1-u2-X25"}],"explanation":["계획이 먼저예요.","그다음 조사예요.","마지막이 보고서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L08_challenge#10','soc',4,1,'u2','L08','g4_1_soc_u2_L08_challenge','lesson_challenge','SO4-1-u2-C8',4,'essay','teacher','대화에 나온 조사 방법을 두 가지 이상 찾아 쓰고, 각 방법을 할 때 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C8","difficulty":4,"kind":"essay","stem":"대화에 나온 조사 방법을 두 가지 이상 찾아 쓰고, 각 방법을 할 때 주의할 점을 쓰세요.","answer_guide":{"answer":"예: 도윤이는 인터넷 조사를 했어요. 찾은 내용이 믿을 만한지 책에서도 확인해야 해요. 예준이는 답사를 말했어요. 보호자와 함께 가고 안전에 유의해야 해요. 서아는 면담 조사를 말했어요. 여쭤볼 것을 미리 적어 가요.","scoring_points":["조사 방법 두 가지 이상을 찾았는가","각 방법의 주의할 점을 썼는가","대화 내용과 맞게 썼는가"]},"explanation":["방법을 찾아요.","주의할 점을 떠올려요.","짝지어 써요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"유적지 누리집을 찾았어. 가상 현실로 안을 둘러볼 수도 있대."},{"who":"하린","text":"누리집 내용이 맞는지 책에서도 확인해 보자."},{"who":"예준","text":"유적지에 갈 때는 보호자와 함께 가고, 안전하게 다니자."},{"who":"서아","text":"유적지를 오래 돌봐 오신 할아버지께 여쭤볼 것도 적어 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#1','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',1,'mc','auto','우리 지역의 역사를 소개하는 자료로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C9","difficulty":1,"kind":"mc","stem":"우리 지역의 역사를 소개하는 자료로 알맞지 않은 것은 무엇인가요?","options":[{"t":"오늘의 급식표","correct":true},{"t":"소개 동영상","mis":"SO4-1-u2-X18"},{"t":"안내 책자","mis":"SO4-1-u2-X18"},{"t":"역사 신문","mis":"SO4-1-u2-X18"}],"explanation":["역사를 알려 줘요.","급식표는 아니에요.","오늘의 급식표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#2','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',1,'sa','auto','박물관에서 자료를 모으고 연구하며 전시를 기획하는 사람을 무엇이라고 하나요?','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C9","difficulty":1,"kind":"sa","stem":"박물관에서 자료를 모으고 연구하며 전시를 기획하는 사람을 무엇이라고 하나요?","answer":["큐레이터","학예사"],"explanation":["박물관에서 일해요.","전시를 기획해요.","큐레이터(학예사)예요."],"mis":"SO4-1-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#3','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',1,'ox','auto','다른 곳에서 모은 사진을 쓸 때는 출처를 표시해야 해요.',ARRAY['SO4-1-u2-X27']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C9","difficulty":1,"kind":"ox","stem":"다른 곳에서 모은 사진을 쓸 때는 출처를 표시해야 해요.","answer":"O","reason_options":[{"t":"사진을 찍은 사람의 것임을 밝혀야 하기 때문에","correct":true},{"t":"모은 사진은 내가 찍은 것처럼 써도 되기 때문에","mis":"SO4-1-u2-X27"}],"mis":"SO4-1-u2-X27","explanation":["모은 사진이에요.","누구 것인지 밝혀요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#4','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',1,'mc','auto','역사 신문에 넣으면 더 재미있는 것은 무엇인가요?',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C9","difficulty":1,"kind":"mc","stem":"역사 신문에 넣으면 더 재미있는 것은 무엇인가요?","options":[{"t":"퀴즈나 인터뷰","correct":true},{"t":"빈 종이","mis":"SO4-1-u2-X28"},{"t":"계산 문제","mis":"SO4-1-u2-X28"},{"t":"시간표","mis":"SO4-1-u2-X28"}],"explanation":["신문이에요.","읽는 사람이 즐거워요.","퀴즈나 인터뷰예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#5','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',2,'mc','auto','동영상을 만드는 차례로 바른 것은 무엇인가요?',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"mc","stem":"동영상을 만드는 차례로 바른 것은 무엇인가요?","options":[{"t":"㉯ → ㉱ → ㉮ → ㉰","correct":true},{"t":"㉮ → ㉯ → ㉱ → ㉰","mis":"SO4-1-u2-X28"},{"t":"㉰ → ㉯ → ㉱ → ㉮","mis":"SO4-1-u2-X28"},{"t":"㉱ → ㉮ → ㉰ → ㉯","mis":"SO4-1-u2-X28"}],"explanation":["먼저 찍어요.","도구를 골라 편집해요.","마지막에 소개해요."],"asset":{"type":"passage","lines":["㉮ 역사적 특징이 잘 드러나게 편집한다.","㉯ 국가유산의 사진과 동영상을 찍는다.","㉰ 많은 사람이 보도록 소개한다.","㉱ 컴퓨터나 휴대 전화의 편집 도구를 고른다."],"title":"동영상 만들기 카드(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#6','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',2,'ox','auto','4모둠의 사진전은 그대로 전시해도 괜찮아요.',ARRAY['SO4-1-u2-X27']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"ox","stem":"4모둠의 사진전은 그대로 전시해도 괜찮아요.","answer":"X","reason_options":[{"t":"누리집에서 모은 사진에 출처를 표시하지 않았기 때문에","correct":true},{"t":"사진전에는 출처가 필요 없기 때문에","mis":"SO4-1-u2-X27"}],"mis":"SO4-1-u2-X27","explanation":["누리집에서 모았어요.","출처가 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1모둠 — 고인돌 유적지 소개 동영상","2모둠 — 솔빛성 안내 책자","3모둠 — 독립운동가 소개 신문(퀴즈·인터뷰 칸)","4모둠 — 옛 그릇 사진전(누리집에서 모은 사진, 출처 없음)","5모둠 — 역사 조사 보고서"],"title":"우리 반 역사 박물관 전시 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#7','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',2,'match','auto','소개 자료와 그 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"match","stem":"소개 자료와 그 좋은 점을 알맞게 이으세요.","pairs":[{"l":"동영상","r":"움직임과 소리로 생생하게 알려요"},{"l":"안내 책자","r":"책처럼 자세하게 소개해요"},{"l":"역사 신문","r":"퀴즈·인터뷰로 재미있게 알려요"}],"mis":"SO4-1-u2-X28","explanation":["움직이고 소리 나요.","자세해요.","재미있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#8','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',2,'blank','auto','우리 반 역사 박물관에서 소개할 때는 듣는 사람이 (    ) 말해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"blank","stem":"우리 반 역사 박물관에서 소개할 때는 듣는 사람이 (    ) 말해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"이해하기 쉽게","correct":true},{"t":"알아듣기 어렵게","mis":"SO4-1-u2-X16"},{"t":"아주 빠르게","mis":"SO4-1-u2-X16"},{"t":"혼자만 들리게","mis":"SO4-1-u2-X16"}],"explanation":["듣는 사람을 생각해요.","쉽게 말해요.","이해하기 쉽게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
