INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_basic#10','soc',4,1,'u2','L09','g4_1_soc_u2_L09_basic','lesson_basic','SO4-1-u2-C9',3,'mc','auto','우리 지역의 역사를 소개하는 활동을 하고 나면 어떤 마음이 생기나요?',ARRAY['SO4-1-u2-X19']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"우리 지역의 역사를 소개하는 활동을 하고 나면 어떤 마음이 생기나요?","options":[{"t":"우리 지역이 자랑스럽고 역사를 지키고 싶은 마음","correct":true},{"t":"역사가 지겨운 마음","mis":"SO4-1-u2-X19"},{"t":"다른 지역을 무시하는 마음","mis":"SO4-1-u2-X19"},{"t":"아무 생각이 없는 마음","mis":"SO4-1-u2-X19"}],"explanation":["역사를 알렸어요.","자긍심이 생겨요.","지키고 싶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#1','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',2,'mc','auto','다른 모둠의 전시를 관람하는 태도로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"mc","stem":"다른 모둠의 전시를 관람하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"관심을 가지고 보며 설명에 귀 기울여요","correct":true},{"t":"우리 모둠 자료만 봐요","mis":"SO4-1-u2-X16"},{"t":"설명하는 중에 떠들어요","mis":"SO4-1-u2-X16"},{"t":"전시 자료를 만지고 옮겨요","mis":"SO4-1-u2-X16"}],"explanation":["다른 모둠 자료예요.","관심 있게 봐요.","귀 기울여 들어요."],"asset":{"type":"passage","lines":["1모둠 — 고인돌 유적지 소개 동영상","2모둠 — 솔빛성 안내 책자","3모둠 — 독립운동가 소개 신문(퀴즈·인터뷰 칸)","4모둠 — 옛 그릇 사진전(누리집에서 모은 사진, 출처 없음)","5모둠 — 역사 조사 보고서"],"title":"우리 반 역사 박물관 전시 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#2','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',2,'ox','auto','안내 책자는 넣을 내용을 정하고 그림·사진을 붙여 자세하게 소개하는 자료예요.',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"ox","stem":"안내 책자는 넣을 내용을 정하고 그림·사진을 붙여 자세하게 소개하는 자료예요.","answer":"O","reason_options":[{"t":"책처럼 여러 장에 자세히 담을 수 있기 때문에","correct":true},{"t":"안내 책자는 움직임과 소리로 알리는 자료이기 때문에","mis":"SO4-1-u2-X28"}],"mis":"SO4-1-u2-X28","explanation":["책자예요.","자세히 담아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#3','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',3,'error','auto','전시 목록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X27','SO4-1-u2-X28']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"error","stem":"전시 목록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「4모둠 사진은 우리가 모았으니 출처를 안 써도 돼.」","correct":true,"mis_target":"SO4-1-u2-X27"},{"t":"친구 가 — 「1모둠 동영상은 움직임과 소리로 생생해.」","mis":"SO4-1-u2-X28"},{"t":"친구 나 — 「3모둠 신문의 퀴즈는 관람객을 즐겁게 해.」","mis":"SO4-1-u2-X28"}],"explanation":["모은 사진이에요.","출처를 써야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["1모둠 — 고인돌 유적지 소개 동영상","2모둠 — 솔빛성 안내 책자","3모둠 — 독립운동가 소개 신문(퀴즈·인터뷰 칸)","4모둠 — 옛 그릇 사진전(누리집에서 모은 사진, 출처 없음)","5모둠 — 역사 조사 보고서"],"title":"우리 반 역사 박물관 전시 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#4','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',3,'mc','auto','큐레이터가 하는 일로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u2-X29']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"큐레이터가 하는 일로 알맞지 않은 것은 무엇인가요?","options":[{"t":"유적지의 유물을 몰래 가져가요","correct":true},{"t":"자료를 모으고 연구해요","mis":"SO4-1-u2-X29"},{"t":"전시를 기획해요","mis":"SO4-1-u2-X29"},{"t":"관람객에게 자료를 설명해요","mis":"SO4-1-u2-X29"}],"explanation":["큐레이터는 박물관에서 일해요.","모으고 연구하고 설명해요.","가져가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#5','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',3,'mc','auto','5모둠 보고서가 다른 자료와 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"5모둠 보고서가 다른 자료와 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"조사 내용과 알게 된 점·느낀 점을 그대로 보여 줘요","correct":true},{"t":"움직임과 소리로 보여 줘요","mis":"SO4-1-u2-X28"},{"t":"사진에 설명을 붙여 전시해요","mis":"SO4-1-u2-X28"},{"t":"퀴즈와 인터뷰를 넣어요","mis":"SO4-1-u2-X28"}],"explanation":["보고서예요.","조사한 것을 담아요.","알게 된 점·느낀 점이에요."],"asset":{"type":"passage","lines":["1모둠 — 고인돌 유적지 소개 동영상","2모둠 — 솔빛성 안내 책자","3모둠 — 독립운동가 소개 신문(퀴즈·인터뷰 칸)","4모둠 — 옛 그릇 사진전(누리집에서 모은 사진, 출처 없음)","5모둠 — 역사 조사 보고서"],"title":"우리 반 역사 박물관 전시 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#6','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',3,'ox','auto','동영상은 편집부터 한 뒤에 사진과 동영상을 찍어요.',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"ox","stem":"동영상은 편집부터 한 뒤에 사진과 동영상을 찍어요.","answer":"X","reason_options":[{"t":"찍은 사진과 영상이 있어야 편집할 수 있기 때문에","correct":true},{"t":"편집 도구만 있으면 찍지 않아도 되기 때문에","mis":"SO4-1-u2-X28"}],"mis":"SO4-1-u2-X28","explanation":["찍어야 편집해요.","촬영이 먼저예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 역사적 특징이 잘 드러나게 편집한다.","㉯ 국가유산의 사진과 동영상을 찍는다.","㉰ 많은 사람이 보도록 소개한다.","㉱ 컴퓨터나 휴대 전화의 편집 도구를 고른다."],"title":"동영상 만들기 카드(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#7','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',3,'mc','auto','역사적 인물을 소개하는 신문을 만들 때 바른 차례는 무엇인가요?',ARRAY['SO4-1-u2-X28','SO4-1-u2-X27']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"역사적 인물을 소개하는 신문을 만들 때 바른 차례는 무엇인가요?","options":[{"t":"신문 제목 → 기사 제목 → 그림·사진·글 넣기","correct":true},{"t":"그림·사진 넣기 → 신문 제목 지우기","mis":"SO4-1-u2-X28"},{"t":"기사 제목만 쓰고 끝내기","mis":"SO4-1-u2-X28"},{"t":"글 → 신문 제목 → 아무 사진이나 넣기","mis":"SO4-1-u2-X27"}],"explanation":["신문 제목이 먼저예요.","기사 제목을 써요.","그림·사진·글을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#8','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',4,'essay','teacher','전시 목록에서 고쳐야 할 모둠을 찾아 까닭과 고치는 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C9","difficulty":4,"kind":"essay","stem":"전시 목록에서 고쳐야 할 모둠을 찾아 까닭과 고치는 방법을 쓰세요.","answer_guide":{"answer":"예: 4모둠을 고쳐야 해요. 누리집에서 모은 사진에 출처를 표시하지 않았기 때문이에요. 사진마다 어느 누리집에서 가져왔는지 출처를 적어 붙이거나, 직접 찍은 사진으로 바꾸어 전시해요.","scoring_points":["고쳐야 할 모둠을 찾았는가","출처가 없다는 까닭을 썼는가","출처 표시 등 고치는 방법을 썼는가"]},"explanation":["목록을 읽어요.","문제를 찾아요.","고치는 방법을 써요."],"asset":{"type":"passage","lines":["1모둠 — 고인돌 유적지 소개 동영상","2모둠 — 솔빛성 안내 책자","3모둠 — 독립운동가 소개 신문(퀴즈·인터뷰 칸)","4모둠 — 옛 그릇 사진전(누리집에서 모은 사진, 출처 없음)","5모둠 — 역사 조사 보고서"],"title":"우리 반 역사 박물관 전시 목록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#9','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',4,'mc','auto','솔빛성을 처음 보는 사람에게 성의 모습을 생생하게 알리고 싶어요. 가장 알맞은 자료와 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X28','SO4-1-u2-X27','SO4-1-u2-X18']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C9","difficulty":4,"kind":"mc","stem":"솔빛성을 처음 보는 사람에게 성의 모습을 생생하게 알리고 싶어요. 가장 알맞은 자료와 까닭은 무엇인가요?","options":[{"t":"동영상 — 움직임과 소리로 생생하게 보여 줄 수 있어서","correct":true},{"t":"보고서 — 느낀 점을 쓸 수 있어서","mis":"SO4-1-u2-X28"},{"t":"사진전 — 출처를 쓰지 않아도 돼서","mis":"SO4-1-u2-X27"},{"t":"급식표 — 누구나 보아서","mis":"SO4-1-u2-X18"}],"explanation":["생생하게 알려요.","움직임과 소리예요.","동영상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L09_challenge#10','soc',4,1,'u2','L09','g4_1_soc_u2_L09_challenge','lesson_challenge','SO4-1-u2-C9',4,'essay','teacher','우리 지역의 역사를 소개할 자료를 하나 골라 만드는 방법을 차례대로 쓰고, 소개할 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C9","difficulty":4,"kind":"essay","stem":"우리 지역의 역사를 소개할 자료를 하나 골라 만드는 방법을 차례대로 쓰고, 소개할 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 안내 책자를 만들 거예요. 먼저 넣을 내용을 정하고, 그림과 사진을 붙인 뒤, 역사적 특징을 써요. 다른 곳에서 가져온 사진은 출처를 표시하고, 소개할 때는 듣는 사람이 이해하기 쉽게 말해요.","scoring_points":["소개 자료를 하나 골랐는가","만드는 방법을 차례대로 썼는가","출처 표시·쉽게 말하기 등 지킬 점을 썼는가"]},"explanation":["자료를 골라요.","차례를 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#1','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',1,'mc','auto','보존이란 무엇인가요?',ARRAY['SO4-1-u2-X30']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"mc","stem":"보존이란 무엇인가요?","options":[{"t":"잘 보살피고 지켜서 계속 남아 있게 하는 것","correct":true},{"t":"빨리 없애는 것","mis":"SO4-1-u2-X30"},{"t":"새로 바꾸는 것","mis":"SO4-1-u2-X30"},{"t":"아무도 못 보게 숨겨 두는 것","mis":"SO4-1-u2-X30"}],"explanation":["지켜요.","계속 남게 해요.","보존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#2','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',1,'sa','auto','국가유산이 깨지거나 상하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"sa","stem":"국가유산이 깨지거나 상하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["훼손"],"explanation":["깨지고 상해요.","훼◯이에요.","훼손이에요."],"mis":"SO4-1-u2-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#3','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',1,'ox','auto','어린이도 우리 지역의 역사를 보존하는 데 힘을 보탤 수 있어요.',ARRAY['SO4-1-u2-X31']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"ox","stem":"어린이도 우리 지역의 역사를 보존하는 데 힘을 보탤 수 있어요.","answer":"O","reason_options":[{"t":"관심 갖고 공부하기·지킴이 활동·널리 알리기를 할 수 있기 때문에","correct":true},{"t":"보존은 어른들만 하는 일이기 때문에","mis":"SO4-1-u2-X31"}],"mis":"SO4-1-u2-X31","explanation":["어린이도 할 수 있어요.","공부·지킴이·알리기예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#4','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',1,'mc','auto','우리 지역의 역사를 지키려는 노력으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u2-X30']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"mc","stem":"우리 지역의 역사를 지키려는 노력으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"유적지 담벼락에 낙서하기","correct":true},{"t":"국가유산 관리·보존하기","mis":"SO4-1-u2-X30"},{"t":"무형유산 알리는 행사 열기","mis":"SO4-1-u2-X30"},{"t":"지킴이 활동 참여하기","mis":"SO4-1-u2-X30"}],"explanation":["지키는 노력을 떠올려요.","낙서는 훼손이에요.","낙서하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#5','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',2,'mc','auto','기사 ㉮에 나온 문제는 무엇인가요?',ARRAY['SO4-1-u2-X32','SO4-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"mc","stem":"기사 ㉮에 나온 문제는 무엇인가요?","options":[{"t":"이을 사람이 없어 노래가 사라질 위기예요","correct":true},{"t":"노래를 부르는 사람이 너무 많아요","mis":"SO4-1-u2-X32"},{"t":"노래가 새로 만들어졌어요","mis":"SO4-1-u2-X32"},{"t":"노래 값이 올랐어요","mis":"SO4-1-u2-X05"}],"explanation":["부를 분이 몇 분만 남았어요.","배우려는 사람이 없어요.","사라질 위기예요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#6','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',2,'ox','auto','기사 ㉯처럼 국가유산이 훼손되어도 그대로 두면 저절로 되살아나요.',ARRAY['SO4-1-u2-X32']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"ox","stem":"기사 ㉯처럼 국가유산이 훼손되어도 그대로 두면 저절로 되살아나요.","answer":"X","reason_options":[{"t":"한번 훼손된 국가유산은 고치고 돌보지 않으면 다음 세대에 전해지지 못하기 때문에","correct":true},{"t":"국가유산은 시간이 지나면 저절로 고쳐지기 때문에","mis":"SO4-1-u2-X32"}],"mis":"SO4-1-u2-X32","explanation":["돌이 깨졌어요.","저절로 고쳐지지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#7','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',2,'match','auto','노력과 그 노력을 주로 하는 쪽을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"match","stem":"노력과 그 노력을 주로 하는 쪽을 알맞게 이으세요.","pairs":[{"l":"① 깨진 담벼락 고치기","r":"지역"},{"l":"⑤ 성 둘레 청소하는 지킴이 활동","r":"우리"}],"mis":"SO4-1-u2-X31","explanation":["고치는 일은 지역이 해요.","청소는 우리도 해요.","함께 지켜요."],"asset":{"type":"passage","lines":["① 깨진 담벼락을 고치고 돌본다.","② 농사 노래를 알리는 공연 행사를 연다.","③ 유네스코 지정을 받으려고 노력한다.","④ 우리 지역의 역사를 공부한다.","⑤ 성 둘레를 청소하는 지킴이 활동을 한다.","⑥ 친구와 가족에게 우리 지역의 역사를 알린다."],"title":"솔빛군 역사를 지키는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#8','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',2,'blank','auto','국가유산이 유네스코 지정을 받으면 보호에 필요한 (    ) 지원을 받을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X08']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"blank","stem":"국가유산이 유네스코 지정을 받으면 보호에 필요한 (    ) 지원을 받을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"재정·기술","correct":true},{"t":"놀이 기구","mis":"SO4-1-u2-X08"},{"t":"가격 결정","mis":"SO4-1-u2-X08"},{"t":"출입 금지","mis":"SO4-1-u2-X08"}],"explanation":["지정을 받아요.","보호를 도와요.","재정·기술 지원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#9','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',2,'mc','auto','우리 지역의 역사를 보존하지 않으면 생기는 일은 무엇인가요?',ARRAY['SO4-1-u2-X32','SO4-1-u2-X30']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"mc","stem":"우리 지역의 역사를 보존하지 않으면 생기는 일은 무엇인가요?","options":[{"t":"전통을 잇지 못하고 다음 세대에 전해지지 못해요","correct":true},{"t":"역사가 저절로 늘어나요","mis":"SO4-1-u2-X32"},{"t":"국가유산이 새것이 돼요","mis":"SO4-1-u2-X30"},{"t":"아무 일도 생기지 않아요","mis":"SO4-1-u2-X32"}],"explanation":["보존하지 않아요.","끊기고 훼손돼요.","전해지지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_basic#10','soc',4,1,'u2','L10','g4_1_soc_u2_L10_basic','lesson_basic','SO4-1-u2-C10',3,'mc','auto','우리 지역의 역사를 보존해야 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X30','SO4-1-u2-X31']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"mc","stem":"우리 지역의 역사를 보존해야 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전통이 담겨 있고 다음 세대를 위한 것이기 때문이에요","correct":true},{"t":"돈을 벌 수 있기 때문이에요","mis":"SO4-1-u2-X05"},{"t":"낡았으니 곧 없애려고요","mis":"SO4-1-u2-X30"},{"t":"어른들만 알면 되기 때문이에요","mis":"SO4-1-u2-X31"}],"explanation":["전통이 담겼어요.","다음 세대가 있어요.","그래서 보존해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#1','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',2,'mc','auto','①~⑥ 가운데 어린이가 할 수 있는 일을 모두 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X31']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"mc","stem":"①~⑥ 가운데 어린이가 할 수 있는 일을 모두 고른 것은 무엇인가요?","options":[{"t":"④, ⑤, ⑥","correct":true},{"t":"①, ②, ③","mis":"SO4-1-u2-X31"},{"t":"①, ④, ⑤","mis":"SO4-1-u2-X31"},{"t":"②, ③, ⑥","mis":"SO4-1-u2-X31"}],"explanation":["공부해요.","청소하고 알려요.","④, ⑤, ⑥이에요."],"asset":{"type":"passage","lines":["① 깨진 담벼락을 고치고 돌본다.","② 농사 노래를 알리는 공연 행사를 연다.","③ 유네스코 지정을 받으려고 노력한다.","④ 우리 지역의 역사를 공부한다.","⑤ 성 둘레를 청소하는 지킴이 활동을 한다.","⑥ 친구와 가족에게 우리 지역의 역사를 알린다."],"title":"솔빛군 역사를 지키는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#2','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',2,'ox','auto','유네스코 지정을 받으면 그 국가유산은 아무도 볼 수 없게 돼요.',ARRAY['SO4-1-u2-X08']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"ox","stem":"유네스코 지정을 받으면 그 국가유산은 아무도 볼 수 없게 돼요.","answer":"X","reason_options":[{"t":"지정은 가치를 인정받아 보호를 위한 지원을 받는 것이기 때문에","correct":true},{"t":"지정되면 문을 닫고 감춰 두어야 하기 때문에","mis":"SO4-1-u2-X08"}],"mis":"SO4-1-u2-X08","explanation":["가치를 인정받아요.","지원을 받아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#3','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',3,'error','auto','두 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X32']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"error","stem":"두 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「노래는 형태가 없으니 사라져도 괜찮아.」","correct":true,"mis_target":"SO4-1-u2-X32"},{"t":"친구 가 — 「두 기사 모두 역사가 제대로 보존되지 못한 문제야.」","mis":"SO4-1-u2-X32"},{"t":"친구 나 — 「㉯는 국가유산이 훼손된 일이야.」","mis":"SO4-1-u2-X32"}],"explanation":["노래도 소중한 무형유산이에요.","사라지면 전통이 끊겨요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#4','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',3,'mc','auto','기사 ㉮의 문제를 풀기 위한 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X30','SO4-1-u2-X31']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"mc","stem":"기사 ㉮의 문제를 풀기 위한 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"노래를 알리는 행사를 열어 배우려는 사람을 늘려요","correct":true},{"t":"담벼락을 새 벽돌로 바꿔요","mis":"SO4-1-u2-X30"},{"t":"노래를 아무도 못 듣게 녹음만 해 숨겨요","mis":"SO4-1-u2-X30"},{"t":"어른들끼리만 알고 있어요","mis":"SO4-1-u2-X31"}],"explanation":["이을 사람이 없어요.","알려서 배우게 해요.","행사를 열어요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#5','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',3,'mc','auto','기사 ㉯의 문제를 막기 위해 우리가 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X30','SO4-1-u2-X31']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"mc","stem":"기사 ㉯의 문제를 막기 위해 우리가 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"성 둘레를 깨끗이 하고 낙서하지 않도록 알려요","correct":true},{"t":"담벼락 돌을 기념으로 가져가요","mis":"SO4-1-u2-X30"},{"t":"지역에서 다 해 줄 테니 그냥 둬요","mis":"SO4-1-u2-X31"},{"t":"담벼락을 허물고 새로 지어요","mis":"SO4-1-u2-X30"}],"explanation":["훼손과 낙서예요.","우리도 할 수 있어요.","지키고 알려요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#6','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',3,'ox','auto','많은 사람이 우리 지역의 역사에 관심을 가지면 더 잘 지켜져요.',ARRAY['SO4-1-u2-X32']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"ox","stem":"많은 사람이 우리 지역의 역사에 관심을 가지면 더 잘 지켜져요.","answer":"O","reason_options":[{"t":"관심을 가진 사람이 많을수록 함께 아끼고 돌보기 때문에","correct":true},{"t":"관심을 가질수록 국가유산이 더 빨리 닳기 때문에","mis":"SO4-1-u2-X32"}],"mis":"SO4-1-u2-X32","explanation":["관심이 모여요.","함께 돌봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#7','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',3,'mc','auto','우리 지역의 역사를 공부하고 널리 알리겠다고 다짐하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X31','SO4-1-u2-X32','SO4-1-u2-X30']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"mc","stem":"우리 지역의 역사를 공부하고 널리 알리겠다고 다짐하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"역사를 지키는 데 우리도 함께해야 하기 때문이에요","correct":true},{"t":"보존은 어른만 하면 되기 때문이에요","mis":"SO4-1-u2-X31"},{"t":"다짐만 하면 저절로 지켜지기 때문이에요","mis":"SO4-1-u2-X32"},{"t":"국가유산을 새것으로 바꾸려고요","mis":"SO4-1-u2-X30"}],"explanation":["다짐이에요.","우리도 함께해요.","실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#8','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',4,'essay','teacher','두 기사 가운데 하나를 골라 어떤 문제인지 쓰고, 지역이 할 노력과 내가 할 수 있는 일을 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":4,"kind":"essay","stem":"두 기사 가운데 하나를 골라 어떤 문제인지 쓰고, 지역이 할 노력과 내가 할 수 있는 일을 하나씩 쓰세요.","answer_guide":{"answer":"예: 기사 ㉮는 농사 노래를 이을 사람이 없어 사라질 위기라는 문제예요. 지역에서는 노래를 알리는 공연 행사를 열 수 있어요. 나는 노래를 배워 보고 친구와 가족에게 알릴 수 있어요.","scoring_points":["기사 하나를 골라 문제를 썼는가","지역이 할 노력을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["기사를 골라요.","문제를 써요.","노력을 나눠 써요."],"asset":{"type":"passage","lines":["㉮ 솔빛군에서 농사지을 때 부르던 노래를 부를 수 있는 분이 몇 분만 남았다.","㉮ 배우려는 사람을 찾지 못해 이 노래가 사라질 위기에 놓였다.","㉯ 600여 년 된 솔빛성 담벼락에 전동차가 부딪쳐 돌이 깨졌다.","㉯ 담벼락 곳곳에 낙서도 남아 있었다."],"title":"솔빛 신문 — 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#9','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',4,'mc','auto','우리 지역의 역사가 우리만의 것이 아니라 다음 세대를 위한 것이라는 말의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X30','SO4-1-u2-X32','SO4-1-u2-X31']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C10","difficulty":4,"kind":"mc","stem":"우리 지역의 역사가 우리만의 것이 아니라 다음 세대를 위한 것이라는 말의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"지금 잘 지켜야 뒤에 올 사람들도 그 역사를 만날 수 있다는 뜻이에요","correct":true},{"t":"지금 사람은 역사를 볼 수 없다는 뜻이에요","mis":"SO4-1-u2-X30"},{"t":"다음 세대가 새로 만들면 된다는 뜻이에요","mis":"SO4-1-u2-X32"},{"t":"어른들만 지키면 된다는 뜻이에요","mis":"SO4-1-u2-X31"}],"explanation":["다음 세대예요.","지금 지켜야 해요.","이어 주는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L10_challenge#10','soc',4,1,'u2','L10','g4_1_soc_u2_L10_challenge','lesson_challenge','SO4-1-u2-C10',4,'essay','teacher','①~⑥ 가운데 지역이 하는 노력과 우리가 할 수 있는 일을 하나씩 골라, 그 노력이 역사 보존에 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C10","difficulty":4,"kind":"essay","stem":"①~⑥ 가운데 지역이 하는 노력과 우리가 할 수 있는 일을 하나씩 골라, 그 노력이 역사 보존에 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: ① 깨진 담벼락을 고치고 돌보면 성이 더 훼손되지 않고 오래 남아요. ⑥ 친구와 가족에게 우리 지역의 역사를 알리면 관심을 가진 사람이 늘어 함께 지킬 수 있어요.","scoring_points":["지역이 하는 노력을 골랐는가","우리가 할 수 있는 일을 골랐는가","보존에 도움이 되는 까닭을 썼는가"]},"explanation":["지역의 노력을 골라요.","우리의 실천을 골라요.","도움이 되는 까닭을 써요."],"asset":{"type":"passage","lines":["① 깨진 담벼락을 고치고 돌본다.","② 농사 노래를 알리는 공연 행사를 연다.","③ 유네스코 지정을 받으려고 노력한다.","④ 우리 지역의 역사를 공부한다.","⑤ 성 둘레를 청소하는 지킴이 활동을 한다.","⑥ 친구와 가족에게 우리 지역의 역사를 알린다."],"title":"솔빛군 역사를 지키는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#1','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',1,'mc','auto','역사 체험 프로그램을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SO4-1-u2-X24','SO4-1-u2-X33']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C11","difficulty":1,"kind":"mc","stem":"역사 체험 프로그램을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"역사적으로 의미 있는 장소 정하기","correct":true},{"t":"프로그램 이름부터 정하기","mis":"SO4-1-u2-X24"},{"t":"간식 정하기","mis":"SO4-1-u2-X33"},{"t":"아무 놀이나 고르기","mis":"SO4-1-u2-X33"}],"explanation":["어디를 다룰까요?","장소부터 정해요.","장소 정하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#2','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C9',1,'mc','auto','박물관에서 전시를 기획하고 관람객에게 자료를 설명하는 사람은 누구인가요?',ARRAY['SO4-1-u2-X29']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C9","difficulty":1,"kind":"mc","stem":"박물관에서 전시를 기획하고 관람객에게 자료를 설명하는 사람은 누구인가요?","options":[{"t":"큐레이터","correct":true},{"t":"소방관","mis":"SO4-1-u2-X29"},{"t":"요리사","mis":"SO4-1-u2-X29"},{"t":"운전기사","mis":"SO4-1-u2-X29"}],"explanation":["박물관이에요.","전시를 기획해요.","큐레이터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#3','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C7',1,'ox','auto','박물관·기념관·유적지에서 우리 지역의 역사를 만날 수 있어요.',ARRAY['SO4-1-u2-X22']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"ox","stem":"박물관·기념관·유적지에서 우리 지역의 역사를 만날 수 있어요.","answer":"O","reason_options":[{"t":"세 곳 모두 지역의 역사가 담긴 장소이기 때문에","correct":true},{"t":"역사는 책에서만 만날 수 있기 때문에","mis":"SO4-1-u2-X22"}],"mis":"SO4-1-u2-X22","explanation":["세 장소예요.","역사가 담겼어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#4','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C8',1,'mc','auto','알게 된 점과 느낀 점을 넣어 쓰는 것은 무엇인가요?',ARRAY['SO4-1-u2-X25']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"mc","stem":"알게 된 점과 느낀 점을 넣어 쓰는 것은 무엇인가요?","options":[{"t":"조사 보고서","correct":true},{"t":"조사 계획서","mis":"SO4-1-u2-X25"},{"t":"준비물 목록","mis":"SO4-1-u2-X25"},{"t":"시간표","mis":"SO4-1-u2-X25"}],"explanation":["조사를 마쳤어요.","알게 된 점·느낀 점이에요.","보고서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#5','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',2,'mc','auto','역사가 담긴 캐릭터를 만들려는 서아에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X27']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"mc","stem":"역사가 담긴 캐릭터를 만들려는 서아에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"솔빛성의 특징을 조사해서 어울리게 그려 보자","correct":true},{"t":"맞아, 아무 동물이나 귀여우면 돼","mis":"SO4-1-u2-X33"},{"t":"다른 나라 캐릭터를 그대로 따라 그리자","mis":"SO4-1-u2-X27"},{"t":"이름만 짓고 그림은 그리지 말자","mis":"SO4-1-u2-X33"}],"explanation":["역사가 담겨야 해요.","특징을 조사해요.","어울리게 그려요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 모둠은 솔빛성 체험 프로그램을 만들자."},{"who":"도윤","text":"좋아! 먼저 솔빛성의 역사적 특징부터 조사하자."},{"who":"예준","text":"성을 쌓을 때 큰 돌을 여럿이 옮겼대. 돌 나르기 협동 놀이는 어때?"},{"who":"서아","text":"캐릭터도 만들자. 아무 동물이나 귀엽게 그리면 되겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#6','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',2,'ox','auto','도윤이의 말처럼 체험 프로그램을 만들기 전에 장소의 역사적 특징을 조사해야 해요.',ARRAY['SO4-1-u2-X33']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"ox","stem":"도윤이의 말처럼 체험 프로그램을 만들기 전에 장소의 역사적 특징을 조사해야 해요.","answer":"O","reason_options":[{"t":"특징을 알아야 그 역사를 즐기며 배울 수 있는 프로그램을 만들 수 있기 때문에","correct":true},{"t":"프로그램은 재미만 있으면 되기 때문에","mis":"SO4-1-u2-X33"}],"mis":"SO4-1-u2-X33","explanation":["특징을 알아야 해요.","역사를 담아요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 모둠은 솔빛성 체험 프로그램을 만들자."},{"who":"도윤","text":"좋아! 먼저 솔빛성의 역사적 특징부터 조사하자."},{"who":"예준","text":"성을 쌓을 때 큰 돌을 여럿이 옮겼대. 돌 나르기 협동 놀이는 어때?"},{"who":"서아","text":"캐릭터도 만들자. 아무 동물이나 귀엽게 그리면 되겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#7','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',2,'match','auto','주제②의 흐름과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"match","stem":"주제②의 흐름과 하는 일을 알맞게 이으세요.","pairs":[{"l":"장소","r":"박물관·기념관·유적지에서 역사 만나기"},{"l":"조사","r":"계획 → 조사 → 보고서"},{"l":"보존","r":"관리·지킴이 활동·널리 알리기"}],"mis":"SO4-1-u2-X24","explanation":["만나요.","알아봐요.","지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#8','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C9',2,'mc','auto','역사 소개 자료로 쓰기 어려운 것은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"mc","stem":"역사 소개 자료로 쓰기 어려운 것은 무엇인가요?","options":[{"t":"오늘의 날씨표","correct":true},{"t":"안내 책자","mis":"SO4-1-u2-X18"},{"t":"역사 신문","mis":"SO4-1-u2-X18"},{"t":"소개 동영상","mis":"SO4-1-u2-X18"}],"explanation":["역사를 알려 줘요?","날씨표는 아니에요.","오늘의 날씨표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#9','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',2,'blank','auto','예준이가 떠올린 체험 프로그램에는 솔빛성을 쌓을 때 (    ) 역사적 특징이 담겼어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X33']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"blank","stem":"예준이가 떠올린 체험 프로그램에는 솔빛성을 쌓을 때 (    ) 역사적 특징이 담겼어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"큰 돌을 여럿이 옮긴","correct":true},{"t":"성 안에 놀이 기구를 둔","mis":"SO4-1-u2-X33"},{"t":"돌을 사고판","mis":"SO4-1-u2-X33"},{"t":"성을 하루 만에 지은","mis":"SO4-1-u2-X33"}],"explanation":["예준이의 말을 읽어요.","여럿이 옮겼어요.","큰 돌을 여럿이 옮긴 것이에요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 모둠은 솔빛성 체험 프로그램을 만들자."},{"who":"도윤","text":"좋아! 먼저 솔빛성의 역사적 특징부터 조사하자."},{"who":"예준","text":"성을 쌓을 때 큰 돌을 여럿이 옮겼대. 돌 나르기 협동 놀이는 어때?"},{"who":"서아","text":"캐릭터도 만들자. 아무 동물이나 귀엽게 그리면 되겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_basic#10','soc',4,1,'u2','L11','g4_1_soc_u2_L11_basic','lesson_basic','SO4-1-u2-C11',3,'sa','auto','암호 풀기에서 옳은 문장의 번호를 작은 수부터 이어 쓰면 무엇인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"sa","stem":"암호 풀기에서 옳은 문장의 번호를 작은 수부터 이어 쓰면 무엇인가요? 숫자만 쓰세요.","answer":["135"],"explanation":["문장을 하나씩 따져요.","①·③·⑤가 옳아요.","135예요."],"asset":{"type":"passage","lines":["① 기념관은 인물이나 사건을 오래 기억하려고 세운 곳이다.","② 역사 조사는 보고서를 먼저 쓰고 계획을 세운다.","③ 면담 조사는 알 만한 분께 여쭤보는 방법이다.","④ 다른 곳에서 모은 사진은 출처 없이 써도 된다.","⑤ 어린이도 지킴이 활동으로 역사 보존에 힘을 보탤 수 있다."],"title":"암호 풀기 — 옳은 문장 번호를 작은 수부터"},"mis":"SO4-1-u2-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#1','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',2,'mc','auto','역사가 담긴 캐릭터를 만드는 차례로 바른 것은 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X27']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"mc","stem":"역사가 담긴 캐릭터를 만드는 차례로 바른 것은 무엇인가요?","options":[{"t":"사건·장소 정하기 → 특징 조사하기 → 어울리는 캐릭터 그리고 이름 짓기","correct":true},{"t":"캐릭터 그리기 → 아무 장소 붙이기","mis":"SO4-1-u2-X33"},{"t":"이름 짓기 → 조사는 하지 않기","mis":"SO4-1-u2-X33"},{"t":"다른 캐릭터 따라 그리기 → 출처 숨기기","mis":"SO4-1-u2-X27"}],"explanation":["정해요.","조사해요.","그리고 이름 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#2','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',2,'ox','auto','암호 풀기의 ② 문장은 옳아요.',ARRAY['SO4-1-u2-X24']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C11","difficulty":2,"kind":"ox","stem":"암호 풀기의 ② 문장은 옳아요.","answer":"X","reason_options":[{"t":"역사 조사는 계획을 먼저 세우고 조사한 뒤 보고서를 쓰기 때문에","correct":true},{"t":"보고서를 먼저 써야 조사가 쉬워지기 때문에","mis":"SO4-1-u2-X24"}],"mis":"SO4-1-u2-X24","explanation":["②를 읽어요.","차례가 바뀌었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 기념관은 인물이나 사건을 오래 기억하려고 세운 곳이다.","② 역사 조사는 보고서를 먼저 쓰고 계획을 세운다.","③ 면담 조사는 알 만한 분께 여쭤보는 방법이다.","④ 다른 곳에서 모은 사진은 출처 없이 써도 된다.","⑤ 어린이도 지킴이 활동으로 역사 보존에 힘을 보탤 수 있다."],"title":"암호 풀기 — 옳은 문장 번호를 작은 수부터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#3','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',3,'error','auto','암호 풀기를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X27','SO4-1-u2-X21','SO4-1-u2-X31']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"error","stem":"암호 풀기를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「④는 옳아. 모은 사진이니까 우리 것이지.」","correct":true,"mis_target":"SO4-1-u2-X27"},{"t":"친구 가 — 「①은 옳아. 기념관은 인물을 기억하는 곳이야.」","mis":"SO4-1-u2-X21"},{"t":"친구 다 — 「⑤는 옳아. 어린이도 보존에 힘을 보태.」","mis":"SO4-1-u2-X31"}],"explanation":["④를 읽어요.","출처를 밝혀야 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 기념관은 인물이나 사건을 오래 기억하려고 세운 곳이다.","② 역사 조사는 보고서를 먼저 쓰고 계획을 세운다.","③ 면담 조사는 알 만한 분께 여쭤보는 방법이다.","④ 다른 곳에서 모은 사진은 출처 없이 써도 된다.","⑤ 어린이도 지킴이 활동으로 역사 보존에 힘을 보탤 수 있다."],"title":"암호 풀기 — 옳은 문장 번호를 작은 수부터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#4','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',3,'mc','auto','고인돌 유적지를 바탕으로 만든 캐릭터로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X27']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"mc","stem":"고인돌 유적지를 바탕으로 만든 캐릭터로 가장 알맞은 것은 무엇인가요?","options":[{"t":"넓적한 돌 지붕을 머리에 인 고돌이","correct":true},{"t":"번개를 쏘는 로봇 번쩍이","mis":"SO4-1-u2-X33"},{"t":"다른 만화에 나오는 캐릭터를 그대로 그린 것","mis":"SO4-1-u2-X27"},{"t":"유적지와 관계없는 과일 캐릭터","mis":"SO4-1-u2-X33"}],"explanation":["고인돌이에요.","넓적한 돌이에요.","특징을 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#5','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C8',3,'mc','auto','주제②에서 배운 역사 조사에 대한 설명으로 옳은 것은 무엇인가요?',ARRAY['SO4-1-u2-X26','SO4-1-u2-X25','SO4-1-u2-X11']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"mc","stem":"주제②에서 배운 역사 조사에 대한 설명으로 옳은 것은 무엇인가요?","options":[{"t":"여러 방법을 함께 쓰고 찾은 내용이 믿을 만한지 확인해요","correct":true},{"t":"인터넷 정보는 확인하지 않아도 돼요","mis":"SO4-1-u2-X26"},{"t":"계획서에 느낀 점을 미리 써요","mis":"SO4-1-u2-X25"},{"t":"한 가지 방법이면 충분해요","mis":"SO4-1-u2-X11"}],"explanation":["여러 방법이에요.","확인해요.","옳은 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#6','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C10',3,'ox','auto','국가유산 보존은 지역만 노력하면 되고 어린이는 지켜보기만 하면 돼요.',ARRAY['SO4-1-u2-X31']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"ox","stem":"국가유산 보존은 지역만 노력하면 되고 어린이는 지켜보기만 하면 돼요.","answer":"X","reason_options":[{"t":"어린이도 공부하기·지킴이 활동·알리기로 함께할 수 있기 때문에","correct":true},{"t":"보존은 어른과 지역의 일이기 때문에","mis":"SO4-1-u2-X31"}],"mis":"SO4-1-u2-X31","explanation":["어린이도 할 수 있어요.","함께 지켜요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#7','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',3,'mc','auto','하린이 모둠이 만든 체험 프로그램이 좋은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"mc","stem":"하린이 모둠이 만든 체험 프로그램이 좋은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"솔빛성을 쌓은 역사를 몸으로 겪으며 배울 수 있어서","correct":true},{"t":"역사와 관계없이 재미만 있어서","mis":"SO4-1-u2-X33"},{"t":"조사하지 않고 만들어서","mis":"SO4-1-u2-X33"},{"t":"다른 지역 성의 이야기를 섞어서","mis":"SO4-1-u2-X33"}],"explanation":["돌 나르기 협동 놀이예요.","성을 쌓은 역사예요.","겪으며 배워요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"우리 모둠은 솔빛성 체험 프로그램을 만들자."},{"who":"도윤","text":"좋아! 먼저 솔빛성의 역사적 특징부터 조사하자."},{"who":"예준","text":"성을 쌓을 때 큰 돌을 여럿이 옮겼대. 돌 나르기 협동 놀이는 어때?"},{"who":"서아","text":"캐릭터도 만들자. 아무 동물이나 귀엽게 그리면 되겠지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#8','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',4,'essay','teacher','우리 지역의 역사 장소를 하나 정해 체험 프로그램이나 캐릭터를 만드는 계획을 차례대로 쓰세요. (장소 이름은 ○○로 써도 돼요)','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C11","difficulty":4,"kind":"essay","stem":"우리 지역의 역사 장소를 하나 정해 체험 프로그램이나 캐릭터를 만드는 계획을 차례대로 쓰세요. (장소 이름은 ○○로 써도 돼요)","answer_guide":{"answer":"예: ○○ 고인돌 유적지로 정해요. 고인돌은 옛사람들이 큰 돌로 만든 무덤이라는 특징을 조사해요. 작은 돌과 막대로 무거운 돌을 함께 옮겨 보는 체험 프로그램을 만들어요.","scoring_points":["장소를 하나 정했는가","그 장소의 역사적 특징을 조사한다고 썼는가","특징이 담긴 프로그램이나 캐릭터를 썼는가"]},"explanation":["장소를 정해요.","특징을 조사해요.","만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#9','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',4,'mc','auto','주제②를 장소 → 조사 → 소개 → 보존으로 정리할 때 소개에 들어갈 내용은 무엇인가요?',ARRAY['SO4-1-u2-X24']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C11","difficulty":4,"kind":"mc","stem":"주제②를 장소 → 조사 → 소개 → 보존으로 정리할 때 소개에 들어갈 내용은 무엇인가요?","options":[{"t":"동영상·안내 책자·신문으로 우리 반 역사 박물관 열기","correct":true},{"t":"박물관·기념관·유적지 찾기","mis":"SO4-1-u2-X24"},{"t":"계획 → 조사 → 보고서","mis":"SO4-1-u2-X24"},{"t":"관리·지킴이 활동·널리 알리기","mis":"SO4-1-u2-X24"}],"explanation":["흐름을 떠올려요.","소개는 알리는 일이에요.","자료로 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_L11_challenge#10','soc',4,1,'u2','L11','g4_1_soc_u2_L11_challenge','lesson_challenge','SO4-1-u2-C11',4,'essay','teacher','암호 풀기에서 옳지 않은 문장 두 개를 찾아 옳게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C11","difficulty":4,"kind":"essay","stem":"암호 풀기에서 옳지 않은 문장 두 개를 찾아 옳게 고쳐 쓰세요.","answer_guide":{"answer":"예: ②는 옳지 않아요. 역사 조사는 계획을 먼저 세우고 조사한 뒤 보고서를 써요. ④도 옳지 않아요. 다른 곳에서 모은 사진은 반드시 출처를 표시해야 해요.","scoring_points":["②를 찾았는가","④를 찾았는가","두 문장을 옳게 고쳐 썼는가"]},"explanation":["문장을 따져요.","옳지 않은 것을 찾아요.","고쳐 써요."],"asset":{"type":"passage","lines":["① 기념관은 인물이나 사건을 오래 기억하려고 세운 곳이다.","② 역사 조사는 보고서를 먼저 쓰고 계획을 세운다.","③ 면담 조사는 알 만한 분께 여쭤보는 방법이다.","④ 다른 곳에서 모은 사진은 출처 없이 써도 된다.","⑤ 어린이도 지킴이 활동으로 역사 보존에 힘을 보탤 수 있다."],"title":"암호 풀기 — 옳은 문장 번호를 작은 수부터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#1','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C1',1,'mc','auto','조상 대대로 전해 내려와 보존할 가치가 있는 것은 무엇인가요?',ARRAY['SO4-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"mc","stem":"조상 대대로 전해 내려와 보존할 가치가 있는 것은 무엇인가요?","options":[{"t":"국가유산","correct":true},{"t":"새 장난감","mis":"SO4-1-u2-X01"},{"t":"기념품","mis":"SO4-1-u2-X01"},{"t":"광고지","mis":"SO4-1-u2-X01"}],"explanation":["조상에게서 왔어요.","보존할 가치가 있어요.","국가유산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#2','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C2',1,'mc','auto','국가유산이 지닌 소중함과 뜻을 한 낱말로 무엇이라고 하나요?',ARRAY['SO4-1-u2-X05']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"mc","stem":"국가유산이 지닌 소중함과 뜻을 한 낱말로 무엇이라고 하나요?","options":[{"t":"가치","correct":true},{"t":"가격","mis":"SO4-1-u2-X05"},{"t":"무게","mis":"SO4-1-u2-X05"},{"t":"나이","mis":"SO4-1-u2-X05"}],"explanation":["값이 아니에요.","소중함과 뜻이에요.","가치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#3','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C3',1,'mc','auto','궁금한 국가유산이 있는 곳에 직접 가서 살펴보는 조사는 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"mc","stem":"궁금한 국가유산이 있는 곳에 직접 가서 살펴보는 조사는 무엇인가요?","options":[{"t":"답사","correct":true},{"t":"검색","mis":"SO4-1-u2-X09"},{"t":"독서","mis":"SO4-1-u2-X09"},{"t":"면담","mis":"SO4-1-u2-X09"}],"explanation":["직접 가요.","현장을 봐요.","답사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#4','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C4',1,'mc','auto','국가유산의 특징은 무엇에 따라 정리하나요?',ARRAY['SO4-1-u2-X13','SO4-1-u2-X14','SO4-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"mc","stem":"국가유산의 특징은 무엇에 따라 정리하나요?","options":[{"t":"있는 그대로의 사실","correct":true},{"t":"내 기분","mis":"SO4-1-u2-X13"},{"t":"친구의 생각","mis":"SO4-1-u2-X14"},{"t":"물건의 가격","mis":"SO4-1-u2-X05"}],"explanation":["특징이에요.","사실이에요.","있는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#5','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C5',1,'mc','auto','손을 맞잡고 원을 그리며 노래하는 강강술래를 노래와 춤으로 나타내는 표현 방법은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"mc","stem":"손을 맞잡고 원을 그리며 노래하는 강강술래를 노래와 춤으로 나타내는 표현 방법은 무엇인가요?","options":[{"t":"공연하기","correct":true},{"t":"가상 일기 쓰기","mis":"SO4-1-u2-X18"},{"t":"역할놀이 하기","mis":"SO4-1-u2-X18"},{"t":"사진 찍기","mis":"SO4-1-u2-X18"}],"explanation":["노래와 춤이에요.","보여 줘요.","공연하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
