INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#7','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C8',1,'mc','auto','역사 조사의 차례로 바른 것은 무엇인가요?',ARRAY['SO4-1-u2-X24']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"mc","stem":"역사 조사의 차례로 바른 것은 무엇인가요?","options":[{"t":"계획 세우기 → 조사하기 → 보고서 쓰기","correct":true},{"t":"보고서 쓰기 → 조사하기 → 계획 세우기","mis":"SO4-1-u2-X24"},{"t":"조사하기 → 계획 세우기 → 보고서 쓰기","mis":"SO4-1-u2-X24"},{"t":"보고서만 쓰기","mis":"SO4-1-u2-X24"}],"explanation":["계획이 먼저예요.","그다음 조사예요.","마지막이 보고서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#8','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C10',1,'mc','auto','잘 보살피고 지켜서 계속 남아 있게 하는 것은 무엇인가요?',ARRAY['SO4-1-u2-X32','SO4-1-u2-X30','SO4-1-u2-X09']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"mc","stem":"잘 보살피고 지켜서 계속 남아 있게 하는 것은 무엇인가요?","options":[{"t":"보존","correct":true},{"t":"훼손","mis":"SO4-1-u2-X32"},{"t":"전시","mis":"SO4-1-u2-X30"},{"t":"검색","mis":"SO4-1-u2-X09"}],"explanation":["지켜요.","계속 남게 해요.","보존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#9','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C1',2,'mc','auto','일지 ①의 카드를 두 칸으로 바르게 나눈 것은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X02']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"mc","stem":"일지 ①의 카드를 두 칸으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"돌다리·옹기 / 농악·줄다리기·장 담그기","correct":true},{"t":"돌다리·농악 / 옹기·줄다리기·장 담그기","mis":"SO4-1-u2-X03"},{"t":"옹기·장 담그기 / 돌다리·농악·줄다리기","mis":"SO4-1-u2-X03"},{"t":"다섯 가지 모두 문화유산","mis":"SO4-1-u2-X02"}],"explanation":["형태가 있나요?","돌다리·옹기는 있어요.","나머지는 없어요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#10','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C2',2,'mc','auto','일지 ②의 이야기 줄에서 찾을 수 있는 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"mc","stem":"일지 ②의 이야기 줄에서 찾을 수 있는 가치는 무엇인가요?","options":[{"t":"역사적 가치","correct":true},{"t":"심미적 가치","mis":"SO4-1-u2-X06"},{"t":"생태환경적 가치","mis":"SO4-1-u2-X06"},{"t":"가격의 가치","mis":"SO4-1-u2-X05"}],"explanation":["오랫동안이에요.","세대를 이었어요.","역사적 가치예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#11','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C3',2,'mc','auto','일지 ③ 대화에서 지호가 사진을 찍어도 되는지 미리 알아보자고 한 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X12','SO4-1-u2-X11']::text[],false,'{"seq":11,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"mc","stem":"일지 ③ 대화에서 지호가 사진을 찍어도 되는지 미리 알아보자고 한 까닭은 무엇인가요?","options":[{"t":"촬영할 수 없는 곳도 있기 때문이에요","correct":true},{"t":"사진은 어디서나 마음대로 찍어도 되기 때문이에요","mis":"SO4-1-u2-X12"},{"t":"사진을 많이 찍을수록 점수가 높기 때문이에요","mis":"SO4-1-u2-X12"},{"t":"조사에는 사진만 있으면 되기 때문이에요","mis":"SO4-1-u2-X11"}],"explanation":["답사 준비예요.","촬영이 안 되는 곳도 있어요.","미리 알아봐요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#12','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C5',2,'mc','auto','옛 바람골 서당의 아이가 되어 하루를 일기로 쓰려고 해요. 가장 알맞게 쓴 문장은 무엇인가요?',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"mc","stem":"옛 바람골 서당의 아이가 되어 하루를 일기로 쓰려고 해요. 가장 알맞게 쓴 문장은 무엇인가요?","options":[{"t":"훈장님 앞에서 소리 내어 글을 읽었다.","correct":true},{"t":"태블릿으로 숙제를 보냈다.","mis":"SO4-1-u2-X17"},{"t":"훈장님과 비행기를 타고 소풍을 갔다.","mis":"SO4-1-u2-X17"},{"t":"오늘 배운 셈을 계산기로 풀었다.","mis":"SO4-1-u2-X17"}],"explanation":["옛 서당이에요.","사실을 토대로 해요.","글을 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#13','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C7',2,'mc','auto','일지 ⑤의 ㉯가 바람골에 세워진 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X23','SO4-1-u2-X22']::text[],false,'{"seq":13,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"mc","stem":"일지 ⑤의 ㉯가 바람골에 세워진 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"의병들이 이 고장에서 나라를 지켰기 때문이에요","correct":true},{"t":"건물이 커서예요","mis":"SO4-1-u2-X23"},{"t":"교통이 편해서예요","mis":"SO4-1-u2-X23"},{"t":"놀이 기구를 두려고요","mis":"SO4-1-u2-X22"}],"explanation":["의병 기념관이에요.","이 고장에서 싸웠어요.","인연이 깊어요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#14','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C8',2,'mc','auto','일지 ⑥의 주의할 점에 믿을 만한 정보인지 확인하기를 넣은 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X26','SO4-1-u2-X12']::text[],false,'{"seq":14,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"mc","stem":"일지 ⑥의 주의할 점에 믿을 만한 정보인지 확인하기를 넣은 까닭은 무엇인가요?","options":[{"t":"인터넷이나 소문에는 잘못된 정보도 있기 때문이에요","correct":true},{"t":"모든 정보는 다 맞기 때문이에요","mis":"SO4-1-u2-X26"},{"t":"확인하면 조사가 끝나지 않기 때문이에요","mis":"SO4-1-u2-X26"},{"t":"보호자가 시켰기 때문이에요","mis":"SO4-1-u2-X12"}],"explanation":["정보가 다 맞지는 않아요.","확인이 필요해요.","잘못된 정보도 있어요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#15','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C9',2,'mc','auto','일지 ⑦에서 움직임과 소리로 생생하게 소개하는 모둠은 어디인가요?',ARRAY['SO4-1-u2-X28']::text[],false,'{"seq":15,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"mc","stem":"일지 ⑦에서 움직임과 소리로 생생하게 소개하는 모둠은 어디인가요?","options":[{"t":"2모둠","correct":true},{"t":"1모둠","mis":"SO4-1-u2-X28"},{"t":"3모둠","mis":"SO4-1-u2-X28"},{"t":"4모둠","mis":"SO4-1-u2-X28"}],"explanation":["움직임과 소리예요.","동영상이에요.","2모둠이에요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#16','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C10',2,'mc','auto','일지 ⑧에서 농악에 생긴 문제는 무엇인가요?',ARRAY['SO4-1-u2-X32','SO4-1-u2-X05']::text[],false,'{"seq":16,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"mc","stem":"일지 ⑧에서 농악에 생긴 문제는 무엇인가요?","options":[{"t":"이을 젊은 사람이 줄고 있어요","correct":true},{"t":"공연하는 사람이 너무 많아요","mis":"SO4-1-u2-X32"},{"t":"농악이 새로 생겼어요","mis":"SO4-1-u2-X32"},{"t":"농악 값이 올랐어요","mis":"SO4-1-u2-X05"}],"explanation":["농악이에요.","젊은 사람이 줄어요.","이을 사람이 부족해요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#17','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C2',3,'error','auto','일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X07']::text[],false,'{"seq":17,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"error","stem":"일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「대청마루는 곡선이 아름다워서 심미적 가치야.」","correct":true,"mis_target":"SO4-1-u2-X06"},{"t":"친구 가 — 「온돌방은 추위를 이기는 과학적 가치야.」","mis":"SO4-1-u2-X06"},{"t":"친구 다 — 「오랫동안 아이들이 배운 곳이니 역사적 가치도 있어.」","mis":"SO4-1-u2-X07"}],"explanation":["대청마루는 바람이 통해요.","과학적 가치예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#18','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C4',3,'error','auto','일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":18,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"error","stem":"일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉢은 눈으로 확인한 사실이니 특징이야.」","correct":true,"mis_target":"SO4-1-u2-X13"},{"t":"친구 나 — 「㉠은 높이를 적은 특징이야.」","mis":"SO4-1-u2-X13"},{"t":"친구 다 — 「㉣은 무늬에서 헤아린 가치야.」","mis":"SO4-1-u2-X13"}],"explanation":["㉢은 슬기가 담겼대요.","헤아린 가치예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#19','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C5',3,'error','auto','바람골 농악을 표현하려는 모둠의 계획을 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X17','SO4-1-u2-X18']::text[],false,'{"seq":19,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"error","stem":"바람골 농악을 표현하려는 모둠의 계획을 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「조사는 필요 없고 요즘 춤을 마음대로 섞으면 돼.」","correct":true,"mis_target":"SO4-1-u2-X17"},{"t":"친구 가 — 「꽹과리·장구 가락을 조사해서 공연하자.」","mis":"SO4-1-u2-X18"},{"t":"친구 나 — 「옛 농악꾼이 되어 가상 일기를 써도 좋아.」","mis":"SO4-1-u2-X18"}],"explanation":["조사가 먼저예요.","사실을 토대로 해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#20','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C7',3,'error','auto','일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":20,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"error","stem":"일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉮는 의병을 기억하려고 세운 기념관이야.」","correct":true,"mis_target":"SO4-1-u2-X21"},{"t":"친구 가 — 「㉰는 움집 자리가 남은 유적지야.」","mis":"SO4-1-u2-X21"},{"t":"친구 다 — 「세 곳 모두 바람골의 역사를 알 수 있어.」","mis":"SO4-1-u2-X22"}],"explanation":["㉮는 박물관이에요.","기념관은 ㉯예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#21','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C9',3,'error','auto','일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X28','SO4-1-u2-X27']::text[],false,'{"seq":21,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"error","stem":"일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「2모둠 동영상은 편집부터 하고 나중에 촬영했을 거야.」","correct":true,"mis_target":"SO4-1-u2-X28"},{"t":"친구 나 — 「3모둠 책자는 자세하게 소개할 수 있어.」","mis":"SO4-1-u2-X28"},{"t":"친구 다 — 「4모둠은 출처를 밝혀서 잘했어.」","mis":"SO4-1-u2-X27"}],"explanation":["촬영이 먼저예요.","그다음 편집이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#22','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C10',3,'error','auto','일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u2-X31','SO4-1-u2-X32']::text[],false,'{"seq":22,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"error","stem":"일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「돌다리는 군에서 고치니까 우리는 할 일이 없어.」","correct":true,"mis_target":"SO4-1-u2-X31"},{"t":"친구 가 — 「농악은 이을 사람이 줄어 사라질 위기야.」","mis":"SO4-1-u2-X32"},{"t":"친구 나 — 「돌다리가 상한 건 훼손이야.」","mis":"SO4-1-u2-X32"}],"explanation":["우리 반도 맡았어요.","청소와 알리기예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#23','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C1',4,'essay','teacher','일지 ①의 카드를 문화유산과 무형유산으로 나누고, 나눈 기준을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u2-C1","difficulty":4,"kind":"essay","stem":"일지 ①의 카드를 문화유산과 무형유산으로 나누고, 나눈 기준을 쓰세요.","answer_guide":{"answer":"예: 문화유산은 바람골 돌다리와 바람골 옹기이고, 무형유산은 바람골 농악·마을 줄다리기·장 담그기예요. 눈으로 보고 만질 수 있는 형태가 있으면 문화유산, 형태 없이 소리·춤·놀이·솜씨로 전해 오면 무형유산으로 나누었어요.","scoring_points":["문화유산 두 가지를 바르게 골랐는가","무형유산 세 가지를 바르게 골랐는가","형태가 있는지 없는지를 기준으로 썼는가"]},"explanation":["카드를 읽어요.","형태를 따져요.","기준을 써요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#24','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C8',4,'essay','teacher','일지 ⑥을 보고 조사 계획서와 조사 보고서에 들어가는 내용을 각각 두 가지씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u2-C8","difficulty":4,"kind":"essay","stem":"일지 ⑥을 보고 조사 계획서와 조사 보고서에 들어가는 내용을 각각 두 가지씩 쓰세요.","answer_guide":{"answer":"예: 조사 계획서에는 조사 주제와 조사 방법, 주의할 점이 들어가요. 조사 보고서에는 조사해서 새롭게 알게 된 점과 느낀 점이 들어가요.","scoring_points":["계획서 내용 두 가지를 썼는가","보고서 내용 두 가지를 썼는가","둘을 바꾸어 쓰지 않았는가"]},"explanation":["계획서를 봐요.","보고서를 봐요.","나누어 써요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_a#25','soc',4,1,'u2','','g4_1_soc_u2_review_a','unit_review','SO4-1-u2-C10',4,'essay','teacher','일지 ⑧의 두 문제를 쓰고, 군이 하는 노력과 우리 반이 하는 노력이 각각 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u2-C10","difficulty":4,"kind":"essay","stem":"일지 ⑧의 두 문제를 쓰고, 군이 하는 노력과 우리 반이 하는 노력이 각각 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 농악을 이을 젊은 사람이 줄고, 돌다리가 상했어요. 군에서 돌다리를 고치면 다리가 더 훼손되지 않고, 공연 행사를 열면 농악에 관심을 가진 사람이 늘어요. 우리 반이 둘레를 청소하고 농악을 알리면 더 많은 사람이 함께 지키게 돼요.","scoring_points":["두 문제를 썼는가","군의 노력이 도움이 되는 까닭을 썼는가","우리 반의 노력이 도움이 되는 까닭을 썼는가"]},"explanation":["문제를 찾아요.","군의 노력을 봐요.","우리 반의 노력을 봐요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#1','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C1',1,'sa','auto','일지 ①에서 냇물 위에 큰 돌을 놓아 만든 국가유산은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"sa","stem":"일지 ①에서 냇물 위에 큰 돌을 놓아 만든 국가유산은 무엇인가요? 세 글자로 쓰세요.","answer":["돌다리"],"explanation":["냇물 위예요.","큰 돌이에요.","돌다리예요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"},"mis":"SO4-1-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#2','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C2',1,'sa','auto','일지 ②의 대청마루처럼 슬기로운 원리가 담긴 가치를 ○○○ 가치라고 해요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"sa","stem":"일지 ②의 대청마루처럼 슬기로운 원리가 담긴 가치를 ○○○ 가치라고 해요. 세 글자로 쓰세요.","answer":["과학적"],"explanation":["바람이 통해요.","슬기로운 원리예요.","과학적 가치예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"},"mis":"SO4-1-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#3','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C3',1,'sa','auto','일지 ③ 대화에서 예린이가 여쭤보자고 한 사람은 누구인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"sa","stem":"일지 ③ 대화에서 예린이가 여쭤보자고 한 사람은 누구인가요? 세 글자로 쓰세요.","answer":["해설사"],"explanation":["서당에 가요.","여쭤봐요.","해설사예요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]},"mis":"SO4-1-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#4','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C4',1,'sa','auto','일지 ④의 ㉠과 ㉡처럼 있는 그대로의 사실을 적은 것은 특징과 가치 가운데 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"sa","stem":"일지 ④의 ㉠과 ㉡처럼 있는 그대로의 사실을 적은 것은 특징과 가치 가운데 무엇인가요? 두 글자로 쓰세요.","answer":["특징"],"explanation":["높이와 무늬예요.","눈으로 확인해요.","특징이에요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"},"mis":"SO4-1-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#5','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C5',1,'sa','auto','대본을 만들어 옛 장면을 연기하는 표현 방법은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"sa","stem":"대본을 만들어 옛 장면을 연기하는 표현 방법은 무엇인가요? 네 글자로 쓰세요.","answer":["역할놀이"],"explanation":["대본이 있어요.","연기해요.","역할놀이예요."],"mis":"SO4-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#6','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C7',1,'sa','auto','일지 ⑤의 ㉰처럼 옛사람들의 흔적이 남아 있는 곳을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"sa","stem":"일지 ⑤의 ㉰처럼 옛사람들의 흔적이 남아 있는 곳을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["유적지"],"explanation":["움집 자리예요.","흔적이 남았어요.","유적지예요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"},"mis":"SO4-1-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#7','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C8',1,'sa','auto','일지 ⑥에서 움집에 살았다는 알게 된 점은 계획서와 보고서 가운데 어디에 쓴 것인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"sa","stem":"일지 ⑥에서 움집에 살았다는 알게 된 점은 계획서와 보고서 가운데 어디에 쓴 것인가요? 세 글자로 쓰세요.","answer":["보고서"],"explanation":["알게 된 점이에요.","조사 뒤에 써요.","보고서예요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"},"mis":"SO4-1-u2-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#8','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C10',1,'sa','auto','일지 ⑧에서 돌다리가 상한 것처럼 국가유산이 깨지거나 상하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"sa","stem":"일지 ⑧에서 돌다리가 상한 것처럼 국가유산이 깨지거나 상하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["훼손"],"explanation":["돌다리가 상했어요.","깨지고 상해요.","훼손이에요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"},"mis":"SO4-1-u2-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#9','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C1',2,'ox','auto','일지 ①의 장 담그기는 된장과 간장을 볼 수 있으니 문화유산이에요.',ARRAY['SO4-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"ox","stem":"일지 ①의 장 담그기는 된장과 간장을 볼 수 있으니 문화유산이에요.","answer":"X","reason_options":[{"t":"장을 담그는 솜씨가 사람에게서 사람으로 전해 오는 무형유산이기 때문에","correct":true},{"t":"먹을거리를 만드는 일은 모두 형태가 있기 때문에","mis":"SO4-1-u2-X03"}],"mis":"SO4-1-u2-X03","explanation":["장 담그기는 솜씨예요.","솜씨는 형태가 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#10','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C2',2,'ox','auto','일지 ②의 옛 서당에는 한 가지 가치만 담겨 있어요.',ARRAY['SO4-1-u2-X07']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"ox","stem":"일지 ②의 옛 서당에는 한 가지 가치만 담겨 있어요.","answer":"X","reason_options":[{"t":"과학적·심미적·생태환경적·역사적 가치가 함께 담겨 있기 때문에","correct":true},{"t":"국가유산에는 가치가 하나씩만 담기기 때문에","mis":"SO4-1-u2-X07"}],"mis":"SO4-1-u2-X07","explanation":["다섯 줄을 봐요.","가치가 여럿이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#11','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C3',2,'ox','auto','일지 ③ 대화의 두 친구는 여러 조사 방법을 함께 쓰려고 해요.',ARRAY['SO4-1-u2-X11']::text[],false,'{"seq":11,"concept":"SO4-1-u2-C3","difficulty":2,"kind":"ox","stem":"일지 ③ 대화의 두 친구는 여러 조사 방법을 함께 쓰려고 해요.","answer":"O","reason_options":[{"t":"책·누리집·해설사·답사를 함께 써서 서로 보태려 하기 때문에","correct":true},{"t":"두 친구 모두 한 가지 방법만 쓰기 때문에","mis":"SO4-1-u2-X11"}],"mis":"SO4-1-u2-X11","explanation":["방법을 세어요.","여럿이에요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#12','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C6',2,'ox','auto','미래의 국가유산은 지금 가장 새로 나온 물건 가운데서 골라야 해요.',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":12,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"ox","stem":"미래의 국가유산은 지금 가장 새로 나온 물건 가운데서 골라야 해요.","answer":"X","reason_options":[{"t":"새것인지보다 미래에도 소중한 가치가 있을지를 생각해야 하기 때문에","correct":true},{"t":"새것일수록 오래 남기 때문에","mis":"SO4-1-u2-X20"}],"mis":"SO4-1-u2-X20","explanation":["새것이 기준이 아니에요.","가치가 기준이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#13','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C7',2,'ox','auto','일지 ⑤의 ㉰에 가면 옛사람들이 살던 흔적을 그 자리에서 볼 수 있어요.',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":13,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"ox","stem":"일지 ⑤의 ㉰에 가면 옛사람들이 살던 흔적을 그 자리에서 볼 수 있어요.","answer":"O","reason_options":[{"t":"움집 자리가 남아 있는 유적지이기 때문에","correct":true},{"t":"유적지는 인물을 기억하려고 새로 지은 곳이기 때문에","mis":"SO4-1-u2-X21"}],"mis":"SO4-1-u2-X21","explanation":["㉰는 유적지예요.","움집 자리가 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#14','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C8',2,'ox','auto','일지 ⑥의 느낀 점은 조사 계획서에 미리 써 두는 내용이에요.',ARRAY['SO4-1-u2-X25']::text[],false,'{"seq":14,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"ox","stem":"일지 ⑥의 느낀 점은 조사 계획서에 미리 써 두는 내용이에요.","answer":"X","reason_options":[{"t":"느낀 점은 조사를 마친 뒤 보고서에 쓰기 때문에","correct":true},{"t":"계획서에 느낀 점을 먼저 정해 두어야 하기 때문에","mis":"SO4-1-u2-X25"}],"mis":"SO4-1-u2-X25","explanation":["느낀 점이에요.","조사 뒤예요.","그래서 X예요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#15','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C9',2,'ox','auto','일지 ⑦의 4모둠은 누리집에서 모은 사진에 출처를 표시해 바르게 전시했어요.',ARRAY['SO4-1-u2-X27']::text[],false,'{"seq":15,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"ox","stem":"일지 ⑦의 4모둠은 누리집에서 모은 사진에 출처를 표시해 바르게 전시했어요.","answer":"O","reason_options":[{"t":"다른 곳에서 모은 사진은 출처를 밝혀야 하기 때문에","correct":true},{"t":"모은 사진은 출처를 밝히지 않아도 되기 때문에","mis":"SO4-1-u2-X27"}],"mis":"SO4-1-u2-X27","explanation":["누리집 사진이에요.","출처를 표시했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#16','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C10',2,'ox','auto','일지 ⑧에서 군이 연 농악 공연 행사는 무형유산을 이어 가는 데 도움이 돼요.',ARRAY['SO4-1-u2-X32']::text[],false,'{"seq":16,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"ox","stem":"일지 ⑧에서 군이 연 농악 공연 행사는 무형유산을 이어 가는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"많은 사람이 보고 관심을 가져 배우려는 사람이 늘 수 있기 때문에","correct":true},{"t":"행사를 열면 농악이 더 빨리 사라지기 때문에","mis":"SO4-1-u2-X32"}],"mis":"SO4-1-u2-X32","explanation":["행사를 열어요.","관심이 생겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#17','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C2',3,'mc','auto','일지 ②의 서당을 소나무와 황토로 지은 것에서 생태환경적 가치를 찾은 까닭은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X06']::text[],false,'{"seq":17,"concept":"SO4-1-u2-C2","difficulty":3,"kind":"mc","stem":"일지 ②의 서당을 소나무와 황토로 지은 것에서 생태환경적 가치를 찾은 까닭은 무엇인가요?","options":[{"t":"자연에서 얻은 재료로 자연을 해치지 않게 지었기 때문이에요","correct":true},{"t":"재료가 비쌌기 때문이에요","mis":"SO4-1-u2-X05"},{"t":"곡선이 아름답기 때문이에요","mis":"SO4-1-u2-X06"},{"t":"오래 전해 왔기 때문이에요","mis":"SO4-1-u2-X06"}],"explanation":["뒷산 재료예요.","자연과 어울려요.","생태환경적 가치예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#18','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C4',3,'mc','auto','일지 ④의 특징 ㉡에서 헤아린 가치는 무엇인가요?',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":18,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"mc","stem":"일지 ④의 특징 ㉡에서 헤아린 가치는 무엇인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO4-1-u2-X13"},{"t":"㉢","mis":"SO4-1-u2-X13"},{"t":"알 수 없어요","mis":"SO4-1-u2-X13"}],"explanation":["㉡은 물결무늬예요.","무늬에서 아름다움을 느껴요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#19','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C6',3,'mc','auto','미래의 국가유산으로 바람골 아이들이 해마다 함께 그려 온 마을 벽화를 골랐어요. 고른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X20']::text[],false,'{"seq":19,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"mc","stem":"미래의 국가유산으로 바람골 아이들이 해마다 함께 그려 온 마을 벽화를 골랐어요. 고른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"마을 사람들이 함께 이어 온 것이라 미래에도 소중한 가치가 있을 것 같아서","correct":true},{"t":"가장 새로 그린 그림이라서","mis":"SO4-1-u2-X20"},{"t":"비싼 물감을 써서","mis":"SO4-1-u2-X20"},{"t":"내가 좋아하는 색이라서","mis":"SO4-1-u2-X20"}],"explanation":["해마다 함께 그렸어요.","이어 온 것이에요.","가치가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#20','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C8',3,'mc','auto','일지 ⑥의 조사에서 문헌 조사·답사·면담 조사를 함께 쓴 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X11','SO4-1-u2-X24']::text[],false,'{"seq":20,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"mc","stem":"일지 ⑥의 조사에서 문헌 조사·답사·면담 조사를 함께 쓴 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한 가지만 쓰면 놓치는 것을 서로 채울 수 있어서","correct":true},{"t":"방법이 많을수록 보고서가 짧아져서","mis":"SO4-1-u2-X11"},{"t":"한 가지로는 아무것도 알 수 없어서","mis":"SO4-1-u2-X11"},{"t":"계획서를 쓰지 않아도 돼서","mis":"SO4-1-u2-X24"}],"explanation":["방법이 셋이에요.","서로 채워요.","더 정확해요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#21','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C9',3,'mc','auto','우리 반 역사 박물관에서 설명하는 친구가 지킬 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X16']::text[],false,'{"seq":21,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"우리 반 역사 박물관에서 설명하는 친구가 지킬 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람이 이해하기 쉽게 또렷하게 말해요","correct":true},{"t":"빨리 말하고 끝내요","mis":"SO4-1-u2-X16"},{"t":"질문은 받지 않아요","mis":"SO4-1-u2-X16"},{"t":"다른 모둠 자료를 깎아내려요","mis":"SO4-1-u2-X16"}],"explanation":["듣는 사람이 있어요.","쉽게 말해요.","또렷하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#22','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C11',3,'mc','auto','바람골 돌다리로 체험 프로그램을 만들 때 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X33','SO4-1-u2-X30']::text[],false,'{"seq":22,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"mc","stem":"바람골 돌다리로 체험 프로그램을 만들 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"돌다리를 놓은 방법을 조사해 작은 돌로 다리 놓기 체험을 해요","correct":true},{"t":"돌다리와 관계없는 보물찾기를 해요","mis":"SO4-1-u2-X33"},{"t":"조사 없이 돌다리 위에서 뛰는 놀이를 해요","mis":"SO4-1-u2-X33"},{"t":"돌다리 돌을 하나씩 가져가요","mis":"SO4-1-u2-X30"}],"explanation":["돌다리의 특징이에요.","조사해요.","체험으로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#23','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C2',4,'essay','teacher','일지 ②의 옛 서당에 담긴 가치 세 가지를 골라 각각 근거가 되는 서당의 모습과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u2-C2","difficulty":4,"kind":"essay","stem":"일지 ②의 옛 서당에 담긴 가치 세 가지를 골라 각각 근거가 되는 서당의 모습과 함께 쓰세요.","answer_guide":{"answer":"예: 온돌방은 아궁이 불로 방을 데워 과학적 가치가 있어요. 처마는 지붕 끝 곡선이 아름다워 심미적 가치가 있어요. 오랫동안 마을 아이들이 글을 배운 곳이라 역사적 가치가 있어요.","scoring_points":["가치 세 가지를 골랐는가","각 가치의 근거를 서당 모습에서 찾았는가","가치와 모습을 바르게 짝지었는가"]},"explanation":["가치를 골라요.","모습을 찾아요.","짝지어 써요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#24','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C9',4,'essay','teacher','일지 ⑦의 자료 가운데 하나를 골라 만드는 방법과 그 자료의 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u2-C9","difficulty":4,"kind":"essay","stem":"일지 ⑦의 자료 가운데 하나를 골라 만드는 방법과 그 자료의 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 2모둠 동영상은 옛 집터를 사진과 동영상으로 찍고, 편집 도구를 골라 역사적 특징이 잘 드러나게 편집한 뒤 소개해요. 움직임과 소리로 생생하게 알릴 수 있어서 좋아요.","scoring_points":["자료 하나를 골랐는가","만드는 방법을 차례대로 썼는가","그 자료의 좋은 점을 썼는가"]},"explanation":["자료를 골라요.","만드는 방법을 써요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_b#25','soc',4,1,'u2','','g4_1_soc_u2_review_b','unit_review','SO4-1-u2-C11',4,'essay','teacher','바람골의 역사 장소 하나를 골라 역사가 담긴 캐릭터를 만들려고 해요. 만드는 차례와 캐릭터의 모습·이름을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u2-C11","difficulty":4,"kind":"essay","stem":"바람골의 역사 장소 하나를 골라 역사가 담긴 캐릭터를 만들려고 해요. 만드는 차례와 캐릭터의 모습·이름을 쓰세요.","answer_guide":{"answer":"예: ㉰ 옛 집터 유적지를 골라요. 먼저 움집에 살던 옛사람들의 특징을 조사해요. 그다음 움집 지붕 모자를 쓰고 돌도끼를 든 캐릭터를 그리고 이름을 움돌이로 지어요.","scoring_points":["장소를 하나 골랐는가","정하기 → 조사 → 그리기 차례를 썼는가","특징이 담긴 모습과 이름을 썼는가"]},"explanation":["장소를 골라요.","특징을 조사해요.","캐릭터를 써요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#1','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C1',1,'ox','auto','일지 ①의 바람골 농악은 형태가 없는 무형유산이에요.',ARRAY['SO4-1-u2-X03']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"ox","stem":"일지 ①의 바람골 농악은 형태가 없는 무형유산이에요.","answer":"O","reason_options":[{"t":"춤과 가락으로 사람에게서 사람으로 전해 오기 때문에","correct":true},{"t":"손으로 만질 수 있는 물건이기 때문에","mis":"SO4-1-u2-X03"}],"mis":"SO4-1-u2-X03","explanation":["농악은 춤과 가락이에요.","형태가 없어요.","그래서 O예요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#2','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C2',1,'ox','auto','일지 ②의 처마에는 심미적 가치가 담겨 있어요.',ARRAY['SO4-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"ox","stem":"일지 ②의 처마에는 심미적 가치가 담겨 있어요.","answer":"O","reason_options":[{"t":"지붕 끝이 올라간 곡선이 아름답기 때문에","correct":true},{"t":"처마는 방을 따뜻하게 하는 시설이기 때문에","mis":"SO4-1-u2-X06"}],"mis":"SO4-1-u2-X06","explanation":["곡선이에요.","아름다워요.","그래서 O예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#3','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C3',1,'ox','auto','일지 ③ 대화에서 지호가 군청 누리집을 검색하는 것은 인터넷 조사예요.',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"ox","stem":"일지 ③ 대화에서 지호가 군청 누리집을 검색하는 것은 인터넷 조사예요.","answer":"O","reason_options":[{"t":"누리집을 검색해 자료를 찾는 방법이기 때문에","correct":true},{"t":"누리집을 보는 것은 답사이기 때문에","mis":"SO4-1-u2-X09"}],"mis":"SO4-1-u2-X09","explanation":["누리집이에요.","검색해요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#4','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C4',1,'ox','auto','일지 ④의 ㉣은 특징이에요.',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"ox","stem":"일지 ④의 ㉣은 특징이에요.","answer":"X","reason_options":[{"t":"물결무늬를 보고 아름다움을 헤아린 가치이기 때문에","correct":true},{"t":"느낀 것도 눈으로 확인한 사실이기 때문에","mis":"SO4-1-u2-X13"}],"mis":"SO4-1-u2-X13","explanation":["아름다움을 느꼈어요.","헤아린 것이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#5','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C5',1,'ox','auto','가상 일기를 쓸 때는 역사적 사실을 토대로 상상해서 써요.',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"ox","stem":"가상 일기를 쓸 때는 역사적 사실을 토대로 상상해서 써요.","answer":"O","reason_options":[{"t":"사실 위에 상상을 더해야 참모습을 바르게 전하기 때문에","correct":true},{"t":"가상 일기는 사실이 필요 없기 때문에","mis":"SO4-1-u2-X17"}],"mis":"SO4-1-u2-X17","explanation":["사실이 바탕이에요.","상상을 더해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#6','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C7',1,'ox','auto','일지 ⑤의 ㉮에서는 옛 농기구와 그릇을 볼 수 있어요.',ARRAY['SO4-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"ox","stem":"일지 ⑤의 ㉮에서는 옛 농기구와 그릇을 볼 수 있어요.","answer":"O","reason_options":[{"t":"박물관은 유물과 자료를 모아 전시하기 때문에","correct":true},{"t":"박물관은 인물만 기억하는 곳이기 때문에","mis":"SO4-1-u2-X21"}],"mis":"SO4-1-u2-X21","explanation":["㉮는 박물관이에요.","유물을 전시해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#7','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C8',1,'ox','auto','알 만한 분께 직접 여쭤보는 조사 방법은 면담 조사예요.',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"ox","stem":"알 만한 분께 직접 여쭤보는 조사 방법은 면담 조사예요.","answer":"O","reason_options":[{"t":"사람을 만나 묻고 답을 듣는 방법이기 때문에","correct":true},{"t":"면담 조사는 책을 찾아보는 방법이기 때문에","mis":"SO4-1-u2-X09"}],"mis":"SO4-1-u2-X09","explanation":["여쭤봐요.","사람을 만나요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#8','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C10',1,'ox','auto','일지 ⑧에서 우리 반이 맡은 돌다리 둘레 청소는 역사를 보존하는 일이에요.',ARRAY['SO4-1-u2-X31']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"ox","stem":"일지 ⑧에서 우리 반이 맡은 돌다리 둘레 청소는 역사를 보존하는 일이에요.","answer":"O","reason_options":[{"t":"국가유산 둘레를 돌보는 지킴이 활동이기 때문에","correct":true},{"t":"보존은 군에서만 할 수 있기 때문에","mis":"SO4-1-u2-X31"}],"mis":"SO4-1-u2-X31","explanation":["청소예요.","지킴이 활동이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#9','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C1',2,'mc','auto','일지 ①의 마을 줄다리기에서 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X04','SO4-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"mc","stem":"일지 ①의 마을 줄다리기에서 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"마을 사람들이 함께 어울려 놀던 생활 모습","correct":true},{"t":"줄의 값","mis":"SO4-1-u2-X05"},{"t":"다음 해의 날씨","mis":"SO4-1-u2-X04"},{"t":"줄다리기가 새로 생긴 놀이라는 것","mis":"SO4-1-u2-X01"}],"explanation":["해마다 해요.","함께 어울려요.","생활 모습이에요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#10','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C2',2,'match','auto','일지 ②의 서당 모습과 담긴 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"match","stem":"일지 ②의 서당 모습과 담긴 가치를 알맞게 이으세요.","pairs":[{"l":"온돌방","r":"과학적 가치"},{"l":"처마","r":"심미적 가치"},{"l":"소나무와 황토","r":"생태환경적 가치"}],"mis":"SO4-1-u2-X06","explanation":["따뜻해요.","아름다워요.","자연이에요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#11','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C4',2,'mc','auto','일지 ④에서 가치를 적은 것을 모두 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":11,"concept":"SO4-1-u2-C4","difficulty":2,"kind":"mc","stem":"일지 ④에서 가치를 적은 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉢, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SO4-1-u2-X13"},{"t":"㉠, ㉢","mis":"SO4-1-u2-X13"},{"t":"㉡, ㉣","mis":"SO4-1-u2-X13"}],"explanation":["헤아린 것을 찾아요.","슬기와 아름다움이에요.","㉢, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#12','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C6',2,'mc','auto','국가유산 안내판에 담을 내용으로 가장 알맞게 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X05','SO4-1-u2-X33','SO4-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO4-1-u2-C6","difficulty":2,"kind":"mc","stem":"국가유산 안내판에 담을 내용으로 가장 알맞게 고른 것은 무엇인가요?","options":[{"t":"이름·종류·특징·가치·지켜 줄 점","correct":true},{"t":"이름·가격·파는 곳","mis":"SO4-1-u2-X05"},{"t":"만든 사람의 기분·좋아하는 색","mis":"SO4-1-u2-X33"},{"t":"지어낸 재미있는 이야기","mis":"SO4-1-u2-X17"}],"explanation":["안내판이에요.","특징과 가치예요.","지켜 줄 점도 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#13','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C7',2,'match','auto','일지 ⑤의 장소와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO4-1-u2-C7","difficulty":2,"kind":"match","stem":"일지 ⑤의 장소와 하는 일을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"유물과 자료를 모아 전시"},{"l":"㉯","r":"인물·사건을 오래 기억"},{"l":"㉰","r":"옛 흔적이 남은 곳"}],"mis":"SO4-1-u2-X21","explanation":["박물관이에요.","기념관이에요.","유적지예요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#14','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C8',2,'mc','auto','일지 ⑥의 조사 방법 가운데 알 만한 분께 여쭤보는 것은 무엇인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":14,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"mc","stem":"일지 ⑥의 조사 방법 가운데 알 만한 분께 여쭤보는 것은 무엇인가요?","options":[{"t":"면담 조사","correct":true},{"t":"문헌 조사","mis":"SO4-1-u2-X09"},{"t":"답사","mis":"SO4-1-u2-X09"},{"t":"인터넷 조사","mis":"SO4-1-u2-X09"}],"explanation":["여쭤봐요.","사람을 만나요.","면담 조사예요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#15','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C9',2,'mc','auto','일지 ⑦의 1모둠 신문에 인터뷰 칸을 넣은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X28','SO4-1-u2-X27']::text[],false,'{"seq":15,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"mc","stem":"일지 ⑦의 1모둠 신문에 인터뷰 칸을 넣은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"읽는 사람이 더 재미있게 알 수 있어서","correct":true},{"t":"신문을 빨리 끝내려고","mis":"SO4-1-u2-X28"},{"t":"사진을 숨기려고","mis":"SO4-1-u2-X27"},{"t":"글을 쓰지 않으려고","mis":"SO4-1-u2-X28"}],"explanation":["신문이에요.","인터뷰가 있어요.","재미있게 알려요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#16','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C10',2,'mc','auto','일지 ⑧에서 군이 하는 노력과 우리 반이 하는 노력을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-1-u2-X31','SO4-1-u2-X30']::text[],false,'{"seq":16,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"mc","stem":"일지 ⑧에서 군이 하는 노력과 우리 반이 하는 노력을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"돌다리 고치기 — 농악 알리기","correct":true},{"t":"농악 알리기 — 돌다리 고치기","mis":"SO4-1-u2-X31"},{"t":"아무것도 하지 않기 — 청소하기","mis":"SO4-1-u2-X31"},{"t":"돌다리 허물기 — 낙서하기","mis":"SO4-1-u2-X30"}],"explanation":["군은 고쳐요.","우리 반은 알려요.","짝을 맞춰요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#17','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C1',3,'ox','auto','일지 ①의 다섯 카드는 모두 형태가 있어야 국가유산이 될 수 있어요.',ARRAY['SO4-1-u2-X02']::text[],false,'{"seq":17,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"ox","stem":"일지 ①의 다섯 카드는 모두 형태가 있어야 국가유산이 될 수 있어요.","answer":"X","reason_options":[{"t":"농악·줄다리기·장 담그기처럼 형태가 없는 무형유산도 국가유산이기 때문에","correct":true},{"t":"눈으로 볼 수 있는 것만 국가유산이기 때문에","mis":"SO4-1-u2-X02"}],"mis":"SO4-1-u2-X02","explanation":["형태가 없는 것도 있어요.","무형유산이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#18','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C3',3,'mc','auto','일지 ③ 대화의 조사 계획에 더하면 좋은 것은 무엇인가요?',ARRAY['SO4-1-u2-X12','SO4-1-u2-X11','SO4-1-u2-X10']::text[],false,'{"seq":18,"concept":"SO4-1-u2-C3","difficulty":3,"kind":"mc","stem":"일지 ③ 대화의 조사 계획에 더하면 좋은 것은 무엇인가요?","options":[{"t":"서당까지 안전하게 갈 길을 알아보고 보호자와 함께 가기","correct":true},{"t":"준비 없이 바로 출발하기","mis":"SO4-1-u2-X12"},{"t":"누리집 하나만 보고 끝내기","mis":"SO4-1-u2-X11"},{"t":"기억나는 이야기를 지어 적기","mis":"SO4-1-u2-X10"}],"explanation":["답사를 가요.","안전이 중요해요.","보호자와 함께 가요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#19','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C5',3,'ox','auto','옛 집터에 살던 사람이 되어 역할놀이를 할 때 움집을 짓고 불을 피우는 장면을 넣는 것은 알맞아요.',ARRAY['SO4-1-u2-X17']::text[],false,'{"seq":19,"concept":"SO4-1-u2-C5","difficulty":3,"kind":"ox","stem":"옛 집터에 살던 사람이 되어 역할놀이를 할 때 움집을 짓고 불을 피우는 장면을 넣는 것은 알맞아요.","answer":"O","reason_options":[{"t":"조사로 알게 된 사실을 바탕으로 장면을 만들었기 때문에","correct":true},{"t":"역할놀이에는 사실을 넣으면 안 되기 때문에","mis":"SO4-1-u2-X17"}],"mis":"SO4-1-u2-X17","explanation":["움집에 살았어요.","사실이 바탕이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#20','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C8',3,'ox','auto','일지 ⑥의 주의할 점에 보호자와 함께 가기를 쓴 것은 알맞아요.',ARRAY['SO4-1-u2-X12']::text[],false,'{"seq":20,"concept":"SO4-1-u2-C8","difficulty":3,"kind":"ox","stem":"일지 ⑥의 주의할 점에 보호자와 함께 가기를 쓴 것은 알맞아요.","answer":"O","reason_options":[{"t":"답사는 안전에 유의하며 보호자와 함께 가야 하기 때문에","correct":true},{"t":"답사는 혼자 가야 더 잘 보이기 때문에","mis":"SO4-1-u2-X12"}],"mis":"SO4-1-u2-X12","explanation":["답사예요.","안전이 중요해요.","그래서 O예요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#21','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C9',3,'ox','auto','큐레이터는 박물관에서 자료를 모으고 연구하며 전시를 기획해요.',ARRAY['SO4-1-u2-X29']::text[],false,'{"seq":21,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"ox","stem":"큐레이터는 박물관에서 자료를 모으고 연구하며 전시를 기획해요.","answer":"O","reason_options":[{"t":"자료를 조사·연구·보존하고 관람객에게 설명하기 때문에","correct":true},{"t":"큐레이터는 유적지를 허무는 일을 하기 때문에","mis":"SO4-1-u2-X29"}],"mis":"SO4-1-u2-X29","explanation":["박물관 사람이에요.","전시를 기획해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#22','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C11',3,'ox','auto','옛 집터 유적지 캐릭터에 움집 지붕 모자를 씌운 것은 장소의 특징을 담은 거예요.',ARRAY['SO4-1-u2-X33']::text[],false,'{"seq":22,"concept":"SO4-1-u2-C11","difficulty":3,"kind":"ox","stem":"옛 집터 유적지 캐릭터에 움집 지붕 모자를 씌운 것은 장소의 특징을 담은 거예요.","answer":"O","reason_options":[{"t":"유적지의 움집이라는 특징을 조사해 어울리게 그렸기 때문에","correct":true},{"t":"캐릭터는 장소와 관계없이 그려야 하기 때문에","mis":"SO4-1-u2-X33"}],"mis":"SO4-1-u2-X33","explanation":["움집이에요.","특징을 담았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#23','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C2',4,'mc','auto','일지 ②의 서당을 헐고 새 건물을 짓자는 말에 서당의 가치를 알리는 대답으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X01','SO4-1-u2-X05','SO4-1-u2-X07']::text[],false,'{"seq":23,"concept":"SO4-1-u2-C2","difficulty":4,"kind":"mc","stem":"일지 ②의 서당을 헐고 새 건물을 짓자는 말에 서당의 가치를 알리는 대답으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"오랫동안 아이들이 배운 역사와 계절을 이기는 슬기가 담겨 있어 지켜야 해요","correct":true},{"t":"낡았으니 새 건물로 바꾸면 돼요","mis":"SO4-1-u2-X01"},{"t":"값을 매겨 팔면 돼요","mis":"SO4-1-u2-X05"},{"t":"처마만 아름다우니 처마만 남기면 돼요","mis":"SO4-1-u2-X07"}],"explanation":["가치가 여럿이에요.","역사와 슬기예요.","지켜야 해요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#24','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C7',4,'mc','auto','바람골의 옛 생활 모습과 의병 이야기를 하루에 모두 알아보려고 해요. 가장 알맞은 일정은 무엇인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":24,"concept":"SO4-1-u2-C7","difficulty":4,"kind":"mc","stem":"바람골의 옛 생활 모습과 의병 이야기를 하루에 모두 알아보려고 해요. 가장 알맞은 일정은 무엇인가요?","options":[{"t":"㉰에서 움집 자리를 보고, ㉮에서 옛 농기구를 본 뒤, ㉯에서 의병 이야기를 알아봐요","correct":true},{"t":"㉯ 한 곳만 들러요","mis":"SO4-1-u2-X21"},{"t":"바람골 시장과 놀이공원을 들러요","mis":"SO4-1-u2-X22"},{"t":"㉮에서 의병을 기리는 행사만 찾아요","mis":"SO4-1-u2-X21"}],"explanation":["옛 생활은 ㉰와 ㉮예요.","의병은 ㉯예요.","세 곳을 들러요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_c#25','soc',4,1,'u2','','g4_1_soc_u2_review_c','unit_review','SO4-1-u2-C10',4,'mc','auto','조상 → 우리 → 다음 세대로 이어지는 흐름에서 우리가 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X30','SO4-1-u2-X31','SO4-1-u2-X32']::text[],false,'{"seq":25,"concept":"SO4-1-u2-C10","difficulty":4,"kind":"mc","stem":"조상 → 우리 → 다음 세대로 이어지는 흐름에서 우리가 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"물려받은 국가유산과 역사를 잘 알고 보존해 다음 세대에 물려줘요","correct":true},{"t":"물려받은 것을 새것으로 모두 바꿔요","mis":"SO4-1-u2-X30"},{"t":"어른들에게 다 맡겨요","mis":"SO4-1-u2-X31"},{"t":"지금 쓰고 나면 없애도 돼요","mis":"SO4-1-u2-X32"}],"explanation":["조상에게 받았어요.","우리가 지켜요.","다음 세대에 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#1','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C1',1,'mc','auto','일지 ①에서 형태가 있는 문화유산은 무엇인가요?',ARRAY['SO4-1-u2-X03']::text[],false,'{"seq":1,"concept":"SO4-1-u2-C1","difficulty":1,"kind":"mc","stem":"일지 ①에서 형태가 있는 문화유산은 무엇인가요?","options":[{"t":"바람골 옹기","correct":true},{"t":"바람골 농악","mis":"SO4-1-u2-X03"},{"t":"마을 줄다리기","mis":"SO4-1-u2-X03"},{"t":"장 담그기","mis":"SO4-1-u2-X03"}],"explanation":["형태가 있나요?","항아리예요.","옹기예요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#2','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C2',1,'mc','auto','일지 ②에서 마을 뒷산의 소나무와 황토로 지은 것에 담긴 가치는 무엇인가요?',ARRAY['SO4-1-u2-X06','SO4-1-u2-X05']::text[],false,'{"seq":2,"concept":"SO4-1-u2-C2","difficulty":1,"kind":"mc","stem":"일지 ②에서 마을 뒷산의 소나무와 황토로 지은 것에 담긴 가치는 무엇인가요?","options":[{"t":"생태환경적 가치","correct":true},{"t":"심미적 가치","mis":"SO4-1-u2-X06"},{"t":"과학적 가치","mis":"SO4-1-u2-X06"},{"t":"가격의 가치","mis":"SO4-1-u2-X05"}],"explanation":["자연 재료예요.","자연과 어울려요.","생태환경적 가치예요."],"asset":{"type":"passage","lines":["온돌방 — 아궁이에 불을 때면 방바닥이 따뜻해진다.","대청마루 — 앞뒤로 바람이 통해 여름에 시원하다.","처마 — 지붕 끝이 하늘로 살짝 올라간 곡선이 아름답다.","재료 — 마을 뒷산의 소나무와 황토로 지었다.","이야기 — 오랫동안 마을 아이들이 이곳에서 글을 배웠다."],"title":"일지 ② — 바람골 옛 서당"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#3','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C3',1,'mc','auto','일지 ③ 대화에서 예린이가 도서관 책을 찾아보려는 것은 어떤 조사 방법인가요?',ARRAY['SO4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SO4-1-u2-C3","difficulty":1,"kind":"mc","stem":"일지 ③ 대화에서 예린이가 도서관 책을 찾아보려는 것은 어떤 조사 방법인가요?","options":[{"t":"책으로 조사하기","correct":true},{"t":"답사","mis":"SO4-1-u2-X09"},{"t":"누리집 조사","mis":"SO4-1-u2-X09"},{"t":"해설사께 여쭤보기","mis":"SO4-1-u2-X09"}],"explanation":["도서관이에요.","책이에요.","책으로 조사하기예요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"옛 서당을 언제 지었는지 도서관 책에서 찾아볼게."},{"who":"지호","text":"나는 군청 누리집을 검색할게."},{"who":"예린","text":"서당에 직접 가서 해설사님께도 여쭤보자."},{"who":"지호","text":"가기 전에 사진을 찍어도 되는지 알아보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#4','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C4',1,'mc','auto','국가유산의 기본 정보에 들어가는 것은 무엇인가요?',ARRAY['SO4-1-u2-X15']::text[],false,'{"seq":4,"concept":"SO4-1-u2-C4","difficulty":1,"kind":"mc","stem":"국가유산의 기본 정보에 들어가는 것은 무엇인가요?","options":[{"t":"있는 곳","correct":true},{"t":"오늘 날씨","mis":"SO4-1-u2-X15"},{"t":"조사한 친구 이름","mis":"SO4-1-u2-X15"},{"t":"좋아하는 색","mis":"SO4-1-u2-X15"}],"explanation":["분류예요.","있는 곳이에요.","시대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#5','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C5',1,'mc','auto','조상들의 생활 모습을 표현하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO4-1-u2-C5","difficulty":1,"kind":"mc","stem":"조상들의 생활 모습을 표현하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"옛 서당 모습을 만화로 그리기","correct":true},{"t":"계산 문제 풀기","mis":"SO4-1-u2-X18"},{"t":"받아쓰기 시험 보기","mis":"SO4-1-u2-X18"},{"t":"줄넘기 기록 재기","mis":"SO4-1-u2-X18"}],"explanation":["옛 생활 모습이에요.","그림·만화도 돼요.","만화로 그리기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#6','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C7',1,'mc','auto','일지 ⑤에서 의병들을 기억하려고 세운 곳은 어디인가요?',ARRAY['SO4-1-u2-X21','SO4-1-u2-X22']::text[],false,'{"seq":6,"concept":"SO4-1-u2-C7","difficulty":1,"kind":"mc","stem":"일지 ⑤에서 의병들을 기억하려고 세운 곳은 어디인가요?","options":[{"t":"㉯ 바람골 의병 기념관","correct":true},{"t":"㉮ 바람골 역사 박물관","mis":"SO4-1-u2-X21"},{"t":"㉰ 바람골 옛 집터 유적지","mis":"SO4-1-u2-X21"},{"t":"바람골 시장","mis":"SO4-1-u2-X22"}],"explanation":["의병이에요.","기억해요.","㉯예요."],"asset":{"type":"passage","lines":["㉮ 바람골 역사 박물관 — 옛 농기구와 그릇을 모아 전시한다.","㉯ 바람골 의병 기념관 — 이 고장에서 나라를 지킨 의병들을 기억하려고 세웠다.","㉰ 바람골 옛 집터 유적지 — 아주 오래전 사람들이 살던 움집 자리가 남아 있다."],"title":"일지 ⑤ — 바람골 역사 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#7','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C8',1,'mc','auto','일지 ⑥의 조사 방법 가운데 책이나 기록물을 찾아보는 것은 무엇인가요?',ARRAY['SO4-1-u2-X09','SO4-1-u2-X28']::text[],false,'{"seq":7,"concept":"SO4-1-u2-C8","difficulty":1,"kind":"mc","stem":"일지 ⑥의 조사 방법 가운데 책이나 기록물을 찾아보는 것은 무엇인가요?","options":[{"t":"문헌 조사","correct":true},{"t":"답사","mis":"SO4-1-u2-X09"},{"t":"면담 조사","mis":"SO4-1-u2-X09"},{"t":"사진전","mis":"SO4-1-u2-X28"}],"explanation":["책과 기록물이에요.","문헌이에요.","문헌 조사예요."],"asset":{"type":"passage","lines":["조사 주제 — 옛 집터에 살던 사람들","조사 방법 — 문헌 조사, 답사, 면담 조사","주의할 점 — 보호자와 함께 가기, 믿을 만한 정보인지 확인하기","(아래는 답사를 다녀온 뒤 쓴 보고서)","알게 된 점 — 땅을 파고 지붕을 덮은 움집에 살았다.","느낀 점 — 추위를 이기려 한 옛사람들의 슬기가 놀라웠다."],"title":"일지 ⑥ — 조사 계획서와 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#8','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C10',1,'mc','auto','우리 지역의 역사를 보존하는 노력이 아닌 것은 무엇인가요?',ARRAY['SO4-1-u2-X30']::text[],false,'{"seq":8,"concept":"SO4-1-u2-C10","difficulty":1,"kind":"mc","stem":"우리 지역의 역사를 보존하는 노력이 아닌 것은 무엇인가요?","options":[{"t":"돌다리 돌을 기념으로 가져가기","correct":true},{"t":"돌다리 고치기","mis":"SO4-1-u2-X30"},{"t":"농악 공연 행사 열기","mis":"SO4-1-u2-X30"},{"t":"돌다리 둘레 청소하기","mis":"SO4-1-u2-X30"}],"explanation":["지키는 노력이에요.","가져가면 훼손이에요.","가져가기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#9','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C1',2,'match','auto','일지 ①의 국가유산과 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u2-C1","difficulty":2,"kind":"match","stem":"일지 ①의 국가유산과 종류를 알맞게 이으세요.","pairs":[{"l":"바람골 옹기","r":"문화유산"},{"l":"바람골 농악","r":"무형유산"}],"mis":"SO4-1-u2-X03","explanation":["옹기는 항아리예요.","농악은 춤과 가락이에요.","형태로 나눠요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#10','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C2',2,'mc','auto','국가유산이 유네스코 인류무형문화유산에 오르면 무엇을 뜻하나요?',ARRAY['SO4-1-u2-X08']::text[],false,'{"seq":10,"concept":"SO4-1-u2-C2","difficulty":2,"kind":"mc","stem":"국가유산이 유네스코 인류무형문화유산에 오르면 무엇을 뜻하나요?","options":[{"t":"세계가 그 가치를 인정했다는 뜻이에요","correct":true},{"t":"곧 사라진다는 뜻이에요","mis":"SO4-1-u2-X08"},{"t":"값이 비싸진다는 뜻이에요","mis":"SO4-1-u2-X08"},{"t":"우리나라만 안다는 뜻이에요","mis":"SO4-1-u2-X08"}],"explanation":["세계가 알아보았어요.","가치를 인정해요.","함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
