INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#12','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C5',2,'mc','auto','조상들의 생활 모습을 표현하면 좋은 점을 바르게 고른 것은 무엇인가요?',ARRAY['SO4-1-u2-X19','SO4-1-u2-X32','SO4-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO4-1-u2-C5","difficulty":2,"kind":"mc","stem":"조상들의 생활 모습을 표현하면 좋은 점을 바르게 고른 것은 무엇인가요?","options":[{"t":"국가유산을 알리고 가치를 이해하며 자긍심을 가져요","correct":true},{"t":"재미있기만 하고 배우는 것은 없어요","mis":"SO4-1-u2-X19"},{"t":"국가유산이 저절로 보존돼요","mis":"SO4-1-u2-X32"},{"t":"조사를 하지 않아도 돼요","mis":"SO4-1-u2-X17"}],"explanation":["알려요.","이해해요.","자긍심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
