INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#14','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C8',2,'blank','auto','보고서에는 찾은 내용을 그대로 베끼지 않고 필요한 것을 골라 (    ) 정리해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X14','SO4-1-u2-X10']::text[],false,'{"seq":14,"concept":"SO4-1-u2-C8","difficulty":2,"kind":"blank","stem":"보고서에는 찾은 내용을 그대로 베끼지 않고 필요한 것을 골라 (    ) 정리해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"내 말로","correct":true},{"t":"친구 글 그대로","mis":"SO4-1-u2-X14"},{"t":"지어낸 말로","mis":"SO4-1-u2-X10"},{"t":"아무렇게나","mis":"SO4-1-u2-X14"}],"explanation":["베끼지 않아요.","골라요.","내 말로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#15','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C9',2,'match','auto','일지 ⑦의 자료와 만드는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO4-1-u2-C9","difficulty":2,"kind":"match","stem":"일지 ⑦의 자료와 만드는 방법을 알맞게 이으세요.","pairs":[{"l":"2모둠 동영상","r":"촬영한 뒤 편집하기"},{"l":"3모둠 안내 책자","r":"넣을 내용을 정하고 사진 붙이기"}],"mis":"SO4-1-u2-X28","explanation":["찍고 편집해요.","내용을 정해요.","이어요."],"asset":{"type":"passage","lines":["1모둠 — 의병 이야기 신문(인터뷰 칸)","2모둠 — 옛 집터 소개 동영상","3모둠 — 옹기 안내 책자","4모둠 — 돌다리 사진전(누리집 사진은 출처 표시)"],"title":"일지 ⑦ — 우리 반 역사 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#16','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C10',2,'blank','auto','우리 지역의 역사는 우리만의 것이 아니라 (    )을/를 위한 것이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X31','SO4-1-u2-X05','SO4-1-u2-X32']::text[],false,'{"seq":16,"concept":"SO4-1-u2-C10","difficulty":2,"kind":"blank","stem":"우리 지역의 역사는 우리만의 것이 아니라 (    )을/를 위한 것이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"다음 세대","correct":true},{"t":"어른들","mis":"SO4-1-u2-X31"},{"t":"관광객의 돈","mis":"SO4-1-u2-X05"},{"t":"옛날 사람","mis":"SO4-1-u2-X32"}],"explanation":["물려줘요.","뒤에 올 사람이에요.","다음 세대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#17','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C1',3,'mc','auto','일지 ①의 옹기와 장 담그기를 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X03','SO4-1-u2-X01']::text[],false,'{"seq":17,"concept":"SO4-1-u2-C1","difficulty":3,"kind":"mc","stem":"일지 ①의 옹기와 장 담그기를 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옹기는 형태가 있는 문화유산이고, 장 담그기는 솜씨로 전해 오는 무형유산이에요","correct":true},{"t":"둘 다 형태가 있는 문화유산이에요","mis":"SO4-1-u2-X03"},{"t":"둘 다 국가유산이 아니에요","mis":"SO4-1-u2-X01"},{"t":"옹기는 무형유산이고, 장 담그기는 문화유산이에요","mis":"SO4-1-u2-X03"}],"explanation":["옹기는 항아리예요.","장 담그기는 솜씨예요.","종류가 달라요."],"asset":{"type":"passage","lines":["바람골 돌다리 — 냇물 위에 큰 돌을 놓아 만든 다리","바람골 옹기 — 흙을 빚어 구운 커다란 항아리","바람골 농악 — 꽹과리·장구를 치며 함께 추는 춤과 가락","마을 줄다리기 — 해마다 마을 사람들이 편을 나누어 하는 놀이","장 담그기 — 콩으로 된장·간장을 담가 온 솜씨"],"title":"일지 ① — 바람골 국가유산 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#18','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C4',3,'ox','auto','일지 ④의 ㉢을 쓰려면 ㉠·㉡ 같은 사실을 먼저 조사해야 해요.',ARRAY['SO4-1-u2-X13']::text[],false,'{"seq":18,"concept":"SO4-1-u2-C4","difficulty":3,"kind":"ox","stem":"일지 ④의 ㉢을 쓰려면 ㉠·㉡ 같은 사실을 먼저 조사해야 해요.","answer":"O","reason_options":[{"t":"가치는 특징을 바탕으로 헤아리기 때문에","correct":true},{"t":"가치는 사실과 관계없이 정하기 때문에","mis":"SO4-1-u2-X13"}],"mis":"SO4-1-u2-X13","explanation":["가치예요.","특징이 바탕이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#19','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C6',3,'mc','auto','바람골 옹기 안내판의 부탁 줄에 넣기 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u2-X30','SO4-1-u2-X05']::text[],false,'{"seq":19,"concept":"SO4-1-u2-C6","difficulty":3,"kind":"mc","stem":"바람골 옹기 안내판의 부탁 줄에 넣기 알맞은 말은 무엇인가요?","options":[{"t":"옹기를 두드리거나 올라타지 말아 주세요","correct":true},{"t":"옹기를 기념으로 가져가세요","mis":"SO4-1-u2-X30"},{"t":"옹기 값은 얼마예요","mis":"SO4-1-u2-X05"},{"t":"옹기에 이름을 새겨 보세요","mis":"SO4-1-u2-X30"}],"explanation":["지켜 줄 점이에요.","훼손하지 않아요.","두드리지 말아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#20','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C7',3,'mc','auto','바람골 의병 기념관이 다른 고장이 아니라 바람골에 있는 까닭을 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u2-X23']::text[],false,'{"seq":20,"concept":"SO4-1-u2-C7","difficulty":3,"kind":"mc","stem":"바람골 의병 기념관이 다른 고장이 아니라 바람골에 있는 까닭을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"의병들이 바람골과 인연이 깊어 그곳에서 기억하려고","correct":true},{"t":"바람골 땅이 넓어서","mis":"SO4-1-u2-X23"},{"t":"바람골에 사람이 많아서","mis":"SO4-1-u2-X23"},{"t":"기념관은 아무 곳에나 짓기 때문에","mis":"SO4-1-u2-X23"}],"explanation":["의병이에요.","바람골과 인연이 있어요.","그곳에서 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#21','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C9',3,'mc','auto','옹기를 처음 보는 사람이 집에 가져가 천천히 읽으며 알 수 있게 하려면 어떤 자료가 가장 알맞을까요?',ARRAY['SO4-1-u2-X28','SO4-1-u2-X27','SO4-1-u2-X18']::text[],false,'{"seq":21,"concept":"SO4-1-u2-C9","difficulty":3,"kind":"mc","stem":"옹기를 처음 보는 사람이 집에 가져가 천천히 읽으며 알 수 있게 하려면 어떤 자료가 가장 알맞을까요?","options":[{"t":"안내 책자","correct":true},{"t":"동영상","mis":"SO4-1-u2-X28"},{"t":"출처 없는 사진전","mis":"SO4-1-u2-X27"},{"t":"급식표","mis":"SO4-1-u2-X18"}],"explanation":["집에 가져가요.","천천히 읽어요.","안내 책자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#22','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C10',3,'mc','auto','일지 ⑧의 문제가 계속되면 일어날 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u2-X32','SO4-1-u2-X31']::text[],false,'{"seq":22,"concept":"SO4-1-u2-C10","difficulty":3,"kind":"mc","stem":"일지 ⑧의 문제가 계속되면 일어날 일로 알맞은 것은 무엇인가요?","options":[{"t":"농악과 돌다리가 다음 세대에 전해지지 못해요","correct":true},{"t":"농악과 돌다리가 저절로 새것이 돼요","mis":"SO4-1-u2-X32"},{"t":"아무 일도 일어나지 않아요","mis":"SO4-1-u2-X32"},{"t":"어른들만 잘 지키면 되니 괜찮아요","mis":"SO4-1-u2-X31"}],"explanation":["이을 사람이 줄어요.","다리가 상해요.","전해지지 못해요."],"asset":{"type":"passage","lines":["바람골 농악을 이을 젊은 사람이 줄고 있다.","돌다리 돌 몇 개가 떠내려가 다리가 상했다.","군에서는 돌다리를 고치고, 농악 공연 행사를 열기로 했다.","우리 반은 돌다리 둘레 청소와 농악 알리기를 맡기로 했다."],"title":"일지 ⑧ — 바람골 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#23','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C4',4,'essay','teacher','일지 ④의 ㉠~㉣을 특징과 가치로 나누고, 특징과 가치를 나누어 정리하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u2-C4","difficulty":4,"kind":"essay","stem":"일지 ④의 ㉠~㉣을 특징과 가치로 나누고, 특징과 가치를 나누어 정리하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 특징은 ㉠, ㉡이고 가치는 ㉢, ㉣이에요. 특징은 사실대로, 가치는 특징을 바탕으로 헤아려 나누어 정리하면 옹기를 사실대로 알고 그 소중함까지 느낄 수 있어요.","scoring_points":["특징 ㉠·㉡과 가치 ㉢·㉣으로 나누었는가","특징은 사실·가치는 추론임을 썼는가","나누어 정리하면 좋은 점을 썼는가"]},"explanation":["나눠요.","차이를 써요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["㉠ 바람골 옹기는 어른 허리쯤 오는 높이다.","㉡ 옹기 겉에 손가락으로 그은 물결무늬가 있다.","㉢ 음식을 오래 두고 먹게 한 조상들의 슬기가 담겼다.","㉣ 물결무늬에서 소박한 아름다움을 느낄 수 있다."],"title":"일지 ④ — 옹기 조사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#24','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C5',4,'essay','teacher','바람골 농악이나 장 담그기 가운데 하나를 골라, 공연·가상 일기·역할놀이 가운데 한 방법으로 어떻게 표현할지 쓰고 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u2-C5","difficulty":4,"kind":"essay","stem":"바람골 농악이나 장 담그기 가운데 하나를 골라, 공연·가상 일기·역할놀이 가운데 한 방법으로 어떻게 표현할지 쓰고 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 장 담그기를 역할놀이로 표현할 거예요. 할머니와 손주가 되어 콩을 삶고 메주를 띄워 된장을 담그는 장면을 연기해요. 장 담그는 차례를 미리 조사해 역사적 사실을 토대로 표현해요.","scoring_points":["국가유산과 표현 방법을 골랐는가","어떻게 표현할지 구체적으로 썼는가","사실을 토대로 한다는 지킬 점을 썼는가"]},"explanation":["고르세요.","표현을 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u2_review_d#25','soc',4,1,'u2','','g4_1_soc_u2_review_d','unit_review','SO4-1-u2-C6',4,'essay','teacher','2단원에서 배운 것 가운데 국가유산·조사·역사 장소·보존에서 세 가지를 넣어, 바람골을 소개하는 글을 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u2-C6","difficulty":4,"kind":"essay","stem":"2단원에서 배운 것 가운데 국가유산·조사·역사 장소·보존에서 세 가지를 넣어, 바람골을 소개하는 글을 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 바람골에는 형태가 있는 돌다리와 옹기, 형태가 없는 농악 같은 국가유산이 있어요. 바람골 역사 박물관과 옛 집터 유적지에 가면 옛사람들의 생활을 알 수 있어요. 돌다리를 고치고 농악을 알리며 우리 모두 바람골의 역사를 보존하고 있어요.","scoring_points":["세 가지를 넣었는가","일지 내용과 맞게 썼는가","세 문장으로 바람골을 소개했는가"]},"explanation":["세 가지를 골라요.","일지를 떠올려요.","소개 글을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
